local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["140:1790510609"]="마지막 공격이 되고 있어 도망갈 곳이 없어$B$B와일드햄어!!"
rows["140:183819076"]="하수인들아! 내 형제와 비룡을 새로운 보금자리로 모시거라. 저 비룡을 살아 있는 채로 데려가야 한다. 여왕을 써먹을 특별한 계획이 있으니 말이다."
rows["140:1877283913"]="오크의 상태에 민감하게 반응해봐 난 힘든 날들을 보내고 있어"
rows["140:1909969605"]="내가 당신한테 일렉스 한 명을 맡길래?"
rows["140:192321553"]="고대 신들이 나타나고 있습니다. 어둠의 물결이 그들의  ⁇ 은 위를 통해 성전으로 향합니다. 우리는 그 측면을 더 많은 시간을 가져야 합니다."
rows["140:193779231"]="내 꿈의 역할은 거머리들을 지키는 게 아니지만, 그 돈도 많이 들어요."
rows["140:1940241608"]="젠타르들은 망할 놈들이야, 넌 네 거래를 지켜냈어"
rows["140:1951279616"]="난 여러 캡틴을 알고 있어"
rows["140:199939963"]="대영주님께서 상대하시는 자는 가장 교활하고 지능적이며 무자비한 마음을 지닌 존재입니다."
rows["140:2036852738"]="클라우드런러 랭은 판다리아에서 비행을 가르칠 수 있어. 그는 메인 테라스에 구름 뱀을 타고 다니고 있어요."
rows["140:2113244658"]="마술인들이 마술관에서 모여서 마술관에서 마술관으로 모여서"
rows["140:2113510870"]="그 다음 중간층에 있는 베나의 알케미아로 가서 베나와 직접 이야기해봐요. 그녀는 술조기의 예술을 익히는데 도움을 줄 수 있을 겁니다."
rows["140:233019835"]="린이 숨겨진 마스터를 찾으면 훈련이 계속될 수 있어$b$b케인-켄은 먼저 슬픔에 빠진 사람들을 도와야 합니다."
rows["140:254972269"]="폭풍이 무슨 원인을 하는지 알아냈어요. 이 미묘한 젠다라리는 얼음 트롤들이"
rows["140:271794977"]="프로스트울프 포크를 재건하기 위해 소량의 물품이 있어"
rows["140:285154358"]="이 곳은 그림자 협의회 작전 전력 기지로 발전되길 바랍니다"
rows["140:292956122"]="이 망할 물건이 이제 막 작동하고 있습니다. 이것은 당신이 마지막 Flame Leviathan을 싸웠던 코커스 끝까지 데려가야 합니다."
rows["140:335504883"]="하지만... 이 기계들 중 얼마나 많은 것들이 땅 아래 숨겨져 있고, 모구의 어두운 비밀에 대해 우리가 잘 알지 못하는 것이 얼마나 많은가?"
rows["140:345231911"]="노그, 나보다 똑똑해, 너 가서 노그 툰드가 보낸다고 말해"
rows["140:34538153"]="내 밴드와 트롤들이 우리를 잡아 버렸어$B$B여기서 나가면 원하는 걸 줄게"
rows["140:364423410"]="엄마가 낯선 사람하고 이야기하지 말랬지만, 친절하게도 절 구해 주셨으니까... 제가 납치되기 전에 찾은 멋진 물건을 드릴게요."
rows["140:373819287"]="난 네 적이 아니야 넌 그보다 더 강해 어쩌면 네가 옳고 어쩌면 희망도 있어"
rows["140:403905574"]="메아리 섬을 떠나면서, 너희들은 고향을 버리고 선조들의 로아들을 버렸다. 로아들이 그런 대접을 받고 기뻐할 리가 있겠느냐?"
rows["140:423189413"]="안녕, 귀여운 옷이 잘 생겼어$b$b레드 크레인의 길을 찾았어?"
rows["140:429296785"]="넌 내 경주에서 실패했어 아제로스당신 때문에, 당신이 알고 있는 모든 사람들이 끔찍한 고통스럽게 죽을 것입니다."
rows["140:455676246"]="싸인지, 좀 더  ⁇ 을 거야, 또 좀 더!"
rows["140:477422100"]="이곳에 가만히 누운 채로 네놈의 손에 죽지는 않을 것이다! 날 죽이고 싶거든 숨 쉴 자격부터 구해봐라!"
rows["140:485022604"]="오, 구린속. 언제나 제일 좋아했어. 썩은얼굴 다음으로 말이야. 좋은 소식이라면 네가 가스를 많이 남겨서 내가 맛볼 수 있다는 거야!"
rows["140:509493666"]="제이드 뱀은 거의 완성됐어 그 말은 몇 달 동안 응원하고 축하하며 잠을 자고 맥주 만들어내는 걸 알겠어"
rows["140:510943225"]="좋다, 고양이야. 어차피 언젠가는 닥칠 네 죽음을 더는 미룰 필요가 없겠다. 이 얼간이부터 처리하고 나서 바로 너를 상대해 주마."
rows["140:511427574"]="델라니엘은 팔콘윙 스퀘어 남동쪽에서 숙소를 잘 관리하고 있어 좋은 음식, 좋은 와인, 부드러운 침대가 더 이상 무엇을 요구할 수 있을까?"
rows["140:513213240"]="동쪽의 비터링에서 큰 일이 일어나고 있습니다.$B$B무슨 일이든, 곧 끝나고 더 좋은 곳으로 다시 배치되길 바랍니다."
rows["140:532195560"]=" ⁇ , 토끼, 그리고 함께 여행하는 조랑이. 그건 매일 볼 수 없는 일이야. 상관없어, 난 오늘 밤 포니션으로 식사를 할거야!"
rows["140:577274627"]="우리 වෙනුවෙන් 많은 일을 해왔어요. 중요한 임무에 왔지만, 시간 동굴로 갈 수 있으면 기꺼이 데려갈게요."
rows["140:627987227"]="새 고기 한 배가 더 있어 사우르보스, 마지막 대대로 내 차에 시체로 안 올 수 있기를 바랍니다"
rows["140:635813543"]="빨리 싸워, 너 둘 다 거칠고 천천히, 내가 널 물에 던지고,"
rows["140:656935189"]="자오는 우리 민족의 진정한 챔피언이었는데 그의 이야기는 셰가 오염시킨다는 것은 얼마나 슬픈지 알 수 있습니다."
rows["140:657932879"]="이제 비전 없이 힘의 한계를 이해하실 수 있기를 바랍니다. 세상을 바꾸는 것은 다른 일이지만, 옳은 일을 하는 것은 전혀 다른 일입니다."
rows["140:661796972"]="다시 집합해, 우리가 이점을 누르면, 대장군이 라저힐을 강화하기 전에, 우리는 혁명을 위해, 바렌스로 가는 길을 막아야 합니다."
rows["140:679071394"]="때가 되면 그 안에 담긴 빛과 희망이 이 힘의 샘뿐만 아니라... 어쩌면 한 나라의 영혼까지 다시 태어나게 할 것이다."
rows["140:679939395"]="처음으로, 지구 반지와 센리온 원은 연합하여 이 큰 나무를 회복할 것이며 이로써 전체 아제로스을 치유할 것입니다."
rows["140:68924970"]="테일드라시일 해안의 물고기 들 은 꽤 크고 강하다. 소문 들 은 우리 새 세계 나무 가 빠르게 성장 하는 것 이 원인 이라고 합니다."
rows["140:709105426"]="네놈들의 노력은 수포로 돌아갔다! 이미 세계수의 힘을 빨아들이기 시작했다. 이제 세계의 심장은 영원히 박동을 멈추리라!"
rows["140:740218364"]="물론 우리가 하는 모든 전투와 함께 레이저 힐에서 초급 훈련자가 있습니다."
rows["140:743469281"]="설마 아니겠지. 네놈의 건방진 코를 납작하게 만들고 나서, 네 시체를 성벽에 매달아 다른 '영웅'들의 본보기로 삼겠다!"
rows["140:767624752"]="이 깃발은 경주 경로를 표시합니다. 만약 길을 잃으면, 이 깃발을 안내로 사용할 수 있습니다."
rows["140:773873958"]="네루비안은 노스렌드의 얼어붙은 황무지 아래에 왕국을 건설했다. 그런데, 멍청하게도 넌 그 왕국 위에 이것저것 세우더군. 바로 내 왕국 위에 말이다."
rows["140:798699441"]=" ⁇ 진수와 대화를 나누고 치료 방법을 찾아야 하고, 그러기 위해서는 네 개의 원자 정신이 돌아가야 합니다."
rows["140:802878628"]="다크월 페어 열릴 때, 아웃랜드에 테로카르 숲에 위치할 것입니다. 우리는 Shattrath 시티 남쪽에 우리 텐트를 지을 것입니다!"
rows["140:812105290"]="오, 예, 직접 본 적 없지만 가끔은 멀리서 들어요."
rows["140:83238289"]="제 마술을 지켜봐 주셔서 감사합니다! 내일 마술에도 지금과 같이 때묻지 않은 관심 보내 주신다면 정말 고맙겠습니다."
rows["140:837291945"]="내가 전에 껍질 한 덩어리를 줬지?$B$B어쨌든, 그 악의  ⁇ 돌이 똥구리의 무자비한 손목에서 구출되어서 기쁘네요!"
rows["140:906437300"]="내 주인은 오십니다. 난 전사들의 군대의 일원이에요."
rows["140:909115876"]="어떻게 용기가 있어 왕을 포로로 잡는 거냐?$B$B우리는 스톤헤어트를 되찾고 앞으로 이동해 그들의 집에서 돌의 트로그를 짓밟을 것입니다!"
rows["140:934078144"]="만약 여기서 탈출구가 있다면, 우리가 그것을 이용해야 할 겁니다."
rows["140:93470817"]="얌전히 따라와 줬으면 좋겠다만, 우리 둘 다 그런 일은 일어나지 않으리란 걸 알지. 여기 있는 작은 친구가 네가 내세에 편안하게 발을 들이게 도와줄 게다."
rows["140:939126559"]="내가 애완동물을 보내서 더 마실 수 있어"
rows["140:951634550"]="내가 이 세상의 악의 힘을 정말로 정복하고, 내가 지휘하는 악마의 힘은"
rows["140:965586532"]="샤먼, 최근에는 트롤 신비주의자가 마을에 와서"
rows["140:980389821"]="이건 시간 낭비야, 내와 네! 그래엄 반 타렌을 만나러 가!"
rows["141:1000901825"]="정해진 시간에, 그들은 불의 원자들을 풀어내고 도시를 불로 삼아 주인의 영광스러운 복귀를 준비할 것이다!"
rows["141:1004664925"]="아브로와 해마를 만드는 법을 배우고 있는 사람?"
rows["141:1010251537"]="무쇠 감시자는 세월이 감에 따라 늘어난 부식으로 행동이 둔해졌습니다. 발을 재빨리 놀리면 그가 당신을 능가하지 못할겁니다. 당신은 스톰하트 왕의 총애를 얻은 분입니다. 실망시키지 마십시오."
rows["141:1072836528"]="'죽는 사람'은 '원자'의 물질로 만들어져 있다. '예방'을 어떻게 희망할 수 있는가?"
rows["141:1112377208"]="지금 당장 그 일에 관여하고 싶지 않다고 말해줘"
rows["141:115264765"]="만약 우리를 배신한다면, 당신은 탈출할 수 없습니다. 나는 당신의 몸을 너무 천천히  ⁇ 을 것입니다"
rows["141:117536037"]="해방된 노예들과 대화를 나누는 것만으로도 머리가 아프게 되죠$B$B그들은 불협화와 리듬으로 선을 밟습니다.\010"
rows["141:1188665059"]="월 축제의 가장 큰 축제는 무롱라드에서 열립니다. 드루이드는 썬더 블러프의 고령 상승에서 당신을 데려갈 것입니다."
rows["141:1268338281"]="엘룬의 빛이여! 에레다르로군! 이 저주받은 악마들, 내게 무슨 짓을 한 거지? 내게는 동료가 있다. 지금까지 그랬던 것처럼 우린 끝까지 너희들과 싸우겠어! 난..."
rows["141:1276997636"]="이 잘 얻은 맥주 맛을 즐기세요. 이 요리법은 10천년 넘게 우리 가족에서 왔어요. 한때 원숭이 왕 스스로 즐겼다고 합니다."
rows["141:1294212845"]="그는 병든 사람들을 착각시켜 그들의 땅을 되찾을 수 있다고 생각하게 해 자신의 독성적인 본질으로 피를 중독시켰습니다."
rows["141:1331723673"]="이 책을 가져와 의식을 실천하라. 그것은 완벽하게 수행되어야 한다, 그렇지 않으면 원자들은 적절한 시간에 포털을 떠나지 않을 것이다."
rows["141:1391171191"]="우린 치열한 전투를 겪을 거야 내가 지나갈 때, 너는 그  ⁇ 에 맞서야 돼"
rows["141:1485322050"]="그 순간 네가 내가 아는 것만큼 잘 알잖아 오그리마그는 가장 행복한  ⁇ 꾼이 아니겠지만 어쨌든 당신을 도와줄 겁니다."
rows["141:1491987558"]="베티 퀸과 얘기해봐, 그쪽 계단 옆에 서 있어."
rows["141:149424637"]="그리고 육아, 잠시 생각 해봐요. 이 장소에서 바위들이 당신을 둘러싸고 있다는 걸."
rows["141:1506128923"]="침입자들을 사랑하지 않네, 스톤모더 하지만 이 육아들은 크림슨 엑스페언스에서 더러운 것을 깨끗하게 하기 위해 최선을 다했습니다. "
rows["141:1559371082"]="셰퍼는 그림자의 절벽에서 과일의 판매자가 있던 강릉의 절벽으로 가게를 옮겼습니다."
rows["141:1566944711"]="얼라이언스의 힘을 보라! 공포의 여군주 오닉시아의 목이 잘려 홍예문에 걸려 있다! 용을 처치한 영웅들의 환성에 함께 기쁨의 춤을 추자!"
rows["141:1578844558"]="또 다른 비전! 고엘을 보고 있지만... 그... 저야. 내가 그의 가장 깊은 욕망이었나?"
rows["141:1594384367"]="일단 샤만이 되면 다시 돌아가지 못해요$B$B저는 불의 원자료의 유용성을 완전히 과소평가했습니다. 또한 쉽게 규율합니다. 그냥 물을 더하십시오."
rows["141:1618918607"]="제가 말해야 할 것은, 포세이큰는... 맥주라는 것에 대해 이상한 맛을 가지고 있지만, 그들은 친구들을 위해 그것을 준비하지 않은 것 같다고 생각합니다."
rows["141:163203282"]="불과 힘으로 전쟁에 필요한 금속을 형성한다고 들었습니다. 저는 물의 압력과 밀도를 마스터함으로써 이 일을 할 수 있습니다."
rows["141:1653828704"]="|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t 포위자 블랙파이더는 당신을 마주하고 준비한다 |cFFFF0000|Hspell:143266|h[론칭 Sawblade]|h|r!"
rows["141:1711397841"]="보물 상자가 있어? 보여줘요! 자, 그림자의 틈에서 잔도잔을 찾아라."
rows["141:1718394799"]="다른 구석에  ⁇ 은 녹색의 거칠고 멍청한 괴물들이 있습니다."
rows["141:1720653189"]="파다리아에서 일어나는 모든 질병이나 악에 대해 항상 완벽한 보충 치료가 있습니다."
rows["141:1730203765"]="여기까지 온다면 마나포르지 아라 근처에 모험을 할 용기가 있어야 합니다.$B$B이리 오기 전에 사거나 팔으려요?"
rows["141:1738692905"]="사라 핀클스위치라는 전투 훈련자가 있습니다. 그녀는 주 테라스에서 애완동물을 훈련합니다.$B$B지도에 위치를 표시해 줄게요"
rows["141:1762066143"]="전 세계 파괴자의 종들, 추종자, 자녀들아, 이제 내가 너희를 부르짖는다. 우리 아버지의 성당은 침입자들을 죽여라!"
rows["141:1803629208"]="이 숲은 내 일부인 것처럼 알고 있지만, 그것으로부터 배울 것이 많고 위험도 많이 있다는 것을 알아야 합니다."
rows["141:1806521325"]="$p우리 사람들은 평생을 이 큰 거북이인  ⁇ 진수에서 살았지만 수백 년 동안 아무도 그와 대화하지 않았습니다."
rows["141:1811484487"]="-- 안녕하세요, $P. 이 단위 뒤에 터널을 아래로 진행 부탁드립니다. 그의 높고 힘 그랜드 마지스터 로마스 당신의 도착을 기다리고 있습니다. -"
rows["141:1867682304"]="재판의 규칙은 간단합니다. 이 표적 인형들은 폼 폭탄이 장착되어 있습니다. 그 중 하나라도 폭발하면, 당신의 시험이 끝납니다."
rows["141:189421625"]="다친 사람들을 위해 최선을 다해 왔어요\010내가 부상자를 지키고 있어요... 더 나은 계획이 없다면?"
rows["141:1894442526"]="승리자는 성채를 공격할 때 그에 걸맞은 자리를 얻으리라. 우리는 악에 굳건히 맞설 것이고, 아서스는 쓰러지리라!"
rows["141:1913846602"]="바로 그렇소. 둘의 유사점이 꽤 흥미롭더군. 게다가 슈할로건 엘프건, 드루이드라면 누구나 무샤의 빛을 불러낸다는 걸 모두 알고 있지 않소."
rows["141:1924622186"]="당신은 끔찍한 역경에 직면해 진정한 용기와 기사도를 보여줬습니다."
rows["141:1966693071"]="이 곳은 매우 특이한 곳입니다.$B$B레이 라인을 복구하기 위해 내가 전달하는 마법은 내 몸을 찢어 버릴 거야"
rows["141:2003915017"]="가장 큰 도전이 눈앞에 있습니다. 지맥 수호자 에레고스는 엄청난 힘을 지닌 푸른용입니다. 에레고스는 꼭대기 고리 위를 선회하고 있을 것입니다."
rows["141:2055310937"]="도시에는 두 개의 은행이 있습니다. 무역 구역의 카운팅 하우스 스톰윈드 및 Dwarven 구역의 스톰윈드 로얄 은행."
rows["141:2056311629"]="바로 그날, 우리는 올빼미야수를 얻게 되었노라. 엘룬께서는 사나운 올빼미야수를 수호자로 보내시어 모든 성소를 지키도록 하셨다."
rows["141:2117837022"]="제1관리자? 어디서 들은 말이지... 아! 우리 할아버지의 수염을 걸지! 로켄이 아제로스의 제1관리자야! 로켄이 죽어서 이렇게 된 거라고!"
rows["141:2129852431"]="쇼에게 증명해줬어 네가 필요하면 널 지켜줄 거라고 했잖아"
rows["141:2138075178"]="부상을 입고 앉아 형제들이 싸우는 걸 보고 있는 것은 참을 수 없을 정도로 힘들지만, 내가 죽기보다 살아있다는 건 더 소중하다는 것을 이해한다."
rows["141:2143015686"]="너 누구인지 모르겠어 왜 날 따라다니는 건지 모르겠지만 내가 배를 타고 혼자 있고 싶어"
rows["141:222100178"]="난 그들의 고통에 대해 맹목적인게 아니야, 로완. 하지만 우리의 임무는 재앙이 가져온 결과를 알아내는 것이다. 아제로스 그 자체는 고통입니다."
rows["141:313085203"]="어쨌든, 타크타크는 캠프에서 많은 일을 듣고 있습니다."
rows["141:373425943"]="겨울 베일 축제처럼 보이나요? 색채의 빛, 장식품? 아니?"
rows["141:394436462"]="내가 그가 훔친 옥수수를 압수하고, 도둑질이 멸망의 길이라고 경고하고,"
rows["141:40341230"]="다음엔 내가 본 가장 약한, 더 못생긴, 가장 미묘한 전투기야."
rows["141:409708851"]="당신들의 정치는 제 관심사 아닙니다. 당신의 호드이 장소의 거룩함을 무시했습니다. 당신은 더 이상 여기에 환영받지 않습니다. 즉시 떠나십시오!"
rows["141:423801306"]="알테락밸리 가자면 카트라 블러드스나르를 만나보게 될 거야"
rows["141:431646209"]="시네스트라여, 난 이번 일을 필요 이상으로 더 질질 끌 생각이 없소. 당신은 시간을 계속 질질 끌어왔지 않소? 그러니 이제 용아귀 부족에 원하는 게 뭔지 말해보시오."
rows["141:441480100"]="내 텐, 내가 아예 알려주지 않는 소식이 있어요. 네 챔피언 베토드가 발하라스에서 반구에 쓰러졌어."
rows["141:499576073"]="내가 여기 있을 때, 저처럼  ⁇ 이 두 번이나 잡힐 확률은 얼마일까요?"
rows["141:509546079"]="지금 내 능력을 뛰어넘는 능력은 더 많은 것을 물어볼 수 있는 게 좋겠소 아이언포지!"
rows["141:512407567"]="적들의 피가 전쟁터에 흘려질 것이며, 위대한 원자들도 우리의 부르짖음을 듣고, 우리의 길을 막는 모든 사람을 꺾을 것이다."
rows["141:518263252"]="그녀의 이름은 나리스이고, 최근에까지만 해도 그녀는 검은 용 비행의 대표로 와임레스트 성전에 서 있었다."
rows["141:590299857"]="나도 만나서 반갑습니다. 티리온에서 임무를 맡고 있어요. 시간이 짧아요. 무롱라이드로 가는 게을리 좀 찾아볼까요?"
rows["141:605439914"]="장군의 형제인 스톰후프는 모든 힘을 모아 북풍으로부터 스톰피크스를 정복하기 위해 출발했습니다."
rows["141:638096156"]="알리스라의 운명 때문에 Fandral의 부패는 내가 악몽에서 겪었던 것보다 더 깊었습니다."
rows["141:64820258"]="정글 캔버스 위로 날아다닐 수 있어$b$bPterrordash을 사용하여 비행 속도를 일시적으로 증가시킵니다.$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t"
rows["141:658969843"]="그 상자의 내용은 매우 위험합니다. 그리고 그것은 안전한 보금자락에 속합니다. 어떤 부유한, 그러나 무지한 수집가의 손에 있지 않습니다!"
rows["141:665606438"]="만약 이길 수 없다면, 그들과 함께 해! 이 경우 선택의 여지가 없을 것이다."
rows["141:666723865"]="당신들의 능력은 내 손이 닿지 않는데 새로운 도전을 당할 때가 됐습니다. 타라단은 준비하는데 도움이 될 것입니다."
rows["141:70931146"]="저자, 그놈의 화염에 웅크리고 있는 놈을 보고 있어. 그 분노만 우리들을  ⁇ 으로 태울 수 있어!"
rows["141:719438012"]="만약 피 엘프들이 노스렌드로 가면, 결국 복수는 우리의 것이다! 리치 왕는 사랑하는 우리 도시 실버문에 대한 그의 행진을 후회할 것입니다!"
rows["141:733528228"]="명예의 요새에서 최근에 도착한 자들 말인데요, 그들은 용병들입니다! 녀석들이 문제를 일으키고 있습니다. 제가 녀석들을 좀 상대해야 하지 않을까요?"
rows["141:74918805"]="이 훈련장은 대부분의 훈련을 할 곳입니다. 오세요, 제가 여러분에게 가르치는 마스터들을 소개하겠습니다."
rows["141:754098079"]="우리는 추락할 수밖에 없었고, 테르마플러그는 방사선 뒤에 숨어있으며, 그의 동호인 크루시코그를 보내서"
rows["141:774563103"]="난 스스로의 뇌와 이 수술의 아름다움이라고 생각하기를 좋아합니다. 안지라는 근신이고 두번째 아름다움입니다.$B$B우리에겐 아름다움이 많아요"
rows["141:845863113"]="|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s는 |cFFF00000|Hspell:117283|h[청소수물]|h|r로 치유되고 있습니다! 그를 쫓아라!"
rows["141:848975507"]="이미 사랑을 찾았어, 사랑 표본을 줄 수 있어, 하지만 난 너에게 좋은 건 주지 않고 특별한 사람을 기다리고 있어"
rows["141:851577732"]="현재까지 알려진 일반적인 방법으로 복구에 성공할 확률은 0에 가깝습니다. 이론적인 방법이 분석될 때까지 대기하십시오."
rows["141:88843732"]="너 너 자신의 한계를 넘었다, 진도. 너 너보다 더 뛰어난 힘으로 놀아왔어. 내가 누군지 잊었나? 내가 할 수 있는 일을 잊었나?!"
rows["141:902082559"]="헤라지 수출이 증가 추세입니다. 이미 세관원을 매수해 놨으니 며칠 안으로 밀수품이 도착할 겁니다."
rows["141:909382216"]="잘했어,  ⁇ 이랑 어떻게 갈 거야?$B$B아무도 더 이상 슬립키크를 못 통과할 거야"
rows["142:1031406263"]="내가 말 안 돼, 하지만 네가 초대된 파티가 있을거야."
rows["142:1074394918"]="다음번에 만날 땐 단단히 준비해야 할 거라고 내가 말하지 않았는가? 난 내 힘으로 힐드스미트를 통과했고, 발키리온에서 훈련을 받았지. 그리고 지금 이 자리에 왔다. 자, 덤벼라!"
rows["142:1074559290"]="혀를 조심해, 벌레. 그 말로는 '스글라더'라고 부르지 않을거야. 아니면 저녁에 네 마음을 먹게 될 거야."
rows["142:1193245696"]="스팀위들 전투 경기는 곧 시작됩니다. 그들은 그들의 경기장에서 연습 경기를 개최하고 있지만 순위 싸움은 $4262d에서 시작합니다."
rows["142:1207581130"]="대영주 티리온 폴드링께서 마상시합 광장에 모인 청중 앞에서 연설하실 겁니다! 대영주님을 위해 연단까지 길을 내십시오!"
rows["142:1251195212"]="아, 이런 걱정스러운 생각. 우리 마지막 황제는 두려움의 그림자 속에서 살지 말라고 조언했다. 이제 왜 우리가 술을 마시고 축하하는 것을 좋아하는지 알 수 있습니까?"
rows["142:1255118744"]=" ⁇ 브루 디스틸리어를 이길 수 없어 쉬면 안 돼"
rows["142:1256748752"]="이 전쟁은 얼라이언스여기서 떠나기 전에 우리 사람들은 이 미친 괴물 기술을 최대한 잡을 거야"
rows["142:1301968371"]="자네는 목숨을 다해 스컬지와 싸울 것을 다짐했었네. 놈들이 로데론에 무슨 짓을 했는지 똑똑히 봤지 않나. 리치 왕은 자네에게서 모든 것을 앗아갔네!"
rows["142:1304994539"]="믿을 수가 없군요! 새로운 용사가 고뇌의 투기장을 접수했습니다!!! 어중이떠중이로 이루어진 어설픈 무리에게 도살자 블라도프가 지고 말았군요! 참으로 극적입니다!"
rows["142:1308448884"]="%s 열립니다. 그 내용이 매우 불쾌한 냄새로 감각을 공격합니다. 내부는 거대한 새 배설물과 많은 피를 볼 수 있습니다."
rows["142:1318159199"]="톨바라드에서의 승리 우리 몫입니다. 호드 공격이 마비되어 있는 동안, 우리는 즉시 자원을 모으고 섬을 안전하게 만들기 위해 여러분의 노력이 필요합니다!"
rows["142:1333947191"]="잠시만! 만약 네가 여기 있다면, 그리 머지 않은 미래에 내가 나를 돕는 네가 된다는 얘기잖아? 지금 우리 시간의 굴레에 갇힌 거야?"
rows["142:1337375778"]="가리온 교사와 얘기할 필요가 있다면, 타베타와 함께 집 안에 있을 거야."
rows["142:1337917128"]="지난 몇 년 동안 우리 땅, 집, 심지어 정체성까지 잃었습니다.$B$B이제 모든 것을 다시 가져갈 때가 됐어"
rows["142:1340632535"]="전쟁은 계속되었지만 위대한 지도자의 의지는 이미 꺾일 대로 꺾인 상태였습니다. 실리더스 전체가 실리시드와 그들의 화신인 퀴라지의 손아귀에 넘어가기 일보 직전이었던 것입니다."
rows["142:1367459270"]="마법사들은 그림자의 틈새에 있을 수 있습니다. 두 개의 입구가 있습니다. 하나는 힘과 지혜의 계곡 사이에 있고, 다른 하나는 드래그에 있습니다."
rows["142:1385723654"]="|TInterface\\Icons\\inv_weapon_shortblade_45.blp:20|t%s는 투입을 시작한다 |cFF9900CC|Hspell:109887|h[Arcane Infused Weapon]|h|r! 그녀의 공격을 피하십시오!"
rows["142:1393730631"]="우리의 주얼리 크래퍼 알레니아는 델라니엘의 창업장에서 발견될 수 있습니다."
rows["142:1408631259"]="이 발굴은 위태롭게 되어 있습니다. 탐험가들의 동맹은 우리가 남은 가치를 가져다가 제거하기를 원합니다."
rows["142:1422778900"]="사냥꾼에게 반려동물로 잡히면 얼마나 부끄러운지!$B$B이제 네가 무셀렉에서 나를 해방시켰으니 나로 나갈 수 있을 거야"
rows["142:1442902636"]="Zanzil는 모든 Stranglethorn을 씻어낼 군대를 만들고 있습니다! 호드... 모두 잔실에게 봉사할 거야!"
rows["142:1449815287"]="배틀메이든, 자네가 보병을 받을 거야."
rows["142:1471686144"]="|TInterface\\Icons\\inv_misc_eye_02.blp:20|t두루무는 그의 평가 눈의 캐스팅을 시작한다 |cFFFF0000|Hspell:133792|h[Lingering Gaze]|h|r!"
rows["142:1481248686"]="제 드루이드들과 내가 반역한 오크들에 의해 함락당했을 때 당신은 워시프 가로쉬를 전투로 재판하도록 도전했습니다. 그들의 죽음에 대해 책임을 묻기 위해서요, 장군님"
rows["142:1514574011"]="이제 해야 할 일은 기다려야 합니다. 대부분의 작물은 자라는 날부터 준비 됩니다.$B$B우리는 이렇게 번성 있는 계곡에 땅을 가지고 있는 행운이 아니지 않습니까?"
rows["142:1519083671"]="다시 생각하면 좋지는 모르겠어요$B$B내가 아는 걸 알고 우리 세상에 무슨 일이 일어날지 알고$B$B<그분은 떨고 침묵합니다.>"
rows["142:1522115086"]="이 수정의 힘만 있으면 나와 내 결사단은... 무적이 될 것이다! 그러면, 우리는 일리단을 해치울 수 있어! 우리는... 일리단을 대신해서 아웃랜드의 주인이 될 것이다!"
rows["142:1556762230"]="마즈가 내게 친절하였으니 그 물은 나를 지켰고 바람이 멀리 떨어진 곳으로 날 태웠으니 내가 원하는 더 나은 삶은 무엇이었을까?"
rows["142:1561685528"]="알테락밸리의 탑과 벙커는 중요한 전략적 지역입니다."
rows["142:1573716762"]="빛 형제단 의 우리 는 이 세상 을 잘못 해 줄 사람 들 에게 정의 를 베풀 때 우리 형제 들 처럼 관용적 인 것 은 아닙니다."
rows["142:1596021946"]="마법으로서, 당신은 이 곳으로 다시 데려갈 포털을 불러올 수 있는 선택된 집단의 한 명입니다."
rows["142:1602855026"]="네놈들의 노력은 수포로 돌아갔다! 이미 세계수의 힘을 빨아들이기 시작했다. 이제 세계의 심장은 영원히 박동을 멈추리라!"
rows["142:1627290859"]="너무 야만하고 악당해서 그는 평온의 봉우리에서 발자취를 당했고, 그것은  ⁇ 어 입이 있는 광기, 항상 바나나 원숭이 수도원 마스터 클라우드벤더 코보입니다!"
rows["142:1629006298"]="왜 저 마법사를 돕는 거냐? 차원문이 열리지 않아서 전쟁이 일어나지 않으면 얼마나 많은 목숨을 구할 수 있는지 생각해 봐라."
rows["142:1693038201"]="글쎄요, 모르겠습니다. 전 여기서 모닥불을 지키면서 주트피즐과 톱니바퀴 고장에 대해 얘기를 나눴지요. 그것도 나름대로 아주 근사한 일이랍니다."
rows["142:1709413491"]="아쿠아노스, 옷이 너무 높게 보내지 마 Aethas Sunreaver의 얼굴은 안보였어"
rows["142:173919905"]="네가 도착하기 전에 우리는 '태양 꽃'에 축제하러 갔어요"
rows["142:174210428"]="철혈의 그리'렉$B$B방황하는 놈의 힘과 전투에 대한 열망이$B$B그릴크는 이제 미쳤던 지경에 머물고 있습니다."
rows["142:1748544093"]="우린 전선에서 일하는 데 적지 않은 드루이드들이야$B$B하지만 가끔은 엉덩이를 더럽히는 걸 좋아해요 "
rows["142:1784585073"]="우리... 우린 \"진홍빛 서광\"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이..."
rows["142:1830709656"]="난 좋은 싸움을 좋아하지만 때로는 적의 두개는 토륨 열보호보다  ⁇ 고 있어요 "
rows["142:1836175617"]=" ⁇ 알은 도라나르의 달굴에서 시간을 보내는데 필요한 훈련을 받을 수 있을 것이라고 확신합니다."
rows["142:1881733763"]="바네홀로우의 메시지, 그 메시지는 뭐야? 그는 위대한 조언자와 종인 Ulathek를 필요로 하는가?"
rows["142:1913686790"]="전장에서의 장렬한 최후라는 낭만에 내 전사들을 희생할 생각은 없네. 살아남고자 벌인 싸움에서 아무도 살아남지 못한다면 그게 무슨 소용인가?"
rows["142:1924268383"]="이제 너만  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고  ⁇ 고$B$B ⁇ 아 덩어리,  ⁇ 아 덩어리, 처음 빛을 보게 되세요!"
rows["142:1929472386"]="오, 그래, 범위를 최대한 높이기 위해 그리고 용량을 늘리기 위해 우리는 최신 엔진을 위한 비정상적인 로켓 연료 혼합물을 만들었습니다."
rows["142:1944213325"]="이 물들이 계곡을 꽃피워지게 해 주었습니다. 그 물들은 4개의 바람의 계곡으로 흘러들어 가면서 세계에서 가장 비옥한 농지를 만들어 냈습니다."
rows["142:1959289632"]=" ⁇ 루그의 도움이 필요해요. 썬더 블러프 은행"
rows["142:1982741270"]="도망치려고 용감한 거야, 젊은 오가나카$b$b계속하기 전에, 어떻게 치아를 이용해 트롤들의 네트워크를 물리는지 가르쳐 드리겠습니다."
rows["142:1989947655"]="희망이 없는 것은 희망이 없는 것이 아니라 모든 희망이 망가진다는 것입니다. 형제자매 여러분, 이것이 옳습니다. 오직 절망만이 진정한 희망을 줄 수 있습니다."
rows["142:1992414108"]=" ⁇ 비스, 네가 다 끝나면, 또 다른 화크 코트를 휘일러 휴대폰에 넣으면 좋겠어"
rows["142:1998721410"]="이런 공허한 승리는 내 아들의 영혼에게 안식을 줄 수 없다, 용이여. 나는 내 아들을 되찾을 것이다. 수천 년이 걸린다 할지라도 꼭 되찾고 말 것이다!"
rows["142:2000744206"]="흠, 이 키버에게 새로운 연구 주제가 필요할 것 같군. 그 바보 애버너시가 계속 이 키버의 주제를 가로챈다면 키버가 그에게 한마디 할 수밖에 없지."
rows["142:2018884204"]="어업자들은 모두 최근 알 아메트 호수 주변 공격으로 다르나서스로 이동했습니다."
rows["142:2027095755"]="자이로메기닉 기어와 엔지니어 팀의 충분한 공급으로 탱크는 완전히 회복될 수 있지만, 그것은 긴 여행이 될 것입니다."
rows["142:2090423766"]="넌 내보다 술에 대해 더 잘 알고 있어, 게다가 내가 지켜봐야 할 냄비도 있어."
rows["142:2098987035"]="3개 조각으로 마켓이 될거야 손잡고 머리 그리고 기름"
