rows["142:2115825460"]="캠프불을 만드는 법을 배우고 싶다면 텔드라시일을 불태우기 전에 마일리겐을 만나면 좋겠어  "
rows["142:2120184565"]="내 시대에는 먹이의 심장이 뛰는 소리를 들을 수 있었지만 이제 말해야 한다"
rows["142:2124952158"]="보통 빌헬름 형제는 리리아와 거래하는 이야기 뒤에 있습니다. 그는 항상 동료 paladins에 새로운 기술을 가르치려고 합니다."
rows["142:230953072"]="그들은  ⁇  라이 기커를 쫓아다니야 합니다! $p, 이 목격들을 조사하고 마을 방어를 설정합니다! 그들은 싸움없이 내 맥주를 얻을 수 없습니다!"
rows["142:245592260"]="호네의 지붕에 구멍이 뚫린 건 뭐지 궁금해요 아웃랜드?"
rows["142:320801581"]="케린 실비아스가 그  ⁇ 한 놈들 곁에 있어"
rows["142:3341673"]="저는 공학자가 있는 것을 기억하고 있습니다. 이 건물에 들어가면 왼쪽에 있는 공학자입니다.$B$B지도에 위치를 표시해 줄게요"
rows["142:369892117"]="영들을 돌보고 다시 우리들 사이에서 데려오면, 우리는 이 땅을 치유할 수 있고, 우리가 직면한 더 큰 위협에 대한 이해를 얻을 수 있습니다."
rows["142:382402027"]="전 대전군에 다시 보내야 합니다. 얼라이언스 2개월 후에 해군이 도착할 겁니다."
rows["142:392483227"]="맞아요, 우리는 죄수들을 때려주지 않습니다. 반면에, 부진자들은 폭력에 문제가 없습니다."
rows["142:404469355"]="하늘이 희생자의 피로 붉게 물들었다! 리치 왕께서 우리를 굽어보고 계신다! 너희가 휩쓸고 간 자리에는 재와 비탄만을 남겨라!"
rows["142:44841564"]="잿빛 골짜기의 마에스트라 주둔지에 가서 파수꾼 오나에야를 만나보십시오. 그대가 오늘 보여준 용감한 행동에 대해 반드시 보답을 할 겁니다."
rows["142:474484623"]="이 마을이 지쳐서, 여행을 하고 세상을 볼 수 있었으면 좋겠다. 어쩌면 금을 충분히 저장하면, 내 자신의 대웅전적인 모험에 나설 수도 있겠지!"
rows["142:487229067"]="D 씨, 다시 왔어 총을 쏘는 법을 기억해?"
rows["142:502104593"]="노스렌드까지 가고 싶다면, 강풍이 바로 갈 수 있는 길이야."
rows["142:54591383"]="내 도끼를 매료시킬 수 있어? 영구적인 도끼를 원해. 나중에 찾을 수 있어."
rows["142:547012336"]="우리 \"왕\"이 우리를 배신할 줄 꿈도 꾸지 못했는데..."
rows["142:554004848"]="저는 문명을 파괴하는 데 제 역할을 했습니다. 저들은 저주를 받는 악당의 숭배를 다루기 위해 자신을 낮추어야 했습니다."
rows["142:583965137"]="수프가 준비되면, 그것을 클릭해서 가져오세요. 너무 오래 방치하면 수프가 망칠 것입니다. 그래서 고객들에게 필요한 것만 만들어 보세요."
rows["142:61530710"]="P 씨, 다시 왔어 총을 쏘는 법을 기억나?"
rows["142:625154796"]="아... 제 힘으론 고대 신들의 속박이 꿈쩍도 하지 않습니다. 그가 그들의 음흉한 생각에 의해 잠식 당하고 있습니다... 더는... 더 이상은... 버틸 수가 없습니다... 엘룬이시여, 저를 도와주소서..."
rows["142:690296739"]="더 다크스피어 드럼을 다시 듣는 게 좋을 것 같아."
rows["142:698142688"]="이제 너희 몫이다, 용사들이여. 우리 모두를 대신해 복수해다오! 너희 앞에 어려운 임무가 놓여 있지만, 내가 최대한 너희를 돕겠노라. 너희는, 승리해야만 한다!"
rows["142:70856425"]="A-Me에게 전해주고, 라코우에게 전개를 만드는 법을 가르쳐줘서 고마워하고 미스코에게 공룡과 싸우는 법을 가르쳐줘서 고맙다고 말해주세요."
rows["142:710954502"]="아직 좀 약하고, 균형이 깨지고, 불확실해."
rows["142:712350153"]="내 스카우트는 동쪽 고원에서 숨겨진 동굴에 진출한 것으로 보고 있습니다."
rows["142:717600812"]="여기 진짜 깜짝 놀래운 게 있는데, 그들이 무엇을 축하하고 있다고 생각하십니까? 그리고 그 날을 기념하기 위해 적절한 음료가 무엇이라고 생각하세요?"
rows["142:738964879"]="이 모든게 무서운거예요, 그렇죠? 그리고 그 함정이 매우 불쾌합니다. 이 모고들은 절박하게 장식 조언이 필요할 겁니다."
rows["142:77954038"]="당신의 비전 부족은 왜 당신의 사람들이 여전히 원시적인지, 그리고 당신의 충성 부족은 내가 이 캠페인에 Darkspear을 소집하지 않았는지입니다."
rows["142:796025390"]=" ⁇ 한 마음은 악당하지만 우린 좋은 사람들인데 오래 있으면 똑똑하고 강한 친구들만 좋아$B$B우린 멍청한 놈들을 좋아하지 않아요"
rows["142:805273576"]="그래! 네 몸은 여전히 단단하구나. 무슨 일이 있었는지 기억하느냐, 무라딘? 네가 없는 동안 심술궂은 운명 탓에 일어난 일을 말이야."
rows["142:848813305"]="이 론스톤은 다른 것보다 더 최근의 것인데 \"잠자는 보호자\"에 대한 내용일 것 같아요"
rows["142:911767268"]="네 이름은 뭐야?$B$B너네 짐승들이 말을 못하면 다행이야 그렇지 않으면 내가 왜 날 짜증나게 했는지 상주왕에게 말해야겠어$B$B이제 긁어!"
rows["142:946433054"]="소나무 가지들이 우리 배를 거의 손상시키지 않는 것은 인상적입니다.$b$b우리가 숲에 충돌한 3번은 변명하지 않습니다."
rows["142:979577698"]="이봐요, 선구자 씨, 조사는 어떻게 진행되고 있나요? 당신이 그 결과를 일러주기만 하면 와플제 초강력 다리미를 드릴 수도 있는데!"
rows["143:103419469"]="선웰에 도달하는 걸 막는 모든 장벽이 파괴되었습니다. 선웰에 들어가서 킬제이든이 이 세상에 들어오지 못하게 해!"
