rows["143:1213930808"]="쓸데없는 얘기는 그만하지! 네 도시를 되찾고 싶다고? 오너라, 영웅들아! 네놈들 영혼으로 주인님은 힘을 얻으시리라! 이 도시는 산산조각 난 채로 되돌려주마!"
rows["143:1241480922"]="로그 트레이너의 이름은 마리온 콜입니다."
rows["143:1285482160"]="이 바보 는 이해하지 못 합니다. 그는 무분별 한 방치 와 함께 부정적인 감정을 가지고 있습니다. 그러한 행동 이 계속된다면 우리 모두는 그 결과 를 겪게 될 것입니다."
rows["143:1306635960"]="블러드스칼프, 샌드푸리, 스켈플릿터, 비레브랑치와 위더바크 모두 진에게 충성 맹세하고 그들의 영혼을 하카르에게 맹세합니다."
rows["143:1370628214"]="나가들이 막히지 않으면 우리 탐험은 중요하지 않을 거야"
rows["143:1394610200"]="중앙 탑을 보십니까? 번개가 계속 그 탑에 타격을 주고 있습니다. 에타스는 폭풍이 궁전의 중심에서 발생한다고 의심합니다."
rows["143:1433994374"]="얼간이 같은 놈들! 너희가 지금 무슨 짓을 하고 있는지, 전혀 모르는구나. 지맥의 흐름을 방해하게 놔둘 것 같으냐? 내 너희를 완전히 끝장내 주마!"
rows["143:1456525706"]="용감한 영웅 여러분, 보여준 감사합니다. 아제로스 어둠이 얼마나 덮치더라도 단 하나의 빛이 통과할 수 있다는 것을요."
rows["143:14933718"]="운명은 기다려주지 않는다. 바위 거인 지도자와 그의 군대가 울두아르에 도착하기 전에 전쟁 골렘을 더 많이 생산해야 한다."
rows["143:1518919078"]="고대의 해적 Dice를 조심스럽게 굴리는 경우 12, 그녀의 모든 승무원에게 |cFF3366FF|Hspell:142140|h[해적의 삶]|h|r."
rows["143:1564021248"]="저는 목포들이 훈련된 군인들을 막는 대리대를 봤습니다. 이런 장비를 제대로 조종하는 데 필요한 힘과 기술을 결코 과소평가하지 마세요."
rows["143:1595733411"]="그는... 너무 강하다. 영웅들이여, 어서... 이쪽으로 오라! 즉시 이곳을 떠나야 한다! 도망치는 동안 그를 잡아놓을 수 있도록 조치를 취하겠다."
rows["143:1625211092"]="다라나르에 다른 요리사가 필요하겠지만, 자네가 잘 모르는 게 아니라"
rows["143:1639791827"]="발아니르는 토석인과 무쇠 드워프의 첫 번째 전쟁 때 파괴되었습니다. 무기의 파편은 유실되었다고 알려졌습니다."
rows["143:1650850720"]="너무 피곤해 어젯밤이 늦은 거 아니었나, 오늘 아침이었어. 하지만 재밌었어!"
rows["143:1670869593"]="아니, 아니, 하지만 많은 사람들이 사랑을 찾고 있어. 당신은 내 사랑 토큰을 사서, 콜론이나 향수를 입고,"
rows["143:1674243163"]="알케미스 트레이너가 필요해? 기술공 거미들이 모이는 도시"
rows["143:1692834753"]="물 \"착륙\"이 불가능한 경우, 편리함을 위해 시안화 캡슐이 위치해있는 좌석 베개 아래로 이동하십시오."
rows["143:1757571146"]="불꽃은 이 신성한 장소의 남은 전부다. 나는 분노를 느끼기 위해 여기 온통 분노를 느끼고 있습니다."
rows["143:1767875138"]="\"잠시마자, 물처럼 해봐 적의 힘을 저항하지 말고 그냥 그 힘으로 흐르라. 그의 부딪히는 걸 놓아주라\"."
rows["143:1808269939"]="오늘 이 전투장에서 죽으면 오크시스 죽음과 같고, 오늘 죽으면 우리 어린아이들, 우리 늙은이들, 우리의 사랑하는 사람들\010"
rows["143:1823616494"]="나까지 포함해서 모든 사람들에게 비밀입니다!$B$B날 찾았다는 건 다행이야. 난 덤불이나 바위 밑에 숨어있지 않아?"
rows["143:1842841428"]="머리 위에 탄탄한 화석 천장이 없다면 편안하지 못해"
rows["143:185282217"]="물질적 부에 대한 집착은 항상 존재합니다."
rows["143:1865193826"]="크라사리 철을 사용해서 왜성이나 기둥의 공사를 진행할 수 있습니다! $B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t"
rows["143:1879861393"]="오크릴라가 오크를 안 내면 안 좋아하지만, 그게 그녀를 막지 않아"
rows["143:1884669812"]="그래! 네 몸은 여전히 단단하구나. 무슨 일이 있었는지 기억하느냐, 무라딘? 네가 없는 동안 심술궂은 운명 탓에 일어난 일을 말이야."
rows["143:1905360578"]="빛의 성당은 스톰윈드의 모든 치유 관행의 중심지입니다. 그곳에서 안젤라 라이펠드를 찾아서 이 공예 를 배우도록 도와 줄 수 있습니다."
rows["143:1985259950"]="자네 드레나이들 중 일부는 스케티스에서 또 일부는 어둠달 골짜기에서 만났던 것 같군. 하지만 지금 이곳은 아제로스고 상황이 좋지 않다."
rows["143:1985282640"]="뭐, 뭘 했니? 아니! 내가 얘기한 걸 알았을 때 Twilight Council이 내게 무슨 짓을 할 지 알겠나?"
rows["143:2013086504"]="한 알케미스트가 산맥에서 북녘골 그리고 스톰윈드 좀 도와줄 수 있겠네요. 왜 가서 그를 방문하지 않는가?"
rows["143:2052983229"]="이네세라는 다양한 보석과 보석품들을 들고 다니는 날카로운 여성입니다. 알도르 라이즈 북부에 있는 그녀의 가게를 찾을 수 있습니다."
rows["143:2068849781"]="우리는 한 가지 목표를 가지고 온 것입니다. 이익. 제 동료들과 저는 항상 비즈니스 파트너를 찾고 있습니다."
rows["143:2076177164"]="어떻게 해야 할지 모르겠지만 칼은 당신을 새  ⁇ 주로 선택해 스컬지 한 번 그랬던 것처럼"
rows["143:2085016427"]="시바루스는 진심으로 감사해요, 영웅님, 당신 없이는 시바루스는 죽었을 수도 있고, 더 나쁜 것은,"
rows["143:2111965389"]="그녀는 내가 당신에게 말할 것을 원했고,  ⁇ 브로우에서 우리가 그녀를 위해 했던 일을 감사하고 싶었고"
rows["143:2118471529"]="왕실 교류관 에서 유물 을 찾아 보아라. 그 조직 의 많은 고고학자 들 중 한 명 이 분명 거기 있을 것 이며, 아마 당신 에게 도움 이 될 것 이다."
rows["143:220234738"]="어떻게든 밤 엘프들은 우리가 함대를 발사할 예정이라고 알게 되었고, 그들은 공격했습니다. 대부분의 새로운 배들이 항구에서 앵커를 태워버렸죠!"
rows["143:236995849"]="이것은 오만인가 아니면 어리석은 짓인가 너희들의 죽음이 그 안 에 있을 것이며 우리가 너희를 버리지 아니하면 너희에게는 어떤 도움도 없노라 너희는 너희가 말하는 것을 알고 있느뇨"
rows["143:28166580"]="네가 가장 강력했던 폭풍의 신전을 떠나게 된 걸 네 조그마한 친구에게 감사해야겠구나. 그 덕분에 주인님의 힘에 더 가깝게 싸우지 않느냐."
rows["143:306270195"]="카이라 윈드블레이드는 칼을 잘 휘두르는데 훈련도 할 수 있을 겁니다."
rows["143:336098377"]="이 땅은 한쪽에서 스컬지의 존재와 다른 쪽에서 드라카리의 의식으로 오염되었습니다.$B$B우리는 둘 사이에 굳건히 서 있습니다."
rows["143:340507112"]="으아아아아아아! 제발... 우리가... 아는 거라곤... 우리 중에... 우리처럼 분장한... 너희들 첩자가 있다는 사실이야! 그래... 내가 아는 건 그게 다야. 제발... 자비를... 그만!"
rows["143:371242227"]="가장 가까운 영은 후오, 불의 영입니다. 저는 여러분께 저의 재능 있는 학생들 중 몇 명을 만나서 후오에 대해 알고 있는 것을 알려드리도록 부탁드립니다."
rows["143:373325822"]="제 학생이 되고 싶다면, 내게 주어진 일을 해내야 합니다."
rows["143:381862220"]="그렇다면 역사에 대한 당신의 지식을 시험해 보겠습니다. 어떤 악마가 청색 용인 칼레고스가 선웰 고원도에 있는 모험가 집단과 싸우도록 강요했습니까?"
rows["143:397607165"]="이 기술을 처음 시험해 봤는데 예상보다 더 잘 됐어요"
rows["143:414115441"]="여기서 뭐하는 거야?$B$B내 길을 벗어나지 마 Scarlet Onslaught를 당신 같은 사람들이 방해하지 않도록 해"
rows["143:424346727"]="불쌍한 크레테우스. 훌륭한 감시자였죠... 그래도 자신의 임무를 완수하고 가서 다행입니다. 크레테우스에겐 그게 삶의 전부였을 테니까요."
rows["143:438768098"]="경고에 대해 걱정하지 마 우리 군대는 모두 지휘 체계를 알고 있습니다. 우리는 연합해서 싸우고 있습니다."
rows["143:445592457"]="황제 살몬을 찾는 가장 좋은 곳은 네 바람의 계곡에 있는 맥주 공장 밖에 있을 겁니다"
rows["143:496864576"]="당신 은 상상 할 수 없을 만큼 큰 적 들 이 주위 에 있을지라도, 당신의 용기 는 당신 을 견딜 수 있게 해 줄 것 이다."
rows["143:547354578"]="군대가 위를 타고 여행한다고 합니다. 그게 사실입니다. 어떤 공격도 성공하기 위해서는 군대가 잘 먹여 공급되어야 합니다."
rows["143:55016816"]="그늘거미 밀렵꾼이 가까이 있을 때 이 지휘의 지팡이를 라제에게 사용하십시오. 녀석들, 이 땅을 침범하기로 결정한 날을 후회하게 될 겁니다."
rows["143:585612701"]="제 명령은 이 땅에 새로운 재산을 확보하고 조사하는 것이었습니다 빛 우리의 태양보행자들은 느꼈습니다. 얼라이언스 거의 걱정이 되지 않습니다."
rows["143:605765757"]="달 축제의 가장 놀라운 파티는 무롱라이드에서 있습니다. 하지만 거기 걸지 마세요. 지혜의 계곡의 드루이드는 여러분을 운반할 수 있습니다."
rows["143:606555396"]="그렇다면 역사에 대한 여러분의 지식을 시험해 보겠습니다. 아제로스의 세계를 보호하기 위해 몇 개의 드래곤 비행기가 특별한 힘을 부여받았습니까?"
rows["143:630066279"]="우린 얼마 안 지나지 않아 물품도 부족해 질 거야"
rows["143:646935260"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다! 아제로스."
rows["143:665551220"]="오늘 여러분들이 아레나에서의 실력으로 모든 사람들을 감동시켰습니다. 이제 모든 사람들 앞에서 토너먼트의 챔피언으로 인정받을 때가 되었습니다."
rows["143:719122997"]="감사합니다, 친구, 내가 자유를 빚어졌어요. 타레타는 어디 있어요?"
rows["143:723974444"]="그는... 너무 강하다. 영웅들이여, 어서... 이쪽으로 오라! 즉시 이곳을 떠나야 한다! 도망치는 동안 그를 잡아놓을 수 있도록 조치를 취하겠다."
rows["143:740987815"]="판다리아가 무너지는 동안 우리가 산 꼭대기에 앉아서는 안 되니까"
rows["143:751280610"]="간단하다. 투스카르에게 도망쳐서는 아니 된다고 알려라. 만약 도망친다면 그들의 영혼은 노스렌드의 악마에게 갈기갈기 찢길 것이다."
rows["143:755975837"]="팔꿈치에 숨겨진 칼은 거리에서 죽은 채 누워있는 당신과 상대방이 자신의 피로 얼굴을 누워 있는 사이의 차이를 의미할 수 있습니다."
rows["143:765864901"]="가로쉬가 신성 벨을 찾고 있소?"
rows["143:771909931"]="켈제덴의 부패한 몸매의 불쾌한 젖으로, 뒷면이 모두 날려버렸어요!"
rows["143:820391875"]="케인 파이어송이 연구실에서 항상 불쾌한 일을 하고 있다고 들었어요"
rows["143:856295517"]="마구스 무역 거래소에서 약품 모양의 문을 찾아보세요."
rows["143:874921500"]="네놈들이 이겼다고 생각하겠지만 리치 왕의 힘에 대항하는 자들에겐 승리란 있을 수 없다! 지금까지 보여준 건 내 힘의 전부가 아니다!"
rows["143:928580592"]="데피아즈단는 폭동자 집단일 뿐이지, 근거 없는 추측을 쫓기 보다는 스톰윈드의 진짜 적들과 싸우는데 바쁘어야 합니다!"
rows["143:941041549"]="파룬은 너희가 거센물결 호수라 부르는 곳의 북쪽에 있다. 녀석은 언제나 혼자 다니지만, 일단 마주쳐 보면 녀석에겐 보호자 따윈 필요 없다는 걸 알게 될 것이다."
rows["143:945526192"]="지금 정보 필요해요 얼라이언스 우리가 남은 오크들은 몇 명이나 있고, 그 광신 괴물 클러치팝이 방어력을 갖도록 도와줘요."
rows["143:95028639"]="여기까지의 무게를 끌어내기 시작했다고 들었어요$B$B잘됐어요. 우리가 도와줄게 설득해야 한다는 걱정이 있었어요."
rows["143:954382679"]="고대의 해적 Dice를 조심스럽게 굴리는 경우 12, 그의 모든 승무원에게 |cFF3366FF|Hspell:142140|h[해적의 삶]|h|r."
rows["143:971494281"]="클라시족들 사이에는 셰어드 레스트의 벽 너머에 있는 고작의 수학자들이 있다고 들었습니다."
rows["143:980391132"]="너무 피곤하군. 어젯밤... 아니 오늘 아침까지 그렇게 늦게 놀지 말았어야 했어. 그래도 재밌었지! 역시 주군의 연회가 최고야."
rows["143:998139853"]="저는 D 블록의 팬이 아닙니다. 모두가 그것에 대해 계속 이야기합니다. 하지만 우리가 그것을 사용할 수 있기 전에 완료해야 할 몇 가지 작업이 있습니다."
rows["143:99839359"]="금 로토스가 준비한 버페에 참석해, 영원한 꽃의 계곡을 지키는데 도움을 준 사람들을 감사하게 해주세요."
