rows["144:1066178438"]="이게 어린아이랑 놀리는게 아니야 나가 스나르랑 얘기해 내 쉼터에 뱀이 있을지도 모르지만"
rows["144:1088272733"]="타르텍을 만났어? 그는 우리의 최고의 전투자 중 한 명입니다. 북서부에서 지휘하고 있습니다. 드래곤의 물건을 잡았다고 들었습니다. 거짓말은 아닙니다, 저는 약간 질투합니다."
