rows["144:1116494817"]="어리석은 필멸자들 같으니. 그리 쉽게 우리를 이겼다고 생각했어? 산레인은 리치 왕이 다스리는 불멸의 병사들이야! 이제 합쳐진 그 힘을 보여주겠어!"
rows["144:1178864628"]="칼림도어 그리모테마에 속해 있어 아무도 우리 길을 걸을 수 없어$B$B우린 모든 면에서 최고야, 내가 네 유감스러운 팀을 짓밟는 동안 알겠지"
rows["144:1246399044"]=" ⁇ -그놀은  ⁇ -그놀의 재미있고 재미있는 게임입니다.$b$b우리들 사이에서 꽤 인기 있는 새로운 매력입니다."
rows["144:1273521631"]="전단 모험가들이 계속할 준비가 됐나?"
rows["144:1359926003"]="동남쪽 끝에서 갈로우스 엣 테버네가 있습니다. 거기 가서 위로 올라가면"
rows["144:138278350"]="이 늙은 멍청이를 들어봐, 얘네는 모든 사람과 그런 거잖아 내가 널 지켜봤어"
rows["144:1409600899"]="만약 천개 바늘의 슈하로가 무너지면 그리모테마 족속은 곧 당신 텐트에서 나올 것입니다."
rows["144:1472521038"]="적어도 당신이 아이언포지에 아내를 남겨두고 싶지 않았어. 나는 그녀가 내가 주변에 없는 동안 무슨 일을 상상할 수 없습니다. 당신은 여자들이 광석 주위에 얼마나 알고있다."
rows["144:1492120485"]="메신저님, 우리의 계획을 로르테마르에게 전달해 주세요. "
rows["144:1539675973"]="좋아 보이지만 좀 더 잘 보이게 될 거야 싸움을 하는 환상을 팔기 위해서"
rows["144:156108211"]="자이 지 연습 중이야, 여기 5미터 이내에 있는 사람은 아마 쓰러질 거야$b$b- 하이하!"
rows["144:1626333666"]="|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t 가라론은 높은 곳에 날아가고 |cFFFF0000|Hspell:128555|h[Massive Crush]|h|r를 준비한다!"
rows["144:1675432339"]="이 에테리얼은 바실리스크 눈도 못 봤어$B$B그리고 그의 지도자는 자신을 \"매매 왕자\"라고 부르기 위해 용기를 가지고 있습니다!"
rows["144:1676477549"]="잘했어, 우린 이 무기를 철저히 지켜야 해, 여기 이 홀에 숨겨져 있어."
rows["144:1719128911"]="아 그러니까, 어쨌든 친구들이 좀 그리워지기 시작했어요. 아마 내가 이런 생각을 했다는 건 안 믿겠지요! 아, 여기, 이거 받으세요. 숨바꼭질하다가 찾은 거예요."
rows["144:1732327471"]="여러분의 희망은 빛나는데, 더욱 더 빛나는 것은 함께 힘을 합쳐서 이겨내면 가장 어두운 곳에서도 항상 빛을 발하게 될 것입니다."
rows["144:1792193822"]="이 모든 갈등이 끝나면, 저는 은퇴할 것 같습니다. 듀로타.$b$b언덕에 있는 작은  ⁇ 이 좋겠는데, 아마 작은 정원이 될지도 몰라$b$b그래, 좋은 소리야"
rows["144:1822790059"]="네 자세가 틀렸어, 발이 완전히 불균형해 머리도 너무 부드럽다$b$b배울 준비가 되어있다는 것을 알게 되면 다시 돌아오세요."
rows["144:18419138"]="푸른용군단이 그토록 무자비하고 냉혹한 길을 택한 것은 참으로 유감입니다. 말리고스의 자식들과 싸워야 한다니 가슴이 아프군요."
rows["144:1871145537"]="이 손님은 잃어버린 사랑의 추억을 입고 있습니다. 저는 그들이 말하는 것이 사실이라고 생각합니다. 모든 사랑 이야기에는 그 주름이 있고, 모든 밤에는 새벽이 있습니다."
rows["144:1877044588"]="한동안 내가 네가 내 사랑하는 시프라고 생각했지만, 아니, 시프가 죽었어$B$B내... 내 동생... 그녀를 죽였어!"
rows["144:1897373749"]="강함의 계곡에 있는 하늘탑의 꼭대기에 바람 라이더 마스터를 찾아라"
rows["144:1910570261"]="지역 스프라이트에서 나오는 영 키스 물은 우리 식물을 잘 먹여줄 것이고, 버킷이 채워지면 다시 보충할 필요가 없을 것입니다."
rows["144:1941657686"]="그거라니까, 언니! 핏달! 사샤 언니... 다시는 나 혼자 두고 가지마! 그 사람들은 아빠를 죽였고, 그리고 언니까지... 나 혼자 그 사람들이랑 있기 싫어!"
rows["144:1945809296"]="지금 우리의 땅에 지독한 병이 돌고 있소. 날로 심각해지고 있지! 마력에 대한 욕구가 클수록 우리는 약해질 테고 결국 몰락하고 말 거요. 과거에 그랬던 것처럼!"
rows["144:1995694965"]="이 모든 것을 포장할 시간이 충분하지 않습니다! 중요한 것들을만 가져가십시오! 나는 내 폭발성 항해 잠수 G-Ray 고글을 어디에 넣었습니까?!"
rows["144:1995913067"]="트위즈플럭스, 무슨 미친 짓이야?"
rows["144:2012847058"]="이제 당신의 사람들이 무기를 내려놓으면 이 대륙에서 두 명의 적을 마주하게 될 것입니다."
rows["144:2041544690"]="경보, 공룡들! 다크문 죽음의 경기가 시작될 예정입니다."
rows["144:24281474"]="반드시 그렇지는 않다네. 므우루가 쓰러진 곳에서 신성한 나루의 불꽃을 다시 찾았으니까! 젊은 블러드 엘프여, 믿음이 머무는 곳에는 언제나 희망이 있다네."
rows["144:26024444"]="초급은 여기 멀지 않아 걱정 마요. 치료사들은 마스터의 방 안에 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["144:265382140"]="그래서... 여기 있는 상자가 고르도크 오그레들이 귀중한 유물이라고 생각하는 장갑이 있다고 생각해 보실 수 없나요?"
rows["144:290431762"]="하지만 먼저 아즈샤라의 고성장 래키들의 보호 구역을 내려놓아야 하니까 궁전 안에 찾을 거야"
rows["144:334207254"]="이 조각들의 힘을 발견하면서 나 자신을 배수에서 끌어내고 삶을 다시 살려야 할 의지가 생겼습니다.$B$B그리고 또 쫓겨났어요"
rows["144:342209849"]="붉은 크레인은 내 안에 희망을 보았고 내 안쪽으로 바라보고 말았다. 절망의 얼굴에도 불구하고, 나는 그 희망을 발견했고, 절망은 패배했습니다."
rows["144:351845023"]="이 캠프 중간에 있는 불에 막대를 던져주셔야 합니다."
rows["144:38543057"]="하지만 큰 마을에서 멀리 떨어져 있어! 그 안에 수십 개의 미친 얼음 트롤들이 있다."
rows["144:397085051"]="자넨 부하들에게 거짓말을 했고, 자네를 믿고 싸운 용병들을 배신했네. 대체 왜 그러나? 자네에겐 오직 복수만이 중요한가?"
