rows["144:415225322"]="챔피언, 우리의 캠페인은 최고점에 도달하고 있습니다. 우리는 Thunder King의 궁전의 문턱에 있습니다."
rows["144:427436819"]="요즘은 사람들이 많이 오고가는데, 정말 인생에 대해 생각하게 해$b$b나도 어딜 가든 찾아와야 돼"
rows["144:427732701"]="불타는 군단은 우리를 압박하지만 우리의 방어는 견딜 수 있습니다. 우리가 아르키몬드를 세계 나무에서 멀리 두는 모든 순간은 우리를 승리에 더 가까이합니다."
rows["144:53179515"]="가죽과 피부를 만드는 것? 당신은 수건을 찾고 있을 겁니다.$B$B지도에 위치를 표시해 줄게요"
rows["144:533439251"]="이 포스터에 있는 정보는 아직 당신이 필요한 일에 자격이 없다고 나타냅니다.$B$B나중에 다시 확인해봐야지"
rows["144:537766246"]="내 친구, 네가 높은 곳에 도달한거야. 일부 사람들은 꿈꾸는 것뿐이야. 축하한다! 그리고 이제 더 이상의 의식 없이, 네 마지막 수업이 왔어!"
rows["144:542876358"]="이 생활에 익숙해져야 한다, 보병들이여. 우리는 비참한 삶을 이어가기 위해 이곳에 왔다. 새로운 고향 지옥불 반도에 온 것을 환영하는 바이다."
rows["144:551212621"]="|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t제국 비지르 조로크는 |cFFFF0000|Hspell:122336|h[소닉 링]|h|r를 방 건너편으로 보내!"
rows["144:567823839"]="이 자이드 조각상의 특징은 정말 실제적인 것 같습니다. 얼굴 표정은 공포로 잠겨 있습니다.$b$B하지만 신과는 닮지 않습니다."
rows["144:581680132"]="경호자들과 저는 크라사랑 야생에서 살았던 이야기를 나누었고,"
rows["144:635465018"]="네 조상들이 원인인 것 같아, 트롤."
rows["144:658774316"]="폴드링, 넌 나의 가장 위대한 용사가 될 수도 있었다. 어둠의 힘으로 이 세계를 쓸어버리고 투쟁의 새로운 시대를 여는 용사 말이다."
rows["144:671136208"]="우리는 돈으로 많은 것을 가지고 있지 않지만, 저는 여러분들과 유명한 맥주를 나누고 싶습니다."
rows["144:673019240"]="아, 그 때 다른 일이 일어날 거라고 예상했잖아?"
rows["144:732574190"]="적을 죽이면 내 블래드턴 능력을 사용할 수 있어"
rows["144:735701591"]="저는 제 민족의 역사학자라고 생각하며, 현재를 이해하기 위해서는 과거의 사건을 살펴봐야 한다고 믿습니다."
rows["144:75222031"]=" ⁇ 스 게이트에서 너들이 똑똑하다고 생각했지?"
rows["144:757284881"]="행동은 의도보다 더 큰 소리지만, 제 전사들은 복수를 추구하겠지만 연습만이 그렇게 할 수 있습니다."
rows["144:765404923"]="명예의 계곡의 용감한 사람들을 찾아서 그레즈 래지피스트와 얘기해 내 일종이 끝나면 다시 보고할 거라는 것을 알려줘"
rows["144:776725443"]="어떻게 된 건진 모르지만, 이 검이 너를 새 주인으로 골랐군. 내 축복과 함께 받아라. 내가 그랬듯 스컬지를 상대할 때 사용해라!"
rows["144:809126712"]="가까이 다가오고 있지만 아직 담배가 너무 많이 들어있어요 다음엔 테라핀 오일을 넣지 마세요"
rows["144:827934040"]="신조들 중 한 명이 내 칼에  ⁇ 돌아 죽었다고 보아... 새로운 위장도 할 수 있을까요?"
rows["144:835176905"]="탈레리스, 전 혼자선 갈 수 없으며 혼자서 여정을 떠나는 건 최후의 선택입니다. 다음 순례자들이 올 때까지 여기서 기다렸다가 그들과 함께 출발하겠습니다."
rows["144:837370247"]="그리고 이제, 당신이 동맹이라고 부르는 나라들조차도 뒤로 물러나서 우리와 함께 힘을 합쳐..."
rows["144:8525464"]="여동생은 기억나? 아버지께서 북쪽의 강을 그렇게 불렀던 거요. 그 밖엔"
rows["144:863652948"]="좋은 질문인데, 내 동생 튀르고러에게 물어봐도 되겠지$b$b아마 그 게으른, 좋은... 오, 시작하지 말아\010"
rows["144:867972288"]="신생에 발견된 후원과 왕의 사라진 데의 명백한 역할 때문에, 저는 데피아즈단에 대한 새로운 공격 계획을 세우기 외에는 선택의 여지가 없습니다."
rows["144:874567006"]="몇 명만 이 사실을 알고 있지만, 저는 한때 포격자였죠. 호드의 재미를 위해 전선수였습니다. 그래서 저는 전투에 대해 몇 가지 것을 압니다."
rows["144:906395088"]="제 영혼은 복수를 위해 불타는데, 하지만 요소들은 명확하게 생각하라고 말해줍니다. 리치 왕은 잔인한 적이고..."
rows["144:967081054"]="그리폰 마스터는 그리폰의 비행을 내부에서 관장한다 스톰윈드- 여행하러 가려고 한다면, 바로 그 곳으로 가야 해."
rows["144:989366716"]="윽! 저놈이 뭘 하는 거야. 해충을 내게 보내? 목숨을 부지하고 싶다면 어서 이거 가지고 내 눈앞에서 사라져!"
rows["144:999824579"]="스톰하트 왕께서 당신을 시험에 임하게 하셨다고요? 그분께서 무엇보다도 먼저 당신의 가능성을 보고 싶으신 게 분명하군요. 아니라면 이런 신성한 의식을 치르게 하지 않으셨을 겁니다."
rows["145:1064179334"]="은행?  ⁇ 은 보트라고 말해서요. 그보다 더 안전한 곳은 없습니다. 아이언포지. "
rows["145:1076711893"]="당신은 도움을 원하고 포세이큰 아라티 계곡의 인간들과 싸우는 데에 대해?"
rows["145:1086429736"]="죽음의 날개의 우물 분해는 울담의 방어력을 무너뜨렸다 준비 되세요, 우린 곧 웨이게이트를 통과할 거야"
rows["145:1099041031"]="고블랜드에 있는 포스터를 지켜봐요, 일단 작전을 시작하면 다시 탑승할 수 있어"
rows["145:1105787243"]="황후의 끊임없이 속삭이는 말을 견딜 수 있는 마음을 강하게 해야 합니다. 약한 마음은"
rows["145:1141915996"]="방어를 시전합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B그러고 나서 근접 표적에 찌르기를 사용합니다.$B|Tinterface\\Icons\\INV_Sword_65.blp:32|t"
rows["145:1158703245"]="본선에 참가할 수 있는 사람은 훈련이 잘 된 사람만 된다.\01015 애완 동물을 최대 수준까지 훈련시킨 후에는 준비가 되어 있다고 간주됩니다."
rows["145:1159780250"]="이전에 발견한 드워프 일지 기억나십니까? 어쩌면 이 드워프는 브란 브론즈비어드를 생포하는 데 반드시 필요한 인물일지도 모릅니다."
rows["145:1222230417"]="로리키퍼 발드린은 젊음의 수영장을 찾을 수 있다고 주장합니다$b$b우리가 성공하면 우리 민족이 다시 불멸할 수 있는"
rows["145:1276271107"]="이 생물은 아주 늙고 매우 지혜로운 존재입니다. 우리는 네스피라와 이야기 할 수 있다면 바쉬히르와 나가에 대해 많은 것을 배울 수 있습니다."
rows["145:1385538957"]="살아있는 관찰자가 없어, 하지만 산악인들도 필요해요."
rows["145:1391443045"]="좋은 생각, 어쩌면 우리가 가서  ⁇ 을 교체해야 할지도 몰라. 그는 잘  ⁇ 습니다. 당신은 마법 사거리의 내주 서클에서 조제프 그레고리안을 찾을 수 있습니다."
rows["145:1399937525"]="재고자의 위협을 들었지만, 그것은 희박했지... 마치 꿈의 세부사항을 떠올려보려고 하는 것 처럼요.$B$B다시금 빚진 것 같네요"
rows["145:1401605811"]="넌 네 부족에서 마지막이 남은 건데, 나두누 왕자를 준다는 보상으로"
rows["145:1461279978"]="골드샤이어의 라이온 프라이드 인은 이 곳 근처에서 찾을 수 있는 모든 인인만큼 좋습니다. 들어와서 인지퍼 파리에게 집에서 느낄 수 있도록 하세요."
rows["145:1480398159"]="지구에 있는 슬픔은 빛에서 내게 주어진 선물을 억제하고 있다.$b$b제 아내는 고통 받고 있는데, 제 능력은 그녀를 도울 수 없습니다."
rows["145:1486051774"]="벨가리스트라스는 진실을 말하고 있습니다.  \010드레이크의 전력은 풀려났어 에레고스를 물리치기 위해 그들의 힘을 사용하라"
rows["145:1491588655"]=" ⁇ 은 라스타칸 왕에게 끔찍한 재앙을 경고했습니다. 왜냐하면  ⁇ 은 거대한 장갑 용이 그의 잔인한 입술로 세계를 묶는 것을 비전을 보았기 때문입니다."
rows["145:1498096234"]="분노의 관문에서 형제자매를 처참하게 살해한 철면피가 이 더러운 도시에 숨어 있다! 놈에게 정의의 심판을 내리자!"
rows["145:1500141427"]="레드 크레인은 항상 우리 민족에게 희망을 상징했지만 그의 부재로 인해 내 생각도 어두워졌다고 생각합니다."
rows["145:1504665917"]="무롱라데 에서 달 축제는 활발 히 진행 되고 있다. 언더시티 의 왕좌 방 에 드루이드 들 의 대표 가 사람들을 그곳 으로 운송 하고 있습니다."
rows["145:1544280936"]="날카로운 칼과 장갑이 필요해 나가란드에 평화를 가져다 줄 수 있어"
rows["145:1548910013"]="점점 더 많은 칼림도어가 우리 왼쪽의 왜곡된 풍경으로 변하고 있으며, 그 안에 사는 생물들은 친절하지 않습니다."
rows["145:1568032921"]="그들이 도와줄 거로시 내가 도와줄게 난 사람들의 두려움을 해소하고"
rows["145:1585185791"]="내 시간은 끝났어요... 살았을 때는 알렉스트라자 님을 섬겼지만, 목숨을 잃은 지금은 그렇게 할 수가 없군요. 그분께서 제단의 수호자를 새로 찾으셔야 할 겁니다."
rows["145:1587540686"]="이곳과 웨스트가드 케이프 사이에선 배가 운항하고 있는데, 때로는 군인과 가끔 승객을 운송하기도 하지만 대부분 필요한 물품을 운반하기도 합니다."
rows["145:1590888367"]="당신들은 누구지 모르겠지만, 감사합니다. 당신의 도움 없이는 우리 세상은..."
rows["145:1679961066"]="우리는 불타는 평원에서 검은용 알이 오기를 기다리고 있다. 검은용 연구를 통해 우리의 지식이 크게 확장되리라 믿는다."
rows["145:168077101"]="아버라는 이름의 SI:7 에이전트를 본 적 있나요?$B$B마지막으로 들은 것은 그녀의 폭탄 테러가 큰 피해를 입었고 동북의 나무에 사라졌다는 것입니다."
rows["145:1764101216"]="그 대신 나를 데려가라. 카일란을 네 사악한 손아귀에서 풀어준다면 넌 알도르 대여사제인 나, 이샤나를 포로로 얻으리라."
rows["145:1767856359"]="안녕하세요, 블리자콘에 오신 것을 환영합니다. 이 항구를 임시로 빌려서 노스렌드으로 운송합니다."
rows["145:1776136861"]="이 빌지워터 카텔 라이프 로켓을 착용하거나 사용함으로써 최종 사용자 라이선스 계약에 따라 구속되는 것을 동의합니다!"
rows["145:1838114332"]="그녀는 미쳤던 용 숭배자들로 둘러싸여 있어 머리에 잘 안 들어있겠지만, 그들은 무장하고 위험하다."
rows["145:1864392167"]="이 쪽지에 적힌 지시 사항은 거의 암호나 다름없습니다. 브란에게 분명히 다른 계획이 있을 테지만, 그렇다 하더라도 영원히 잡히지 않고 피해 다닐 수는 없을 겁니다..."
rows["145:1867147194"]="가장 좋은 낚시는 남동쪽 크라사랑 야생지대의 어글러스 바프에서 찾을 수 있습니다. 누구나 우리를 방문하여 낚시줄을 들고 갈 수 있습니다!"
rows["145:1908589825"]="잘라제인을 물리치려면 죽은 이들의 수호자, 브원삼디와 화해해야 한다. 다른 방법은 없다. 센진의 아들에게 돌아가 그대로 전해라."
rows["145:1914045108"]="비탈 아래에 조종 장치를 몇 개 설치해뒀어. 빨리 하나를 잡고 지옥절단기를 조종해! 시간은 얼마 없어."
rows["145:1915418140"]="오! 케켁 이제 알겠다. 큰 용 여자한테 깔리기 싫다. 사람 적을 때 다시 오던가 하자. 반가웠다, 용 여자."
rows["145:1935984989"]="파다렌들은 이 \"더더킹\"의 귀환에 대해 깊은 우려를 갖고 있지만, 저는 더 호드에 대해 걱정하고 있습니다."
rows["145:1938292464"]="힌클스, 그 윙링 브론즈 기즈모와 신선한 봄수 좀 줘"
