rows["145:1947890917"]="우리가 시작하기 전에 적에 대해 말해줄게 들어봐요. 우리가 현장에서 스컬지를 파괴하는 동안 준비되지 않으려구요."
rows["145:1961594530"]="여기, 다양한 공예술을 숙달한 몇몇을 찾을 수 있습니다. 여행에 필요한 물품이라면, 그들은 아마도 도움이 될 것입니다."
rows["145:1983357946"]="물이 급하게 들어왔을 때 그들은 우리를 공격했습니다. 거의 무슨 일이 일어날지 알고 있는 것처럼 보였다.$B$B그들은 모두 그들이 한 일에 대해 고통받아야 합니다."
rows["145:2000258621"]="그를 이길 수는 없다. <유물이 완전히 타서 사그라집니다. 유물에 담겨 있던 기억을 고스란히 물려받았습니다. 이 도시는 이 세계에 속하지 않는 존재에 의해 파괴되었습니다.>"
rows["145:2006221557"]="난... 호드를 실패했어...$b$b가로쉬가...$b$b내 백성들을 망칠게 해"
rows["145:2034351735"]="네가 가야 해 스톰윈드 만약 당신이 제주를 배우고 싶다면, 그 곳의 왜적 중 한 명이 당신에게 그 직업을 가르쳐 줄 수 있을 것입니다."
rows["145:2043310699"]="톨바라드에서의 승리 우리 몫입니다. 얼라이언스 공격이 마비되어 있는 동안, 우리는 즉시 자원을 모으고 섬을 안전하게 만들기 위해 여러분의 노력이 필요합니다!"
rows["145:2073459477"]="천 Needles가 동쪽 산들을 무너뜨렸어 남해가 쏟아져 들어갔고,"
rows["145:220468871"]="여자들이여, 신사 숙녀 여러분, 이 해체된 자들은 승리했습니다! 다음 라운드에 대한 베팅은 지금 시작됩니다."
rows["145:274214537"]="|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s는 |cFFF00000|Hspell:117283|h[청소수물]|h|r에 의해 치유될 예정입니다! 그를 이동하십시오!"
rows["145:285882846"]="우리는 놈들을 몰아낼 것입니다, 아나크로노스. 내 맹세하지요. 그대는 이번 임무를 끝까지 완수해야 합니다. 우리의 운명은 그대 손에 달렸으니 망설이지 마십시오."
rows["145:323850997"]="독이 퍼진 다리가 훨씬 좋아졌습니다. 해독제가 효과가 있었나 봐요. 실례가 안 된다면 저는 상관께 여기서 밝혀진 일을 보고하러 가야겠습니다."
rows["145:353508950"]="한 번 더, 나조트의  ⁇ 어지고기 깃발들이 이 세상의 날려버린 시체 위에 비명을 지을 것입니다."
rows["145:403842305"]="우리는 스컬지의 재앙을 그들에게 돌리기 시작했지만 우리의 지지가 가장 잘 되지 않습니다! 그들의 가솔린을 무너뜨리면서 그 원인에 도움이 될 것을 확신하십시오!"
rows["145:406055892"]="우리의 챔피언들은 이 일을 활성화하기 위해 많은 피를 잃었습니다 스컬지 운반자, 복수할 준비가 돼야 해요"
rows["145:417780062"]="돌아가면 분명 표창을 받겠지. 피해가 조금 있긴 했지만, 전체적으로 꽤 잘했잖아. 그렇지, 발란나?"
rows["145:42974098"]="<오릭은 코믹을 구하기 위해 애도심을 가지고 왔다고 생각하며, 그 이유는 그를 격려하기 때문일 뿐이라는 것이다.>"
rows["145:46620612"]="아직도 어떻게 우리는 그립 없이 천개의 바늘을 통과할 수 있었는지 모르겠지만, 그늘이 없는 곳에서  ⁇ 고 타버렸어요!"
rows["145:486153151"]="엘루네가 찬양을 받으소서, 당신은 우리의 워싱글 쿨 전투 마스터를 찾고 있습니다. 그녀의 이름은 아에탈라스이며, 그녀는 전투 훈련자 근처에 당신을 환영하기 위해 준비되어 있습니다."
rows["145:489614534"]="시라라는 결혼 초청을 보내는데 당신 때문이라고 들었어요$b$b고마워요 이제 난 가족의 결혼하지 않은 흑인 야크가 될게"
rows["145:492515647"]="이제 검은 성전 열쇠가 있으니\010 블랙 템플로 직접 이동할 수 있어"
rows["145:535523711"]="내가 너에게 교훈을 줄려고 했지만, 네가 내게 가르쳐줬어."
rows["145:55481908"]="내가 말했잖아, 난 방해된 브리치블록에 톱니가 있는 스레드를 원해 "
rows["145:606417151"]="토끼발과 여덟 개의 동전들은 누가 더 운이 좋는지 논쟁하고 그 멍청한 거북이는 주머니에 똥을 찾는 것보다 더 행운이 없다는 것을 잊고 있습니다."
rows["145:614113697"]="넌 내 능력을 뛰어넘어, 어릴 적 썬더 블러프중앙 고원입니다. 그녀가 원하는 방향을 제시할 수 있습니다."
rows["145:622518700"]="이 포털은 먼 타나리스에서 땅 아래 깊은 시간의 동굴로 이어집니다.$B$B내가 당신을 보내줄 수 있는 힘을 가지고 있어"
rows["145:666793967"]="내가 얼마나 똑똑한지 보여줘요, 보스!$B$B스립키크가 자기에게 마술을 써도 좋을 것 같군"
rows["145:715958075"]="로얄 엑스체인 경매소는 동부에서 발견될 수 있습니다."
rows["145:735117480"]="|TInterface\\Icons\\achievement_dungeon_ulduarraid_titan_01.blp:20|t 당신은 |cFFF00000|Hspell:144359|h[티탄의 선물]|h|r와 함께 축복받았습니다!"
rows["145:746960192"]="불행 히, 뱀 을 번식 시키기 위한 우리 의 노력 은 실패 하였다. 우리는 주의 깊게 야생 뱀 들 에서 몇 개의 알 을 가져서 자신 으로 키우게 됩니다."
rows["145:764146070"]="심장... 네가 인간이었음을 알려 주는 마지막 흔적이지. 난 그 심장이 파괴되는 걸 막으려 했다. 내 눈으로 직접 확인하고 싶었지. 하지만 이젠 알겠다..."
rows["145:790337530"]="착각성 앰버 웨이버는 당신 쪽으로 떠다니고 다른 접촉에 폭발하는 앰버 볼을 불러일으키죠."
rows["145:805812268"]="그렉이 쥐고 있어$b$b네가 그를 도와줄 때, 그가 너에게 한 개를 줄지도 몰라 다음번 북쪽 블루 스카이 목장에 있을 때, 그와 얘기해봐"
rows["145:822582471"]="코렌이 죽었다니 유감이군요. 그 친구한테 맥주를 사들여서 물 좀 섞고 제 상표를 붙여 팔았으면 꽤 짭짤했을 텐데 말이에요!"
rows["145:843850631"]="우리의 검으로 이 땅을 손에 넣고 우리의 농기구로 이 땅을 일구어 나갈 것입니다! 여러분은 거친 땅을 길들인 자로서 두고두고 기억될 것이오!"
rows["145:851072063"]="걱정 마, 내가  ⁇ 색 래셔를 안전하게 데려갈 거야"
rows["145:865531873"]="<너의 놀라움으로, 랩터 새끼는 당신과 소통할 수 있습니다.>$B$B헬멧이 부족해지면서 지적 능력이 떨어지는 걸까요?"
rows["145:883689382"]="믿으세요. 가로시 지옥의 비늘이 테라모어에서 달성한 것은 지금 우리 취약한 가정에 닥치는 공포와 비교할 수 없는 일입니다."
rows["145:928142147"]="까마귀가 찾아오고 하늘에 어둠이 깃들면 오래된 피가 다시 한 번 흘러내릴지니. 붉은 밤이 찾아오면 과거가 깨어나리라."
rows["145:94630366"]="벨의 통세에 그것은 될 것입니다 10:00오늘 날씨 예측에서 더 많은 녹색 독성 죽음의 구름이 있을 것 같습니다."
rows["145:998613170"]="마음이 바뀌었다, 충성스러운 종들이여. 죄수를 내 서재까지 데려올 필요 없다. 여기서 직접 처리하겠다. 빈센트!"
rows["146:108062928"]="내가 보는 것은 내 가문이 제 주변에서 사라진 기억으로 줄어드는 것인데 한때 모든 맥주장들 중 가장 위대한 사람이었던 우리는 이제 스톰스타우츠의 무대에 서 있습니다."
rows["146:1088701562"]="저는 이 말을 듣고 기쁘다. 모그들의 최근 행동은 저를 매우 괴롭히고 있습니다. 그들은 거의 10천 년 동안 이런 조직적인 방식으로 행동하지 않았습니다."
rows["146:113210287"]="기즐턴 짐마차가 출발할 시간이군! 곧 돌아오겠지만 기다릴 수 없다면 북쪽 코르멕의 오두막으로 와. 한 시간쯤 뒤에 가게를 열 거야."
rows["146:116984514"]="글은 발견한 사람이야 내 가족에 대한 소식에 고마워요"
rows["146:1221832876"]="나이트 엘프나  ⁇ 의 건설 현장에서 뱀 기름을 사용해서 발전 속도를 높여라! $B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t"
rows["146:1225541273"]="여기선택한 사람들이 그들의 운명을 깨닫고, 그리고 여기서 당신은 당신의 운명을 깨달을 것입니다."
rows["146:1234580964"]="너희 좆같은 신조들이 내 남편을 빼앗아갔어!"
rows["146:128479619"]="손목을 찢고 싸움을 준비했어요$b|TInterface\\Icons\\inv_gauntlets_05.blp:32|t  |TInterface\\Icons\\inv_inscription_pigment_emerald.blp:32|t$b"
rows["146:1284945186"]="우린 그들을 파괴할 거야 그들의 피가 우리 검에 자유롭게 흐르겠지 우리가 드레네이를 파괴했듯이, 이제 우리는 인간을 파괴할거야\010"
rows["146:1291089108"]="|TInterface\\Icons\\spell_fire_twilightcano.blp:20|t 울트라시온의 불안정성은 거대한 |cFF9900CC|Hspell:106388|h|h|r!"
rows["146:1306499691"]="만약 호드이 우리를 전쟁의 가장자리에 밀어 넣으면, 그렇게 되길 바랍니다.$B$B빛은 나를 도와줘, 나는 내 왕국과 내 백성을 위해 싸울 것이다.$B$B얼라이언스의 영광이 있으소서"
rows["146:1345702214"]="무의미해 보일 수 있습니다만, 멋진 시합에서 자긍심을 얻도록 해 보세요. 이런 연습과 경쟁 모든 게 뜻있게 쓰일 때가 올 겁니다."
rows["146:1377590804"]="위기가 울고 있다면, 갈리 장관 스틸벨리와 얘기해줘, 하지만 우리 둘 사이에만 기다려봐"
rows["146:1378120045"]="아, 블랑쉬. 너무 걱정하지 마. 서부 몰락지대에 있는 내 형제가 널 잘 돌봐줄 거란다. 네가 마음껏 뛰어놀 수 있을 만큼 넓은 아름다운 농장을 가지고 있다는 말을 들었단다."
rows["146:1387902825"]="소크레타르, 우리의 수가 적을지는 모르지만 신념만큼은 굳건하다. 너는 절대 이해하지 못하겠지. 관례는 지켰으니 최후를 맞이할 준비나 해라."
rows["146:1416872360"]="해마르의 형제들아 내게 이르라 불신자들이 아직도 서 있나니 그들을 멸망케 하라"
rows["146:1454262476"]="저는 숙제실의 엔지니어가 있는 것을 기억하고 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["146:1590586790"]="그레이즈시즌에 드루이드들은 주변 사람들에게 친근한 친구가 될 수 있습니다."
rows["146:1621129755"]="나무에서 목을 꽂고 바람에 흔들려 두면 얼라이언스가 발견할 거야"
rows["146:1648132405"]="어디서 왔는지 모르겠지만 오늘처럼 정의를 위해 계속 서면 파다리아에 환영받습니다.$B$B- 고마워요"
rows["146:1663623489"]="이 땅이 어떻게 되었는지 보고 안타깝지만, 센라리온 탐험대는"
rows["146:1674287403"]="뭐, 결국 생각이 바뀌었잖아 조심하라고 했잖아$B$B이번엔 용서해줘요, 무슨 달걀이 진짜 필요해요?"
rows["146:168703383"]="완전 승리로! 당신의 재창조와 효율성 덕분에 우리는 한 영혼도 잃지 않았습니다. 이 상과 함께 저의 진심으로 감사한 마음을 받아보세요."
rows["146:1688181071"]="샤트트라스의 숙소는 부상자 난민들로 가득 차 있지만, 여전히 알도르 라이즈와 스크라이어 계층에 있는 드레네이 알도르와 피 엘프 스크라이어들 사이에 공간이 있습니다."
rows["146:1691476362"]="그 바람은 하수인들을 보내 자네 종족에 전해 내려오는 이야기를 바꿔버리고 명예롭게 죽어간 자들의 영혼까지 파괴하면서 이곳의 역사를 왜곡했다네."
rows["146:1708770423"]="그 뒤틀린 드레나이 벌레 녀석이 지팡이를 줬군. 그렇지? 자기가 바로 동족을 팔아먹은 장본인이라는 말도 하던가? 어찌 됐든 네놈들은 대가를 치러야 한다!"
rows["146:1716649731"]="여기 너무 많은 생명과 공간이 있습니다.$b$b돌아다니는 섬에는 사냥할 만큼 큰 맹수들이 살 수 있는 공간이 없었습니다."
rows["146:1736632034"]="이 왜곡된 세상은 속인 영웅들의 손길이 닿지 않는 곳이고 부패에 대한 유일한 해결책은 파괴입니다. 그리고 그것은 지금부터 시작됩니다."
rows["146:1838615004"]="너희 운명이 결정됐다. 너희와, 이 작고 가련한 세상에 사는 모든 것들에게 마침내 종말이 닥친다. 우울위 이피스 할란 가그 에르옹그 위스..."
rows["146:1851561026"]="잠이 짧았다고 보는데 언소크가 저쪽에 있다는 걸 알아봤어요. 그는 자신을 앰버샤퍼로 명명해줬다고 보는데. 그의 능력은 내 능력을 결코 뛰어넘지 않았습니다."
rows["146:1910700430"]=" ⁇ 은 테일드라실의 기지에서 루트테란 마을에서 로르다넬로 떠난다. 다르나서스에 있는 포털은 안전하게 루트테란을 도달할 수 있게 해 줄 것이다."
rows["146:1917202275"]="물론 탐사선수연맹은 어리석은 상황에 빠졌고,\010물론 우리는 이 기회를 활용할 것입니다."
rows["146:1988894315"]="북풍은 예로부터 타운카의 적이었네. 그는 정령의 군주이자 부족민의 목숨을 오랫동안 앗아간 존재라네."
rows["146:1995384392"]="샤트라트에는 두 개의 은행이 있습니다. 두 은행은 도시 중심부의 가장자리에 있습니다. 하나는 드레네이 알도르, 다른 하나는 피 엘프 스라이어스가 운영합니다."
rows["146:1999466930"]="Fel Rock에 들어가기 전에 나무 꼭대기에 있는 Tallonkai Swiftroot에게 말해주세요."
rows["146:2046511213"]="분명히 여러분은 이 땅으로 전쟁을 가져오기 위해 여기 온 것이 아닙니다."
rows["146:2054587401"]="당신 입맛이 들어있어요, 낯선 사람.$b$b여기서 무슨 뜻이야?"
rows["146:2122190715"]="그때 네가 내 손을 강요해 놓았어 내가 오래 전에 저지른 실수를 바로잡을 거야 바람의 영, 땅, 물의 영혼들 내 부르짖음을 들어줘"
rows["146:2131071342"]="선리버스 대신, 대회에 오신 것을 환영합니다. 아르헨티나 십자군 전쟁은 참가자 등록을 요청하고 훈련합니다."
rows["146:233499478"]="저는 실크를 만드는 더 생산적인 방법을 찾아내야 했습니다. 제 자부심으로 괴물을 만들었어요. 이것은 내 생애 마지막까지 내가 가져갈 수 있는 수치입니다."
rows["146:242302814"]="우린 도움 없이 처리할 수 있어 물러나라. 네가 돌아왔을 때 황후가 죽고 네 문제가 해결됐다고"
rows["146:266648739"]="저기로군! 벡터 코일에서 거대한 붉은색 수정이 튀어나온 부분이 보이오? 저곳이 바로 첫 번째 폭탄을 설치할 위치요."
rows["146:331674738"]="진정한 영웅은 전투에서 승리만을 목표로 하는 것이 아니라 마지막 화살이 떨어지면 지속적인 평화를 이루는 것을 목표로 한다."
rows["146:333831108"]="챔피언, 당신은 내 기대를 뛰어넘어 제 섬에 우리의 위치가 보장되었습니다."
rows["146:334867907"]="어찌 됐든, 네가 죽어서는 안 되지. 그렇게 되면 나까지 사라져버릴 테니까. 그렇지? 하지만, 내가 너였을 때는 이 자리에 내가 있었는데... 아아, 헷갈려!"
rows["146:360597870"]="그 전투 후에, 전장에서 검을 찾아냈다. 그리고 왕자님을 모시고 그 검을 노스렌드로 가져갔지. 우리 종족의 패배를 설욕하려 말이다."
