rows["146:435072609"]="난 배포에서 일했고, 수년간 새끼를 훈련시켰어요. 집에 있는 건 좋죠. 무슨 일이 벌어졌든, 이건 내 집입니다."
rows["146:439863473"]="진짜 챔피언을 만나야 돼, 내가 너에게 도망갈 기회를 주겠다."
rows["146:458542584"]="카너타드는 너무 많은 펠에너지로 자신을 감싸고 있어 완전히 손상시켰지만 그의 힘의 작은 맛은 해롭지 않아야 합니다."
rows["146:481656113"]="최근엔 이런 쉐도파인이 없었어요$b$b다음 마티드 무리가 되기까지는 몇 년이 남아있어야 했습니다."
rows["146:497080631"]="판다렌 공사장에서 폭발조제용 기 ⁇ 에 있는 정글 홉을 이용해 발전을 촉진하세요! $B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t"
rows["146:501481977"]="바리안 폐하의 SI:7 요원들은 투영의 전당이라 불리는 곳 깊숙이 자리 잡은 리치 왕의 개인 성소에 대한 정보를 수집했지요."
rows["146:531839549"]="칠흑의 기사단도 함께할 것이다. 비록 너희 사이에 우리 자리는 없겠지만, 리치 왕을 끝장낼 때까지 싸울 것이다! 맹세한다!"
rows["146:602797940"]="하지만 농장은 꽤 잘 생겼어 여기 있는 사람들과 친구가 되면 더 멋지게 만들 수 있을 거야"
rows["146:609878327"]="다리와  ⁇ 을 가지고 있는 능력이 있지만 충분하지 않아 다인 린드그렌에게 가서 내가 가르쳐야 할 것을 배울 준비가 될거야"
rows["146:610854905"]="이 유적 안에 많은 고대 모가 비밀들이 있습니다. 이 모든 계곡은 한때 그들의 것이었고, 그 어떤 구석도 아직 판다르 발에 걸리지 않았습니다."
rows["146:648351505"]="이 물건은 철군을 파괴해야 해 더 나은 건 얼굴에 폭발하지 않을 거야 내가 본 기계들과 달리"
rows["146:659508493"]="내가 어떻게 생겼나, 마법사의 큰  ⁇ ? 당신의 능력은 공예의 지도를 필요로 한다! 아조라 타워에서 Kitta Firewind를 찾아라."
rows["146:712424201"]="저는 제 형제처럼 조상들을 존중하는 사람들을 존중합니다. 달 축제의 제자들에게 제 기획 비밀을 공유하는 것이 큰 기쁨입니다."
