rows["147:49980253"]="더 이상 통나무 바가 없어 팔도 다리  ⁇ 어 걸렸어요"
rows["147:573805859"]="더 많은 훈련을 할 수 있는 것은 내 능력 이상입니다. 다르나서스그는 항상 재능있는 학생들에게 도움을 주는 것을 기쁘게 생각합니다."
rows["147:586016036"]="|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t스카이파이어에 대한 구조적 손상으로 갑작스러운 |cFFFF0000|Hspell:110095|h|h|r!"
rows["147:586735977"]="아드미럴, 테라모어의 함대의 잔류를 보내 밤 엘프들에게 도움을 주고 우리의 사안에 참여하려는 모든 캡틴에게 표창을 발급해 주십시오."
rows["147:594754949"]="스컬지가 우리를 공격하는 이유는 분명 빛의 수호자의 징표가 지닌 순수함 때문이오. 당하지 않으려면 조심해서 전진해야 하오!"
rows["147:612403512"]="지상 공격을 하기 위해 충분한 물품이 있습니다. 명령 보내고 자격을 갖춘다고 생각한다면,"
rows["147:698030766"]="네, 물론 내가 도자야 왜 왜 왜소들이 그 무게를 가진 유일한 사람이라고 생각하니?"
rows["147:705752479"]="하지만 나이든 정신들을 걱정해야 합니다. 아직 배울 게 많아요. 다크스피어 사람들을 도와주세요."
rows["147:736960560"]="이 괴물 날개가 내 위에 무너져 내 고통을 없애고 난 더 빨리 더 빨리 치게 될 거야"
rows["147:75827156"]="마지막 황제는 우리 땅을 다른 세상으로부터 숨겼을 때, 그는 고대 적인 만티드의 고향도 보존했습니다."
rows["147:764067101"]="이해할 수가 없군! 당신 눈이 멀기라도 했나? 저 밖에 악마들이 우리 문을 두드리며 쳐들어오려는 게 보이지 않나 보지? 누굴 보내서 당신의 주술사 친구들을 도우라는 거요? 골라보시오!"
rows["147:80669485"]="이 지역은 우리 세계를 찢어 버릴 위협이 되는 재앙의 진앙 중 하나입니다.$b$b생존을 위해 노력한다면 그 원인을 찾아내야 합니다."
rows["147:917306667"]="날 물리치고 내가 타고 있는 죽음의 전하를 빼앗아 내 삶을 되찾을 유일한 방법은"
rows["147:921946918"]="나도 널 보고 기쁘다, 그리임! 모든 낯선 사람이 두려워할 필요는 없어 보인다. 그래임?"
rows["147:941093874"]="돌아가면 분명 칭찬을 받을 거예요. 피해는 약간 보았지만 전체적으로 꽤 잘한 것 같아요. 그렇지 않나요, 발란나?"
rows["147:950422633"]="마법에 집중한다면 아이언포지에 한번 봐라."
rows["147:952179992"]="시간이 너의 적인 이 세계에서 그 시간이 나의 가장 위대한 동료다. 네가 네 맘대로 조종하고 있다고 믿는 인생이란 놀이가 사실은 널 갖고 놀고 있는 것이지. 그러니까 내 말은..."
rows["147:953733134"]="전투는 두 배에 모두 영향을 미쳤고, 구조팀은 안전할 때 남은 것을 확보할 겁니다."
rows["147:979018058"]="만약 당신이 나를 따라오기로 결정한다면, 조심해 어둠의 해안의 동물들은 나에게 해를 끼치지 않을 것이지만"
rows["147:989433887"]="이 배가 죽음의 날개를 격파한 거야. 당신은 어떤  ⁇ 은 작은 호드 전두환이 얼라이언스 함대의 자부심을 상대로 기회를 가질 수 있다고 생각하십니까?"
rows["148:1044403668"]="가로쉬는 명예와 힘에 대해 계속 이야기하지만, 사실 우리의 지도자는 두 가지 결과를 볼 수 있습니다."
rows["148:1052065533"]="자, 이것으로 소환에 대한 수업은 모두 마치도록 하겠네. 곧 다음 수업이 시작될 테니, 복습하고 싶다면 여기 계속 머물러 있어도 좋네."
rows["148:1065744814"]="도시 곳곳에 격차가 발생해 전투를 준비하지 않은 시민들을 모두 탈출시켜 안전장치를 확보해야 합니다"
rows["148:1090871726"]="거대한 폭발이 그 지역을 뒤덮었을 때, 내 아버지께서는 우리 적의 손에 넘어가지 않도록 그 거대한 망치에 룬 마법을 시전하셨다. 그분이 행하신 마지막 일이셨지..."
rows["148:1112985208"]="스피릿스밸리에서 호수 옆에 있는 다크브라이어 로지에 가서"
rows["148:1138431511"]="돌 안에서 분명한 목소리가 떠오르고...$B$B공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작자, 공작님, 공작님, 공작님, 공작님, 공작님, 공작님, 공작, 공작, 공작, 공작 등 등 등 등 등 등 등 등"
rows["148:1143765899"]="이제 생명의 탄생을 기념하는 시간입니다. 그리고 계란은 봄과 재탄생을 상징합니다."
rows["148:1182519336"]="안녕, 낯선 사람, 내 꿈의 맥주 샘플을 가져왔어? 그 비전은 해석하기 어렵죠. 반 진실, 반 환상. 누가 어떤 것이 어느 것이냐는 걸 말할 수 있겠는가?"
rows["148:1190453335"]="<빛이 빛나는 시선은 당신의 존재를 인정하지 않습니다. 그녀는 자신의 세계에 사라지고, 수천 년 전에 일어난 사건에 반응합니다.>"
rows["148:1206471469"]="오타 웬의 눈에는 이상한 빛이 불어오면서 그는 곧게 서서 하늘을 향해 울고 있습니다.$B$B네, 우리는 일어나서 우리의 수감자들을 파괴할 것이다!"
rows["148:1215884348"]="잘, 내가 가르쳐주면 동맹국들에게 큰 피해를 주지 않을 것 같네요."
rows["148:1217347868"]="샤트트라스의 지도력은 너무 느려서 행동하기 때문에 하위 도시의 위대한 사람들은 그림자 람락의 문제를 우리 손에 맡겼습니다."
rows["148:1274142890"]="아, 당신은 내 아내가 아니로군. 하지만, 그녀와 만난 적이 있군. 그녀를 만나거든 내가 추락에서는 살아남았으나 이곳 침투요원들에게 죽임을 당했다고 전해 주시오."
rows["148:1284509371"]="넥서스 왕자 하마담은 내가 차기 시험 대상이 될 것이라고 말했어요.$B$B그는 블러핑을 하지 않았습니다."
rows["148:1294999241"]="우리가 누군지 알아내지 못해? Godfrey입니다."
rows["148:1301188365"]="어떻게 나의 사람들이 어떻게 싸울 수 있을까요? 요소들이 이렇게 혼란스러울 때?"
rows["148:1315248731"]="스컬지이 순수한 땅에는 결함이 있다. 내 창조자의 힘으로, 내 발목 아래 그들의 쇠퇴한 뼈들 중 한 개라도  ⁇ 을 것이다."
rows["148:1334333898"]="난 이  ⁇ 한 XX와 충분한 시간을 보냈고 부상 치료에 대해 한두 가지 배웠어"
rows["148:1338422384"]="젠 마스터 라오를 찾고 있을 거야. 그는 영원한 꽃의 계곡에 있는 서식하는 태양 기병에서 일하고 있어.$B$B네 지도에 그의 위치를 표시해 줄게"
rows["148:1383484014"]="아라토르 동맹은 스트롬가르드와 얼라이언스의 사람들을 위해 아라티를 되찾겠다고 맹세했습니다."
rows["148:1401443047"]="난 네 비밀을 알고 있어 외래인 너가 적이야$b$b내가 너한테는 겁이 안 돼 난 약자야"
rows["148:1430846070"]="그럼 우리랑 함께 증오의 샤를 사냥해봐라오진이군 이 사람들은 다리를 지키고"
rows["148:1436791376"]="내가 네가 싫어하는 저질환자 중 한 명을 영구적으로 쫓아내려고 했지"
rows["148:1457527711"]="여기에는 종종 맹수들이 있지 않습니다. 가끔 비가 오면 사루크가 나오죠. 하지만 비는 번개 때만요."
rows["148:1519095962"]="- 누구신?$B$B가요, 하버로드에서 열심히 일해서 지쳤어요."
rows["148:1560504173"]="마라우돈으로 가는 문 근처의 오렌지색과 보라색 경로 사이에 세 번째 길을 찾을 수 있습니다.$B$B당신이 손에 쥐고 있는 왕자 막대기란 열쇠입니다."
rows["148:1598259209"]="언덕 아래 조종장치를 몇 개를 만들어 놓았네. 빨리 아무 조종장치나 선택해서 지옥절단기를 조종하게! 시간이 얼마 없단 말일세."
rows["148:1611964763"]="난 약해졌어요. 빛 오크 음식이 날 망치게 해"
rows["148:1680451207"]="공중에서 날아다니는 것 보다 더 흥미진진한 것은 없습니다.$B$B어쩌면 공중에서 날아다니면서 싸우고 그 후에 맥주를 마실 수 있을지도 몰라요"
rows["148:1766738279"]="내 아들은 파란색 깃털을 발견했을 때, 하늘로 있는 그의 어머니로부터 키스를 받았다고 말하곤 했습니다.$B$B<노인 힐파우가 멈추고, 계속할 수 없을 정도로 질식하고 있습니다.>"
rows["148:1770725038"]="아니, 이럴 수가... 이 생물이 자진해서 군단의 하인이 됐다고 적혀 있어. 사티로스로 변하고 군단의 '축복'을 받았대."
rows["148:1797293925"]="꿈에서 머무는 동안 중요한 발견을 했습니다. 이 세상의 경계를 약화시키는 균열은 강력한 동맹국들의 귀환을 가속시켰습니다."
rows["148:1851657873"]="지식의 자리에 오신 것을 환영합니다. 그리고 판다리아의 고대 시대에 대한 정보와 지혜를 더 많이 찾을 수 있는 저장소가 없었습니다."
rows["148:1852105581"]="우리 동맹국들의 도움과 우리를 돕기 위해 온 호드의 일원들을 잊지 말자! 이제 이 위대한 승리를 함께 축하할 때가 되었습니다."
rows["148:1884609247"]="얼마나 아픔스럽지, 나는 영혼살상자의 힘을 가지고 있어 전능한 하카르의 분노를 두려워하고"
rows["148:1951443821"]="전 지식 추구에만 살았어요$b$b이제 저는 깨어 있는 모든 시간을 우리 민족이 잃어버린 불멸을 다시 살릴 수 있는 방법을 찾고 있습니다."
rows["148:2011800164"]="이번에는 낙스라마스에 있는 저주받은 거미의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 더욱 독성이 강하고 위험한 놈들을 만들어내고 있다."
rows["148:2017337437"]="이제 네가 가서 해냈어 내가 생각했지 네가 사우스셔의 사람들보다 낫다고"
rows["148:2056599850"]="우리가 연합하는 상징을 바라보고 있습니다. 이 다고입니다. 그것은 건설하고 만드는 다고입니다. 하지만 또한 그것이 때리고 파괴하는 다고입니다!"
rows["148:2072691682"]="우리가 필요로 했던 마지막 일은 미친 드라카리 트롤들이 우리 뒷마당에 있는 스컬지 네크로폴리를 격추하는 것이었습니다.$B$B어떻게 그렇게 할 수 있었나요?"
rows["148:2110020875"]="우리는 호드와 얼라이언스의 지도자들과 협상해야 한다. 라그나로스는 고향에서 패배해야만 한다."
rows["148:2141313647"]="만약 당신이 동전을 가지고 있다면, 나는 당신의 식욕을 만족시킬 수 있는 음식과 음료수를 가지고 있습니다."
rows["148:236106046"]="난 널 냄새 맡고 있어 외래인$b$b왜 우리 마을로 몰래 들어왔어요?"
rows["148:293619002"]="투기장에 들어오는 저 성기사는 전쟁터에서도 마상시합 광장에서도 널리 알려진 인물입니다. 은빛십자군 최고 용사, 성기사 에드릭을 소개합니다!"
rows["148:312108187"]="어떻게 사들이 그들의 고대 감옥에서 벗어났는지는 중요하지 않습니다. 우리는 앞으로의 행동을 계획해야 합니다. 어떻게 그들을 다시 우리 땅에서 쫓아낼 수 있을까요?"
rows["148:323155118"]="선택의 여지가 없었어요, 그들은 저를 알아냈어요. 제가 존재한다는 것을 아는 유일한 사람들은"
rows["148:327255260"]="우리는 베틸라크의 번식지 가운데 서 있습니다. 북쪽의 기둥 너머에 그녀의 새끼들이 기다리고 있습니다. 그들은 그녀의 새끼를 끊임없이 방어할 것입니다."
rows["148:337392405"]="카라잔 아래의 동굴에서 그녀를 발견했는데 그녀의 목숨을 두려워하고 그 밑에 숨겨진 비밀들을 연구하고 있습니다."
rows["148:339072729"]="케잔의 첫 은행에 오신 것을 환영합니다.$B$B오늘 내가 뭘 도와드릴까요?"
rows["148:357307773"]="보다시피 네 백성은 이제 내 손에 들어왔다. 이 도시의 모든 집을 하나씩 하나씩 찾아가 주마. 생명의 불씨가 영원히 꺼질 때까지..."
rows["148:380039034"]="너 미쳤어? 주변을 봐, 필사자. 네가 찢어진 땅 위에 서 있는 것을 보지 못해?"
rows["148:458649786"]="세계의 자연적인 과정을 축하하는 것은 어리석은 일입니다. 우리가 축하하든 그렇지 않든, 그것은 일어날 것입니다. 하지만 그것은 설탕에 대한 훌륭한 변명입니다."
rows["148:470816825"]="우리가 돌아오는 전에, 아마도 이 지역에서 자라는 증강된 채소를 수집해야 할까요?"
rows["148:473015512"]="왜 다른 것을 배우고 싶지는 모르겠지만, 내가 옳은 방향으로 안내할 수 있겠죠."
rows["148:477180806"]="그는 티탄의 모든 창조물이 '육체의 저주'에 걸린 거라고 주장하더군요. 태초의 노움은 기계노움이라나요."
rows["148:503326245"]="리스리더는 처음에는 좀 겁이 나지만, 당신이 찾는 걸 보관하고 있어요."
rows["148:505396240"]="우리가 아는 것은 크루시코가 발전된 기계 탱크 프로토타입을 사용하고 있고 그의 방사선 기둥들은 오래된 무기장에서 더 많은 것을 수리하려고 노력하고 있다는 것입니다."
rows["148:543512782"]="믿어요, 친구. 급속한 약을 먹으면 더 낫습니다. 긴 고통스러운 인체온난과"
rows["148:587830305"]="그토록 충직하게 날 섬겨주니 참으로 기쁘구나. 머지않아 모든 이가 켈투자드를 섬기게 될 것이며, 너는 단단히 흔들리지 않는 한 수확을 얻게 될 것이다..."
rows["148:601187353"]="경비원들이 방문할 때, 우두머스 유물과 그 아름다운 그림을 어떻게 찾았는지 설명해줄 수 있을 것 같군요."
rows["148:66673845"]="제 첫 실험이 잘못되었던 기억입니다. 이 들들은 이 시대에는 볼 수 없었던 슈퍼  ⁇ 으로 가득했습니다."
rows["148:683541595"]="이 곳의 성공률이 얼마나 낮건 상관없습니다. 만약 우리가 한 번이라도 숲의 광신과 야만에서 구한다면, 우리의 투쟁은 헛되지 않을 것입니다."
rows["148:783820888"]="카이른이 살고 있다고 합니다. 그리고 내가 적절한 선물을 만들면 그를 찾아서"
rows["148:838349366"]="라드나알은 나디아에게 그가 껍질을 벗는 동물들의 가죽을 많이 공급해 줍니다."
rows["148:860672842"]="너의 존재는 인정하는 바이다. <유물이 먼지로 변해 버립니다. 새로 얻은 지혜로 인해 머리가 고동칩니다. 이 산의 정수에 사악한 무언가 잠재해 있다는 것이 느껴집니다.>"
rows["148:867744053"]="너희가 전투에서 쓰러지면 너희에게는 선행이 있을 것이며 그가 일어나자 너희는 그의 편에 있으리라"
rows["148:879994894"]="접근...\010공학기능\010 \01001000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\010접근이 금지되어 있습니다!"
rows["148:884491931"]="미사일 생성기의 제어 단위는 탑의 최상층에 있습니다. 만약 당신이 거기에 올라갈 방법을 찾을 수 있다면, 당신은 그것을 스스로 끄고 있습니다."
rows["148:885213805"]="네파리우스가 나를 강하게 만들었다. 내 혈관에는 네파리우스의 증오와 검은바위 부족의 분노가 흐르고 있다!"
rows["148:918572216"]="감염된 작물은 곤충으로 덮여 있습니다.$B$B할아버지의 곤충 스프레이어는 현장 근처에 있습니다. 그 동물들에게 해파람을 줄 수 있도록 사용하세요!"
rows["148:919291419"]="난 여전히 위험에 대해 경계하고 있습니다. 말푸리온과 그의 흙을 사랑하는 형제들이 꽤 미쳤다고 동의하지만, 이 사르게라스 경은 다른 일정을 가지고 있을 것입니다."
rows["148:929523996"]="내가 네가 모르는 것을 가르칠 수는 없는데, 하지만 내 아버지에 대한 지식은 내보다 훨씬 더 높습니다. 들어가서 이야기해 주세요."
rows["148:93608822"]="죄송합니다만 오늘 돌까마귀 선술집은 영업하지 않습니다. 위생 문제가 좀 많아서 말입니다. 에드가 사람들을 병에 걸리게 한다는 비난을 듣게 하지는 않으려 합니다."
rows["148:942272529"]="틴버링은 어업자들이 도라나르 주변에서 낚시하기 너무 어렵게 해 다르나서스."
rows["148:960174910"]="적들을 멀리하고 동시에  ⁇ 을 자르세요."
rows["148:964360699"]="제카라 대황후는 그녀의 진정한 의도를 모트론의 걱정으로 숨기고, 우리를 보호하기 위해 그녀의 지배적인 방법이 필요하다고 주장했다."
rows["149:1001039794"]="계획들을 작성한 후, 저는 제 최고 남성과 여성들에게 정확히 그 작업을 수행하기 위해 기계에 일을 시작하도록 했습니다."
rows["149:1015870883"]="이 세상에 시간이 많지 않지만, 빛의 뜻에 따라 제 운명을 성취할 시간이 충분해."
rows["149:1052185544"]="5분 후에 타우렌 치프타인의 콘서트가 시작됩니다."
rows["149:1062694103"]="난 연습생 교육을 제공하지 않습니다. 울고 있는 동굴에서 타우렌 월도르를 찾아보세요. 불모의 땅 그는 당신이 필요로 하는 모든 것을 도와줄 수 있습니다."
rows["149:1062737619"]="아주 오랫동안 나는 자신을 잃어버린 채 살았다... 악몽의 타락이 나를 지배해 왔지... 그리고 지금, 그대... 그대들이... 나를 구했다. 악몽의 손아귀에서 나를 해방시켰구나."
rows["149:1102450549"]="이 임무에서 살아서 다시 만나기를 바랍니다. 하지만 그렇지 않으면, 당신이 일하는 것을 보고 즐거웠다고 말하고 싶습니다."
rows["149:1125788674"]="습지에 좋은 가죽, 용기가 있다면 크로콜리스크가 많아요.\010내가 도와줄 게 있어?"
