rows["149:1149564318"]="이 계획의 참담함은 바로 제가 흥미를 느끼는 것입니다. 만약 우리가 해운대에서 침입한다면, 우리는 더 많은 장다라리 보강을 박탈할 것입니다."
rows["149:1157556948"]="감히 내 문간을 더럽히고, 내게 도전을 했겠다? 네놈들의 몸뚱이를 손아귀에 넣어, 죽음의 신께 제물로 바칠 것이다! 루알 냐 가볼!"
rows["149:1220077551"]="<서저인 스톰파이크 인사합니다>$B$B이름, 계급, 순위 번호 군인, 그 정보만 그 얼음 늑대 개들에게 줄 수 있어!"
rows["149:131030464"]="내 친구, 더 큰 힘을 추구하는 검은 용을 맹목적으로 신뢰한다면 당신은 가로쉬 펠스크림보다 낫지 않나요?"
rows["149:1351345344"]="원자들의 영은 지혜롭습니다. 그들은 우리보다 오래 전에 존재했고, 우리가 떠난 후에도 계속 존재할 것입니다. 그들이 우리에게 말할 때, 우리는 귀를 기울여야 합니다."
rows["149:1356928447"]="안 돼... 너무 늦었어. 사람들이 모두 감염돼 버렸군! 지금은 괜찮아 보일지 모르지만, 언데드로 변하는 것은 시간문제입니다!"
