rows["149:1616883299"]="이 거인들은 완벽한 동맹관일 겁니다. 이 사람은 그들의 지도자지만, 그는 계속 나와 대화하기를 거부합니다."
rows["149:1630373645"]="저 숫자 좀 봐요. 어마어마하네요... 스톰하트 왕께서 도와주러 오셨다니 다행입니다. 그분에 관해서라면 좋은 얘기만 들었거든요. 드디어 만나뵐 수 있겠네요."
