rows["149:174244394"]="용기가 아니라 내 앞에 걸어다니며 이 곳을 고향이라고 생각했지 바보야 곧 죽게 될 거야"
rows["149:1745794877"]="지구 감시자들은 이 집단의 싸움이 지구 반지의 일상을 위태롭게 만들지 않을 것입니다.\010평화를 깨는 사람들은... 엄하게 대접받습니다."
