rows["149:179157907"]="돌은 극심 한 추위를 불어넣고, 그 돌과 그 돌을 둘러싼 공기와 그 돌의 위를 감싸고, 그 돌의 안쪽 깊이에는 파란색 빛의 파동이 기다리고 있습니다."
rows["149:1802114315"]="내가 의심하는 건 틀렸다고 생각했는데... 그들은 마그마와르마를 부활시키고 있어."
rows["149:1821888971"]="호, 이것 참 놀랍군, 타사리안. 모그레인이나 다른 죽음의 기사들은 몇 달째 소식이 없는데. 다시 스컬지에 돌아오겠다는 의사로 받아들여도 되겠나?"
rows["149:1846597960"]="내가 언제 농부 윤이 나를 알아차릴지 궁금했는데, 오늘 시장에서 끝나면 거기 있을 거야"
rows["149:187832738"]="이 곳 에서 내가 창조 한 것 은 진화 이다! 포세이큰 는 어떤 마법 의 날개 있는 요정 이 시체 에 행복한 먼지를 뿌리면서 번영 할 것 이 아니라, 그렇게 번영 할 것이다!"
rows["149:1887978356"]="라스타칸은 나를 동생이라고 부르지만 호드 다른 사람들과 함께 그의 제국으로 들어가기 전에 그를 막아야 합니다."
rows["149:1892926838"]="하지만 Cenarion Circle의 많은 드루이드는 그가 Kaldorei 전체에 가장 좋은 것을 원하는 것을 굳게 지고, 그 목적을 위해 그를 일실히 봉사합니다."
rows["149:189979360"]="내가 마지막 싸움을 했을 때 상대가 울고 도망쳤는데, 그들이 도망친 것은 놀라운 일이 아니었지만, 악어개는 처음으로 눈물을 흘리는 것을 봤습니다."
rows["149:190862980"]="우리는 그들의 크리스탈 포지 연구하기 위해 바시르 착륙에 공격을 시작합니다. 당신이 할 수 있다면 우리를 도와! 우리의 스카이 가드 에더 기술 약 $4581d에 출발합니다."
rows["149:1935010978"]="멍청이들아, 그들에게도 늦었어 너희들 모두에게도 늦었어!"
rows["149:1956639136"]="힘. 그것은 단순한 육체적 능력 이 아니라 훨씬 더 많습니다. 당신 은 진정으로 시험 을 받으면 힘 과 힘 사이 에 차이 를 알 수 있습니까?"
rows["149:1994354116"]="야니라 문펠은 공사물질을 판매하고 있습니다. 건물 안으로 들어오는 왼쪽에서 공사의 홀에 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["149:2025377133"]="내 래치로 잠시 들어와 내가 어떻게 느껴지는지 알 수 있겠어"
rows["149:2062092438"]="이제... 그대가 발견한 그 황천날개 알이 필요합니다. 결국 그 알들은 주인님의 성과니까요. 당신이 원하는 가격이라면 얼마든지 치를 의향이 있습니다."
rows["149:2091919765"]="사실 두 가지 언급은 모욕적인 것 같습니다.$B$B이제 내 시선을 벗어나서, 내가 내 대리대를 네 뒷면에 놓을 때까지"
rows["149:2094066872"]="당신이 사고 싶은 게 있나요?$B$B그래서 여기 왔어, 내 친구$B$B제발, 당신의 기쁨을 말해줘"
rows["149:212614376"]="호드의 형제 자매 여러분, 우리 는 모든 면 에서 적 들 이 둘러싸고 있습니다. 앞으로 몇 주 동안 여러분의 용기는 승리 와 패배 사이 의 차이점 이 될 것입니다."
rows["149:217104622"]="물도 무료로 제공해 드릴게요. 수분분 공급 기능이 여러 번 이용되려면 더 많이 찾아볼 필요가 있습니다."
rows["149:247348233"]="다음은 낙스라마스에서 정점에 선 강력한 존재들에 대해 이야기하겠다. 이 두 괴물은 노스렌드에 있는 모든 존재에게 엄청난 위협이지."
rows["149:280801521"]="팔콘윙 스퀘어 북동쪽에 있는 건물은, 당신은 아마 타나리아를 찾을 것입니다."
