rows["149:336169531"]="여기 우리는 니우자오의 고향입니다. 검은 황소. 그는 판다레네 강도의 보호자 정신입니다."
rows["149:337968982"]="강점을 시험하는 것과 맹목적으로 위험길에 걷는 것은 다르죠. 가로쉬는 우리를 이 일을 하도록 보냈고, 저는 이것을 받아들일 수 없습니다."
rows["149:341630285"]="스태겔름은 다르나서스년] 자신의 지역으로 물러나며, 테일드라시일을 축복하고 우리 민족의 불멸을 회복할 수 있는 새로운 방향을 찾고 있었습니다."
rows["149:343013180"]="우리의 발 아래의 땅이 비거리고 떨고 있으며 하늘로부터 불가 내리게 되나니 공기가 모든 생명을 익사케 하리니 실로 이것이 불의 주인이시니라"
rows["149:36746136"]="아니, 그럴 수 없는데... 이 생물은 레지옹의 종이 되어서 사타이로 변신하고 레지온의 \"복\"을 받고 있다고 합니다."
rows["149:393294207"]="적에 피해를 주려면 충격의 창을 사용하라. 위험에 처하면 시간 정지를 사용해 모든 적을 그 자리에 멈추게 하여 충격의 창으로 어마어마한 피해를 주어라!"
rows["149:415987631"]="배신자들아! 심판의 날과 함께 너의 종말도 다가올 거다! 네 잘난 리치 왕이 선조의 심판에서 널 구해줄 수 있는지 보자! 죽어라!"
rows["149:422543696"]="살아 있는 자들의 근로이 결코 멈추지 않는다. 당신들의 수가 제한되어 있고, 모든 전투에서 점점 줄어들게 됩니다. 당신은 종말을 볼 때까지 살지 않을 것입니다."
rows["149:426130445"]="살마 살디언의 레시피가 아니라 엄마의 요리인데 서부 몰락지대 노인 블랑시와 함께"
rows["149:427420169"]="난 피가 흐르는 가장자리야, 아기! 초원적 기술들이 투입되어 있어. 잃어버린 지식과 새로운 자원을 찾기 위해 아제로스의 깊이를 탐구한다.$B$B이름 기억해"
rows["149:437836659"]="죽은 토끼를 묶어서 트롤의 굴을 지나가는 게 더 낫지"
rows["149:492104335"]="존재 지시어. 요그사론. 보안 환경이 손상되었습니다. 감옥 관리 상황, 알 수 없음. 알림을 목적으로 감시자와 연락할 수 없습니다."
rows["149:527066065"]="가난한 로, 그는 판드리아크들의 존경을 얻기 위해 너무 열심히 노력했지"
rows["149:550701268"]="\"우리는 미스트호퍼가 벽을 넘어서서 모험을 하기 위해 고용된 게 아니라는 것을 알고 있습니다."
rows["149:552068609"]="리치 왕은 멀리까지 손을 뻗치는 중입니다... 모든 용군단에게 가장 성스러운 땅마저도 짓밟으려 하고 있어요. 우리가 행동에 나서게 유도하고 있습니다."
rows["149:596444995"]="이 제단에서 어떤 의식이 행되었는데, 베렌이 한 번 이야기했던 비교적인 초성례처럼 보입니다."
rows["149:598081605"]="해적이라는 명성이 나쁜 사람이라고 하지만, 돈을 벌기 위해 무차별적으로 사람들을 죽이는 걸 볼 수는 없어요."
rows["149:626123557"]="저는 이 포세이큰 매일 밤 큰 비커 조각상을 태우고 있지만 우리 의식은 그들에게 이상해 보일 것입니다."
rows["149:640004857"]="필사자는 눈을 감을 용기가 있다! (부진한 작은 장난감) 난 너를 보고 있어, 작은아! 눈이 보는 것을 보고 싶어하지 않나? (그것을 보여주어, 모든 것을 보여주어!)"
rows["149:646482675"]="스톰윈드의 거주 엔지니어 트레이너는 리얼리아ම් 스파크스핀드라는 이름의 기발한 기둥입니다. 그는 왜성 구역의 뒷면에 발견 될 수 있습니다."
