rows["150:1009220423"]="이제 제 요점으로: 우리는 계산을 향해 가고 있다고 생각합니다. 그리고 아니, 저는 얼라이언스와 호드 사이의 현재의 갈등에 대해 이야기하고 있지 않습니다."
rows["150:1015259678"]="라스타칸, 네가랑 너의 잔다라리들이 트롤 사람들을 지배할 계획이라면 다크스피어와 우리의 동맹자들이 널 대적하는 걸 알게 될거야!"
rows["150:104114738"]="운명은 우리에게 더 감사할 일을 베풀고 있답니다. 말리고스는 지금 아끼던 것을 잃었습니다. 만약 그 사실을 깨달으면, 그는 안전한 마력의 탑 밖으로 나올 게 분명해요."
rows["150:1047925435"]="스킨링 트레이너가 있어요 오그리마- 라저힐에서 북쪽으로 가는 길 오그리마 도착할 때 방향에 대해 물어보세요."
rows["150:1082574982"]="스칼리온을 싫어한다고 말했어?$B$B<유가 큰 소리를 내며 울린다.>$B$B불행히도 내겐 내일은 시즌이 올릴 겁니다."
rows["150:1103475232"]="근육이 많고 뇌도 없죠. 피온은 기발할 때 훌륭하지만, 제가 무슨 말을 하는지 이해한다면, 발자취가 시작되어야 합니다."
rows["150:1139585689"]="조심해, D 씨. 거미들이 많으면 자기력을 이용해 죽게 해"
rows["150:1159104917"]="우리는 너무 늦었어!  ⁇  부는 거의 마쳤어 폭풍의 신인 나락을 부활시키는 것. 하지만 그건 우연한 일이야. 우리의 진정한 목표는  ⁇  부를 물리치는 것입니다."
rows["150:1161991889"]="난 그들의 상사와 얘기하려고 했지만, 그는 날 보고 싶지 않아. 나는 충분히 \"고위 지위가\" 아니기 때문일 것 같네요."
rows["150:1206751679"]="스트라톨렘의 혐오스러운 것들을 하나로 묶는 이끈은 공예인들이 매우 많이 찾는 것인데: 극히 탄력적이면서 거의 깨지지 않는 것이지요."
rows["150:1238302118"]="어업 실력을 시험하고 싶다면, 이번 일요일에는 스터글스톤에서 어업 대회가 열린다.\010"
rows["150:1251077603"]="여기, 그 파이프들은 모두 구조에 연결되어 있는 것 같네요. 물은 훔친 적도 없을 겁니다."
rows["150:1254290252"]="그만 두세요, 둘 다 이보다 똑똑해요. 진주처럼 똑똑해서 잘 지내실 수 있나요? 아니면 그냥 똥같은 행동을 계속할 건가요?"
rows["150:1271122270"]=" ⁇ , 덩어리 없는 탱커드의? 그는 아이언포지의 문 북쪽에 있는 스톤파이어 타버너에서 음주 경쟁에 가장 오랫동안 참여했습니다."
rows["150:1290557797"]="아, 이제 자네가 무슨 생각인지 알겠군. 내 생전의 제자가 이런 일을 하다니... 메라 돈블레이드. 그의 마음이 그토록 사악하게 변했다니 정말 안타깝군그래."
rows["150:1299006691"]="감사합니다. 제 거대한 금무리를 바라보고 온 분들에게 감사드립니다."
rows["150:1364043769"]="작은 자드 조각을 소유하는 것은 악령들을 물리치는 매력을 가진 것과 같습니다. 이 작은 고양이 덕분에 고마워요!"
rows["150:1398825796"]="<프로스트보른 스카우트는 당신이 접근할 때 발에 일어나려고 하지만, 바닥에 넘어지면서 부위에 고통스러운 상처를  ⁇ 습니다.>"
rows["150:1432604163"]="당신들은 반대의 폭격을 해치면서도 너무 바빴어요"
rows["150:1539100570"]="우리가 노후화된 로봇들을 어떻게 만들지 궁금해 했나요? 3000!"
rows["150:154754904"]="가로쉬의 이런 모그 유물들의 집착은 카엘타스가 우리들 사이에서 걸어온 이후로 본 적도 없다"
rows["150:1559114418"]="참으로 기막힌 아이러니군. 도시를 지키다 쓰러져간 스톰윈드의 군대가 다시 일어나 결사단 편에서 파괴의 앞잡이가 되어 싸우다니."
rows["150:1568967878"]=" ⁇ 다라리족은 자랑스러운 인종입니다. 그들의 자부심이 결국 그들의 멸망이 될 것입니다.$b$b가장 강력한 적들조차도 약점이 있습니다. 우리는 그것을 발견해야 합니다."
rows["150:1573281711"]="왜 날 괴롭히고 있어? 왜, 당신은 고품질의 옷도 만들 수 없지! 스난그와 이야기해 내 재능에 가치가 있을 때 다시 오!"
rows["150:1591344077"]="내 인생에 많은 새끼와 큰 새끼들이 있었지만, 이제까지 내 큰 손녀들은 아무도 방문하지 않습니다."
rows["150:1627266487"]=" ⁇ 더브루 맥주와 그렘록의 요리도 맛있는 식사입니다. 요리사가 되고 싶다면 그를 훈련시켜야 합니다."
rows["150:162834440"]="크로시크는 우리의 창조자인 크로스의 선물입니다. 그는 우리에게 우리의 힘과 유산, 우리의 유산을 상기시켜줍니다. 그는 우리에게 우리의 영광스러운 미래를 엿볼 수 있습니다."
rows["150:1676142293"]="아버지 는 우리 가 저항 을 받지 않을 것 이라고 생각 했으나, 그 때 는 종종 사물 을 잘 생각 하기 보다는 불멸 에 집착 하는 데 시간을 쏟고 있습니다."
rows["150:1689624009"]="여기가 중요한데 영웅, 공격할 준비가 되면 신호를 줄 수 있어"
rows["150:1706843095"]="우리가 미묘하고 원자적인 길을 따르는 사람들은 끝없는 탐구 경로를 따르고 있습니다."
rows["150:1712241957"]="엘라는 서쪽 끝에 살고 있습니다.$B$B부모님이 죽기 전까진 혼자 살았어"
