rows["150:1760908090"]="\"심오한 것\"$b$B누가 리 무그파이더가 처음 만난 때 뭐라고 했는지 물어보면 항상 심오한 일이죠"
rows["150:1788391828"]="하자라, 드림비버$B$B악몽의 힘은 그의 것이며, 그의 적들은 영원히 잠들게 하소서.  $B$B하자라가 이제 멀리 떨어져 있어 언젠가는 돌아올 수도 있어"
rows["150:1798638984"]="물론, 풀을 도와줘서  ⁇ 을 나눠주면 최소한 할 수 있어"
rows["150:1820632709"]="우리가 본 것에서 죽은 미레에서 일어난 일을 설명합니다. 한 번은 이곳에는 호수가 있었습니다. 만약 나가를 멈추지 않는다면, 모든 습지는 곧 이렇게 보일 것입니다!"
rows["150:1838539018"]="정말 날려오셨어 여기서부터 들릴 수 있어 \010벽에서 날아가는 영돌의 소리라고 부르죠?"
rows["150:1871713945"]="군인과 농민과 싸우려고 하지 않았는데, 이 농부들이 우리 편에  ⁇ 을 때 우리는 안도랄을 점령하는 데 집중하지 않을 위험이 있습니다."
rows["150:1926099367"]="걱정마, 내 마음은 도로리아 여인에게만 속해있지만, 당신만큼의 아름다운 여인은 많은 사람들의 마음을 지배해야 합니다."
rows["150:19601844"]="이 포스트가 워싱홀드에서 보병을 준비할 거야 아니면 너희 무용한 시신이 묘지를 채울거야"
rows["150:1987846220"]="이건 똑같지 않아, 아버지. 샤는 단순히 이길 수 없어. 그것은 우리의 가장 내면의 약점을 먹이고, 우리의 생각을 왜곡합니다. 그것을 과소평가하지 마십시오."
rows["150:1988371918"]="인사드립니다, 게제 님! 하라사미드 구역에서 17건의 주문이 추가로 들어왔습니다. 예측하신 대로 벨다라이트 시장이 붕괴됐습니다."
rows["150:2071811620"]="그는 판다리아를  ⁇ 고 있는 이 땅의 숨겨진 비밀을 발견할 수 있는 모든 사람에게 금과 부를 약속했습니다."
rows["150:2083771690"]="저는 경멸을 무시하고, 통치자에게 경멸을 심어주기를 희망합니다."
rows["150:2116464252"]="지구가 고통에 울고 눈물을 모으고 큰 나무의 문을 봉쇄해라"
rows["150:2123822291"]="모든 노스렌드 마녀의 심장이 더 차가운데, 여기선... 그 이유를 알 수 있을 거야."
rows["150:2124642102"]="우리에겐 피부  ⁇ 이 있어요. 켈리안 헤이지한테서 배웠어요. 피부  ⁇ 을 가르쳐줬어요."
rows["150:2127267276"]="오버딘이나 발리언스 포항을 찾으려 한다면, 캐서럴 구역과 공원 사이에 있는 운하를 지나면 항구 스톰윈드을 찾을 수 있습니다."
rows["150:234135023"]="아내가 죽기 전에 약속했었다. 죽든 살든 어둠의 문은 나 혼자 넘고, 아들은 안전하게 있을 거라고. 더럽혀지지 않은 채로..."
rows["150:241975467"]="그리고 기억해, 필사자, 지금 내가 너에게 선택권을 주네. 나는 너의 충성을 선택할 수 있게 해 주네. 하지만 결국, 너는 내게 될거야.\010"
rows["150:283782518"]="사냥꾼의 홀로 가는 거요,  ⁇ 터 호른 같은 훌륭한 사냥꾼들이 있을 겁니다."
rows["150:287305033"]="아빠는 항상 이웃이 필요해 줄거라고 했지. 먼저 시장에서 일 좀 처리해야겠어. 내가 가능한 한 빨리 올 거야!"
rows["150:297479145"]="허버트 할세이 박사님, 재밌는 건 하지 마 더 이상 전염병의 말도 안 되는 거라면"
rows["150:297997057"]="이 표기판의 표기에는 고대 다이어그램이 있고 강력한 단어들이 있습니다.$B$B당신은 그것이 알케미컬 레시피라고 믿지만, 그것은 당신의 능력보다 더..."
rows["150:324933763"]="플레브 씨는 나에게 택시지질이 되는 법을 가르쳐주고 있습니다. 개인적으로 그는 너무 오래 된 것 같아서"
rows["150:351792702"]="도와줄게요 하지만 다른 사람에게 말하지 말라는 약속을 해주세요"
rows["150:38870409"]="약간의 마술을 아는 것은 이 분야에서 유용합니다. 환상은 항상 모든 사람을 속일 수는 없지만, 보통 일을 할 수 있을 만큼 좋은 것입니다."
rows["150:427781529"]="어업은 항상 우리 가족에게 자연스럽게 왔어요. 하지만 조금의 도움이 필요해 보네요. 어머님께 몇 가지 업무를 해도 어때요?"
rows["150:442046971"]="내가 낄 싸움이 아니라고? 자기를 얼마나 대단하게 생각하는지 모르겠지만, 난 아서스에게 갚아야 할 원수가 있으니 방해할 생각은 마라! 총공격! 발사! 발사!"
