rows["150:499635593"]="언소크가 드론이었을 때 처음 독소를 섞지 못했을 때, 혼자 나와 마주하게 해"
rows["150:517508772"]="드루이드들은 무롱라드에서 달 축제를 축하하고 있습니다. 너무 멀리 걸어서 가면, 그들은 큰 도시에서 사람들을 운송합니다."
rows["150:520949360"]="Kun-Lai 정상에서 당신이 그 모구의 기억에서 본 것과 일치하는 장소를 찾고 있습니다. 마침내 코루네의 숨기는 곳을 발견했습니다."
rows["150:570263552"]="브로켄디스 형제가 내 돈과 재산을 빼앗아갔어"
rows["150:597071694"]="그건 전적으로 자발적인 일이 아니었지만, 정말 놀라운 것을 발견했는데, 짐승은 거의 모든 것을 악영향 없이 섭취할 수 있는 것 같았다."
rows["150:640699740"]="좋아, 시작해...  ⁇ ! 속였어! 그렇게 간단하진 못 생각했지. 다른 사람들처럼 네 용기를 증명해야 할거야!"
rows["150:682627384"]="그렇소. 헌데 이곳에서 해안으로 나가는 길을 언데드가 장악했다고 하더군. 배로 돌아가려면 다른 길을 찾아야 할 거요."
rows["150:689189095"]="몇 개, 가장 큰 한은 마지막으로 코르베스에서 싸웠다$b$b며칠 동안 못 봤어, 괜찮아졌으면 좋겠어"
rows["150:74012232"]="여기 있네, 내가 생각하기 시작했어, 선리버들이 널 잡았어"
rows["150:777477421"]="골드샤이어의 라이온즈 프라이드 인에서 더 멀리 보지 마세요."
rows["150:783406673"]="이웃, 내가 너무 좋아하는 이야기들, 전부 듣고 싶어!$B$B하지만 우린 함께 좋은 이야기를 만들어냈어"
rows["150:789778721"]="뭐요?$B$B뭐 필요해?$B$B왜 내 여동생이 나를 여기 방문하도록 설득시켰지? 동물들이 얼마나 큰지 본 적 있어?"
rows["150:8420953"]="활을 내던지면서 보병을 지원해 줄 수 있어$B$B|TInterface\\Icons\\ability_searingarrow.blp:64|t"
rows["150:857636839"]="어쨌든, 우리는 오늘 썬더 킹에게 끔찍한 타격을 줬습니다. 호드 금속공사는 즉시 모가 제조 기술을 연구하기 시작할 수 있습니다."
rows["150:880383035"]="걱정하지 마, 레리사. 무슨 일이 있어도 난 돌아갈 거다. 넌 세상에 단 하나 남은 내 가족이니까."
rows["150:890904416"]="아마추어라면 나쁘지 않겠지만, 넌 나도 아는 걸 알잖아 언더시티."
rows["150:896528603"]="여기 우리는 아래 땅 속에 있습니다.$b$b보람 섬에서 어린 시절 내가 들은 이야기만큼이나 아름답지만 물고기는 더 크기도 합니다."
rows["150:90773011"]="아레나에서 죽기 위해 싸우는 사람들보다 더 좋아할 일은 없다."
rows["150:922171532"]="로헨도르는 파괴됐고, 오직 아르코니소스 문만 남아있어요.$B$B우리 마법사들은 $3257w 마지막 문의 방어구역을 통과해, 아르코니소스"
rows["150:930787501"]="내가 바쁘다? 그게 무슨 뜻일까요? 하루 종일 여기 서서 손가락을 굽혀서?"
rows["150:969900770"]="십자군 재판에 오신 것을 환영합니다. 아제로스의 가장 강력한 전투가 이 재판을 받을 수 있습니다. 당신은 몇 명 중 한 명입니다."
rows["150:971503906"]="최신 설계도, 도안, 설명서 등이 모두 이곳에 있습니다. 따라하기 아주 쉽게 설명되어 있어서 직접 제작도 가능하답니다!"
rows["151:1000817696"]="피 기사단 본부로 오신 것을 환영합니다. 실버문, 그리고 진정한 주인 빛."
rows["151:1005050991"]="멀리서, 먼 곳에서, 아제로스라는 나라에서, 나는 동맹을 가지고 있습니다. 그는 우리에게 그의 땅을 제안합니다. 그것은 녹색과 화려한, 순수 물과 사냥하기 위해 기름진 생물들로 가득합니다."
rows["151:1013155218"]="맥스웰 캠프에서 만나면 다음 단계의 계획을 살펴보고"
rows["151:1026711409"]="안심해, 필사자 우리 함께하는 시간은 생산적이어야 하고 긴장감이 없는 시간일 것이다.$b$b당신 의 생각 과 의식을 잘 이해 하는 능력 에 따라 많은 일 이 달라진다."
rows["151:1067356620"]="그 듀크 스톨링턴은 멍청한 놈이야 큰 게임도 하고 있지만 자기 검을 들고도 못 나잖아"
rows["151:1087635309"]="아이언포지의 미스틱 워드에 가서 야간 엘프 드루이드들과 이야기해봐요. 그들은 당신을 무롱레이드로 데려가 달 축제 축하에 참여하게 할 수 있습니다."
rows["151:1103798143"]="내 사람들과 함께 안에 숨어 있을 거야 빛난 이미 명령을 내렸어, 총이 오고 있어"
rows["151:1129191470"]="델라니엘은 퀘릴레스트라라는 멋진 요리사를 직원으로 고용하고 있어"
rows["151:1180643999"]="지금에도 자유의지를 가진 무사한이 아라티 계곡에 있는 아라토르 동맹을 싸우고 있습니다. 얼라이언스 동맹국?"
rows["151:1199070051"]="우리가 조사에 대해 완전히 처리했다면 증거는 안전해졌다고 확신합니다"
rows["151:1235584710"]="\"우리 는 당신 을 도울 수 없다\".라고 와일드햄어  ⁇  은 말 하였다. \"우리가 암흑 철군 에게 등을 돌리면, 그들은 청동염을 물리치고 아이언포지를 장악 할 것 이다!\""
rows["151:1252715598"]="\"우리는 당신을 도울 수 없다\"라고 청동염색왜성은 말했다. \"우리가 암흑 철에 등을 돌리면 그들은 와일드햄러를 물리치고 아이언포지을 장악 할 것입니다!\""
rows["151:1276143750"]="우린 위험한 곳으로 들어왔어요. 이 곳에서 사우로크들이 매우 화가 났고, 지나가는 모든 배를 공격합니다."
rows["151:1284406778"]="이치만해! 당신은 불타는 군단를 막을 수 없다고 희망합니다. 문명적인 방법으로 논의하자. 나는 당신의 가장 야생한 꿈을 넘어 권력을 제공할 수 있습니다!"
rows["151:1301719700"]="[%s] 고백: 나는 둘 중 하나를 결정할 수 없다 호드 그리고 얼라이언스. 호드 네 개의  ⁇ 꼬리 괴물들이 있지만 얼라이언스  ⁇ 이 있는 왜성 사제들이 있습니다."
rows["151:1353656361"]="토그누스는 자주 볼 수 없는 분노로  ⁇ 을 때리고 있어"
rows["151:1359250948"]="마녀들, 나한테는 들리지 않았지만 마녀촌의 마녀양이라고 불리는 바에서 그 사람들이 모여있는 거라는 소문을 들었어요  "
rows["151:1360461014"]="아마 당신의 기술 중 하나가 스파링 세션을 더 흥미롭게 만들 수 있을 겁니다."
rows["151:1387405914"]="나도 아오, 자매여. 우리는 언젠가 싸우러 돌아갈 것이오. 그러나 지금은... 그대의 희망을 널리 전파하는 게 최선이오."
rows["151:1430330430"]="내가 정말로 네놈과 다시 거래를 할 것이라 생각하지는 않았겠지? 손해를 줄이는 것이 수익을 남기는 최선의 방법일 때도 있는 법이다!"
rows["151:1431317193"]="꽤 많은 일이었지만 이제 크레이터로 돌아가는 데 필요한 물품을 채울 수 있고 이 외래적인 화물을 배상할 수도 있습니다."
rows["151:1492766413"]="전 엘드레타라를 구제하는 것에 너무 신경쓰고 있어 다른 문제도 해결하지 못해 전쟁, 갈등, 충성도도도 이 도시가 안전할 때까지는 중요하지 않습니다"
rows["151:152798878"]="적들이 각쪽에서 우리를 향해 다가오고 있고, 모든 장로들은 이 자리를 포기하고 말하며, 우리는 우리가 있는 전사처럼 일어서서 싸워야 한다고 말한다."
rows["151:1593827604"]="이 기지는 북렌 스톰윈드에 있습니다.$B$B북쪽의 운하를 따라가면 결국은 유관으로 넘어갈 수 있습니다."
rows["151:1630974329"]="폴드링, 너는 살려서 최후를 지켜보게 하겠다. 이 비참한 세상이 내 생각대로 만들어지는 모습을 빛의 가장 위대한 용사가 놓치게 하고 싶지 않다."
rows["151:1631061449"]="피즐뱅은 곧 널리 알려진 말이 될 거예요! 엄마들은 아기한테 일찍 자라고 겁을 줄 때 그 이름을 들먹거리겠죠! \"그만 침대로 가야지. 안 그러면 피즐뱅이 무서운 악마를 소환해서 한입에 삼켜버린단다!\""
rows["151:1651124635"]="비안시의 초등병 능력은 여러 번 유용하다는 것을 증명했습니다."
rows["151:165122085"]="오, 제가 방해가 된 것 같으면 죄송합니다. 저는 노스워치의 사람들을 두려워합니다. 저는 제 학생들 중 일부를 보내서 그들을 도울 수 있었겠죠. 이제, 어떻게 도와드릴 수 있을까요?"
rows["151:1664971776"]="한때 그립스리 언덕을 돌아다니며 살았는데 이 땅을 통치했던 위대한 우르소크의 아들로$B$B하지만 이제... 이제 난 내 남은 인생을 이 동굴에서 보내게 될게"
rows["151:1668806228"]="알드윈 라클린은 여전히 스톰윈드그의 집 왼쪽에 있는 문을 지나가면 스톰윈드."
rows["151:167976538"]="이  ⁇ 은 놈들은 아안키라지의 문이 열려 제 아내를 삼켜버린 날을 너무 많이 떠올리게 해$b$b이 동물들은 이 땅에 진짜 위협이 됩니다."
rows["151:1727727678"]="지역 공학자인 데이로가 공학의 기초를 가르쳐 줄 수 있고, 당신은 기술자에게 통신 장치의 고장을 도울 수 있을지도 모릅니다."
rows["151:1770892577"]="결국, 날 좌절시키는군, 탤런! 널 목표로... 굉장한 계획을 세웠는데. 아아! 시간이 조금만 더 있었더라면 네가 그 더러운 혈통을 타고난 사실을 땅을 치며 후회하게 해줄 것을..."
rows["151:1828896084"]="칼을 들고 모자를 풀어 내면 먼저 칼을 들고 싸우기 전에$b$b준비됐어?"
rows["151:1836148042"]="지옥불 반도 는 찢어진 왕국 이므로 그 주민 들 에게는 무자비 한 자 과 용서 하지 않는 곳 이다."
rows["151:1916271884"]="진정하십시오, 불똥 님! 모든 것이 제 통제 하에 있습니다. 우리는 그들 몰래 엑소다르에서 채굴을 할 것이고 불똥님과 저는 아주 큰 부자가 될 겁니다."
rows["151:203464611"]="<손으로 쓰여진 표지판은 다음과 같다>$B$B          비밀 연구소 기록$B     X. 니즈레브렉스, 연구소 이사$B$B$B<지금 집에 아무도 없는 것 같네요. 나중에 돌아올까요?>"
rows["151:2059403284"]="다음으로 낙스라마스 역병의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 로데론에 뿌렸던 것보다 더 강한 역병을 만드는 중이다."
rows["151:2086374052"]="바람을 머리 속에 느껴서 안경을 착용하면 아이언  ⁇ 이 좀 엉망이 될거라고"
rows["151:2086616702"]="우리는 초기의 영들을 찾아서 성전에 다시 모여야 합니다. 그렇게 하면 이 나라를 치유하고,"
rows["151:2135719106"]="대라란에서 최근에 온 아카인 리포저인 프랫 장교는 보통 로컬 마녀 라비니아 크루와 함께 일하고 있습니다."
rows["151:239397937"]="이 일은 전혀 친숙하지 않습니다. 다시 정원에 가서 다른 방법이 있는지 보자. 나는 긴 계단벽을 좋아하지 않는다."
rows["151:263967010"]="무장실에는 우브렉 파이어핸드 (Ulbrek Firehand) 라는 주거의 주인을 찾을 수 있습니다."
rows["151:27551564"]="보아도  ⁇  얼굴과 놀면서 재밌었군 하지만 제대로 된 표본을 수집하려면 두 가지 종류의 병이 동시에 필요해"
rows["151:293324771"]="제 신부님의 명령에 따라 그를 처형합니다. 하지만 가능한 한 고통 없이 그렇게 합니다. 정의가 이루어져야 합니다."
rows["151:37388896"]="우리 보석사들이 에크소다르에 있어 발견한 자료를 이용해 기적을 만들어내야 돼"
rows["151:420873288"]="모두 준비해 포로가 밸리로 데려가자"
rows["151:421463656"]="크로미, 이 시간 흐름에서 무슨 일이 일어날지 둘 다 알고 있어, 이런 걸 본 적이 있어"
rows["151:422636995"]="새로운 동맹국인 스틸파인 포르볼그족은 우리가 발견한 스킨을 가져가는 것에 관심을 나타냈습니다. 그들은 북쪽에 살고 있습니다."
rows["151:424063475"]="제 페이 페이는 다른 사람의 물건을 가져가지 않을 거야 좋은 개야 가끔은 관심만 필요해"
rows["151:428603936"]="말할 것도 없겠지만, 제군들이 살아서 돌아갈 확률은 매우 낮다. 하지만 배운 걸 기억하고 그대로만 한다면 그 확률은 얼마든지 높일 수 있다."
rows["151:429516830"]="작은 나무 는 큰 나무 로 보인 것 이 아니라, 그 끝 에는 엄청난 무게 가 있다. 하지만 그 뒤 에 타우렌 의 힘 을 가지고 흔들면 돌 벽 을 깨뜨릴 수 있습니다."
rows["151:430090810"]="지도자가 누군지 궁금하다 이거지... 쥐방울만한 녀석아, 감히 천둥의 인도자 그롬타르가 이끄는 부족과 전쟁을 벌이겠다고? 그렇게 죽고 싶으냐?"
rows["151:446136289"]="자신이 노력한 결실은 볼 수 있도록 살려둬야지. 검은바위 부족이 이 협곡을 침략하면서 일어날 파괴와 혼돈을 똑똑히 보도록 말이야."
rows["151:50896036"]="치료 능력 을 가진 재능 은 결코 없었지만, 의사 의 기술 에 있어서 내 의욕 을 발견 하였습니다."
rows["151:540271654"]="뒤를 조심하십시오, 밀사여. 이 책의 가치를 다시 알려 드릴 필요는 없겠죠. 이걸 차지할 수만 있다면 은빛 서약단이 무슨 짓이든 하리란 것도 잘 아시리라 믿습니다."
rows["151:559425939"]="이티가 좋은 카파를 좋아하는데, 그 여자도 최고에서 내려온 이래 한 번도 못먹었어"
rows["151:571703395"]="샤오티엔은 이 유적에 큰 관심을 갖고 있습니다. 그들은 그 깊은 곳에서 권력을 되찾으려 합니다. 저는 그들의 시체를 쓰레기통으로 남겨두고 싶습니다."
rows["151:585244731"]="이해가 안 돼요. 낙스라마스를 윈터가드 성채 위로 보내서 다 날려버리면 될 텐데, 왜 그러지 않는 걸까요? 제가 켈투자드였다면 그렇게 했을 텐데."
rows["151:591655933"]="심지어 그들의 필요시에도, 파다레인은 친절하게 음식을 공유하고 불에 있는 장소를 제공해 왔습니다.$B$B우리 모두는 그들로부터 많은 것을 배울 수 있습니다."
rows["151:602040494"]="이제 정말 위대한 시간입니다. Twilight's Hammer, 가장 위대한 시대. 첫째, 죽음의 날개의 도착. 그리고 이제..."
rows["151:725716438"]="그들은 죽어야 하지 않았습니다.$B$B남쪽 마을 내 집, 가족 모두 죽였어$B$B내가 더 강했다면, 그들을 구해 줄 수 있었을 거야!"
rows["151:72801918"]="지질조사를 하는 것이 얼마나 어려운지 알 수 있나요?$B$B술에 취해서 더 힘들어"
rows["151:732129021"]="<볼진의 임시 혁명 캠프 주변 냄새는 참을 수 없는 것 이다. 트롤 리더가 먼저 말을 허용, 그의 경비자 조심스럽게 당신을 관찰하는 동안>"
rows["151:749565108"]="구루바시 제국의 최고 권력자에 대한 너의 무관심을 알고 있다. 그러나 이곳에 네가 발을 들여놓는 순간, 줄구룹의 거주자들이 네 존재에 대해 촉각을 곤두세우고 있다는 것을 잊지 마라."
rows["151:798296599"]="우리의 공예가 가장 훌륭한 나무판을 만들지만, 그들은 가장 잔인한 폭풍에 견딜 수 있지만, 그들은 내 허벅지 추락하는 폭풍의 물처럼"
rows["151:806297014"]="지옥불 반도의 먼지와 열이 꽤 짜증나는다고 전해졌지만, 저는 알 수 없지만,"
rows["151:810702922"]="아케이온은 우리의 레지던트 트래커이고, 그는 또한 좋은 사람이에요. 그가 착용하는 피부는 그의 기술에 대한 증거입니다. 그의 캠프는 아저워치 남동쪽에 있습니다."
rows["151:824554823"]="조심해, P씨. 큰 괴물들을 볼 때 자기력을 이용해 그들을 빨아들여 죽게 해"
rows["151:836905090"]="그리고 우리 계급들 사이에서 조화를 촉구하는 사람들에게... 그들에게 묻습니다. \"모든 분쟁이 우리의 주인들을 기쁘게 하지 않느냐?"
rows["151:846397478"]="진실 한 사람 호드 내가 그것을 보았고, 나를 보여줬다. 나는 스켈라 산과 피의 강을 보았다. 그리고 난... 내... 세계를!"
rows["151:850147908"]="우서가 내 부대를 불러들여? 빌어먹을! 병사들이 떠나면 어떻게 말가니스를 잡으란 말인가! 병사들이 해안에 도착하기 전에 배를 불태워야겠어!"
rows["151:851393265"]="리스리더는 처음에는 좀 겁이 나지만, 당신이 찾는 걸 보관하고 있어요."
rows["151:875278098"]="스톤브로는 떠나지 않을 거야 아이언포지 요즘은 많이요 그래서 수직자의 직업을 배우고 싶다면 아이언포지."
rows["151:88787597"]="지구 어머니에는 많은 비밀이 있고 브렉 스톤호프가 몇 가지 발견하는 데 도움이 될 수 있습니다."
rows["151:908211440"]="\"...\"$B$B타우렌 드루이드의 몸은 가만히 있고 움직이지 않는 것처럼 보입니다. 마치 그는 마침내 이 세상에서 약속된 위대한 세상을 넘어갔던 것처럼 보입니다."
rows["151:928894684"]="이제... 그대가 발견한 그 황천날개 알이 필요합니다. 결국 그 알들은 주인님의 성과니까요. 당신이 원하는 가격이라면 얼마든지 치를 의향이 있습니다."
rows["151:951602867"]="우리 해안에서 배가 추락하는 것을 본 적 있으신가요?$b$b안개가 종종 우리에게 그런 \"상\"들을 가져다 줍니다."
rows["152:1039270330"]="저기, 돌로 얼어붙은 그를 봐요, 움직이지 않고, 감히 느끼지 못하는 그의 얼굴의 모습, 결단력과 거저함"
rows["152:1063050641"]="그는 결국은 전체 요새를 파괴하고 수용소에서 보관하는 오크들을 해방시키고, 오크들의 왕으로 권력을 잡는다."
rows["152:1065080060"]="아니, 우리는 뒤로 물러나지 않을거야. 맨티드들이 다음 무리를 낳기까지는 아직 많은 세월이 걸렸어."
rows["152:1073380929"]="언고로의 크리스탈 파일론은 모든 사람들에게 미스터리입니다. 이곳의 몇 명의 주민들에게, 그들은 전설의 원천입니다."
rows["152:1093166462"]="말퓨리온, 지나치게 앞서 가는군. 현재 아제로스 자손들 사이에서 평화는 거의 찾아볼 수가 없는 지경일세. 그나저나 우리 아버지는 어떤가? 자네 형제는? 뭐 새로운 소식은 없나?"
rows["152:110340575"]="우린 가장 걱정할 게 사우로크 강탈자나 가끔씩 배고픈 호젠이야$b$b그 트롤들은 다른 방식으로 싸우고 있어요"
rows["152:1162235775"]="다시 한 번 말하지만, 그자가 성공한다면 이 세상은 아웃랜드에서 지금껏 일어났던 일보다 훨씬 험한 상황에 부닥칠 거다. 그러니 무슨 수를 써서라도 이를 막아내야 한다."
rows["152:116319189"]="보웬 브리스보이스가 보웬 브리일 남서쪽의 그의 집 안에 있습니다."
rows["152:1188565268"]="죽음 날개가 우리를 하늘로 날려버렸어 거의 도착했잖아"
rows["152:1269364598"]="당신은 답을 찾기 위해 죽은 자들의 세계로 건너갔고, 동맹을 구하고 목숨을 걸고 여기에 있는걸 허락해줘"
rows["152:1397920233"]="네, 평화의 전당 안에 낚시용품 판매자가 있습니다. 어획을 망치지 않도록 조용히 해 주세요!$B$B지도에 위치를 표시해 줄게요"
rows["152:1459914832"]="맛있고 깨끗한 흙을 찾았어! 오늘 밤 왕처럼 먹으러 갈 거야, 펭귄 씨! 물론 나랑 나누겠다!"
rows["152:148913127"]="티만은 아쉬의 기둥에서 떨어졌고 오타나는 늑대가 먹었고, 고롭은 래바에 빠졌다. 그리고 제 중위원 대부분은 괴짜의 발목 사고로 사망했습니다."
rows["152:1505691942"]="타우렌 시퍼트 콘서트는 15분 후에 시작됩니다. 스랫라스 시티 남쪽 테로카르에서 다크문 페어의 개막을 축하합니다!"
rows["152:150622288"]="네, 압니다. 그가 돌아서는 걸 보았지요... 올바른 길을 모두 포기하는 걸 지켜봤지만 저는 아무것도 하지 않았습니다... 최후의 순간까지도 말이죠."
rows["152:1527881373"]="우리들, 하위시민들은 최근에까지만 해도 그림자 迷宫에서 꽤 광범위한 스파이 네트워크를 구축했습니다.$B$B이제 나랑 토건을 제외한 모든 사람이 죽었어"
rows["152:1621640577"]="훈련에 있어서 아주 먼 길을 걸었으니 더 많은 것을 배우고 싶다면 사막으로 가야 합니다. "
rows["152:1627899354"]="거대한 돌은 집중된 미묘한 에너지로  ⁇ 다.$B$B안도렐의 지시들을 믿으면 돌의 에너지를 다시 집중시키는 것이 쉬울 겁니다"
rows["152:1643328206"]="\"빛에서 태어난\"는 샤타르의 직역어인데, 이리던의 요원으로부터 샤트라트 도시를 되찾은 나라루에게 붙여진 이름입니다."
rows["152:1690578914"]="날 기억하고 여기까지 와주다니 고맙네. 그 상징이 꼭 필요한 건 아니었네만 그걸 되찾아 온 그대의 노력이 이 늙은이의 마음을 감동시키는군."
rows["152:1709829047"]="우리는 용감함의 승객들을 보호하기 위해 최선을 다할 것을 맹세했습니다. 스톰윈드 항구는 안전해야 합니다."
rows["152:1715792526"]="등록자는 어떤 임무를 올리기 전에 뷰록 경과와 대화를 해야 합니다.$B$B승인되지 않은 게시물을 작성한 사람은 처벌을 받게 될 것입니다.$B$B결제도 안하고"
rows["152:1726786829"]="텔드랏실에 발을 들이다니 뻔뻔하군, 명가의 일원이여. 그대의 족속은 여기서 환영받지 못하오. 우리는 고대의 전쟁도, 누구 때문에 그 일이 벌어졌는지도 기억하고 있소."
rows["152:1762399823"]="아무 것도 닿지 않아, 살아있는 어떤 것도 그 장벽을 통과할 수 없어!"
rows["152:1807746979"]="하지만 적들을 과소평가하지 말아요, 우린 그들을 침공하고 있습니다. 우리는 그들을 위해 싸우고 있습니다."
rows["152:1832790670"]="고왕 볼버 포드라곤은 우리 모두를 위해 싸우고 있습니다. 스톰윈드 바로 지금 당장"
rows["152:184145736"]="희생 마법은 생명의 가장 큰 위반으로 간주되었고 우리는 즉시 그러한... 맛있는 마술에 빠져있는 사람들을 처벌하도록 조정되었습니다."
rows["152:1862098601"]="그랄크 로크럽! 너는 호드에 대한 반역죄로 기소되었고 이미 유죄로 판결이 났다. 네 변명이나 주장 따위는 아무런 의미가 없다. 대집행자 누즈라크, 앞으로 나오시오."
rows["152:1865841455"]="우리 셋 다 유적들을 가지고 있지만, 에너지는 급속히 사라지고 있습니다. 우리는 꿈의 경로로스로 돌아가야 합니다!"
rows["152:1871378015"]="|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:144985|h[강력 주둥이 부패]|h|r!"
rows["152:1875888705"]="전쟁터에서 피로만 구매한 존중의 표지판입니다. 이 표지판을 충분히 획득하는 것은 이 전쟁을 이길 계획이라면 매우 중요합니다."
rows["152:1897161885"]="타디우스는 여자와 아이의 육신으로 만들어졌다. 그 가엾은 영혼들은 하나로 융합되어, 더러운 육체의 감옥에 영원토록 갇혀 있다고 한다."
rows["152:1898050299"]="당신은 Sildinair를 보병의 테라스에서 발견할 것입니다. 그녀의 눈은 숲을 스캔하고 우리의 아름다운 도시에 진입할 용기를 가진 적들을 찾아보고 있습니다.  "
rows["152:1898096637"]="검댕가루 작업현장에서 우연히 선타라 비석을 찾았을 때 라그나로스 님의 힘이 내 온몸과 마음을 휘감았지. 라그나로스께서 내 삶에 의미를 주신 거야."
rows["152:1908260224"]="전설에 따르면 오래전 하늘에는 5개의 태양이 밝게 불어오고 바람이 불 때 그 열은 큰 산불을 일으켰습니다."
rows["152:197198622"]="활의 능력이 사냥꾼뿐만 아니라 모든 사람에게 큰 도움이 되고 당신은 빨리, 조용히 공격할 수 있고 포상이 깜박이는 전에 그들은 죽습니다."
rows["152:2003749140"]="|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t 함대 선장은 클러스터를 감지했다! 발사 |cFFFF0000|Hspell:147047|h[불안정 철성]|h|r!"
rows["152:2117195760"]="당신은 약물을 만드는 기초를 배웠지만 더 많은 공부가 필요합니다."
rows["152:2117336696"]="그녀는 이제 황제 타우리산과 함께 살고 있습니다. 그는 그녀를 어떤 강력한 생각의 마법에 사로잡고 있습니다.\010"
rows["152:2120185878"]="당신의 선물은 보기 드문 친절이로군요, 여행자님. 제 감사와 함께 이 검을 가져가세요. 오래전, 다른 여행자 한 분이 여기 놓고 가셨지만 제겐 쓸모가 없네요."
rows["152:2137293680"]="난 고드프레를 설득하려고 노력 중이야 너희 모두를 죽여서 고통이 끝나고 싶어 하지만 그는 계속 거절하고 있어"
rows["152:260997297"]="여기 있어 다행이야, 친구!$B$B화재는 야생동물들을 이 숲에서 보호소를 찾아내게 해"
rows["152:271900744"]="스카우트 캡틴 엘시아와 만나라. 빛 태양이 너희에게 빛을 비추는"
rows["152:337635868"]="제발, 장군의 손에서 그들을 지켜라! 나는 영원한 꽃의 계곡으로 돌아가 금 로토스에게 보고하겠다. 다시 한번, 많은 감사"
rows["152:434529840"]=" ⁇ 은 강력한 도구일 수 있습니다. 모가 한때 신성 벨에 힘을 발휘했을지도 모릅니다. 그리고 그 후 그들이 건설한 영광스러운 제국을 보세요."
rows["152:441282728"]="예배당 아래 뭐가 있는지 네 주인은 안다. 그래서 나타나지 않는 게지! 너와 죽음의 기사들만 사지로 보낸 것이다."
rows["152:449216819"]="그랜드 아포테카리 푸트레스와 함께 일하는 것이 영광입니다. 리치 왕전염병이 우리 사안에 새로운 희망을 주었고요."
rows["152:472312080"]="스다도파인이 북서쪽으로 썬더 섬을 공격할 준비를 하고 있다고 들었어요."
rows["152:473356942"]="내가 자동 판매자의 최신 인신이야 언젠가는 세상을 지배할 거야"
rows["152:48848700"]="<Putress는 당신을 매우 불안한 방식으로 쳐다보며>$B$B당신은 놀라운 표본이 아니냐?$B$B더 큰 이익을 위해 희생을 할 수 있다고 생각해 본 적이 있습니까?"
rows["152:527530312"]="내가 다트레마르와 다른 사람들을 따라갈거야.  ⁇ 드라라라들은 너무 멀리 갔어. 악마들과 교류하기 위해 우리는 부패에 굴복하고 있다."
rows["152:570219314"]="우리는 이 고철 덩어리를 녹여서 주괴로 무기를 만들 것이다! 지옥절단기를 얼라이언스 식으로 대접하면 불타는 군단이 어떤 반응을 보일지 지켜보도록 하자!"
rows["152:644353510"]="축제는 시작됐어요 친구들을 초대해$b$b축제의 시작이나 끝에서 불꽃놀이를 놓치지 마세요."
rows["152:690097483"]="내가 피난처가 될거라고 생각했나? 난 피난민이 된 게 내 잘못이 아니야."
rows["152:721354990"]="어느 날 신입생 중 한 명이 내게 장난을 치고 말했어요. 내가 그의 \"보건 안개\"를 냄새가 맡아야 한다고요. 그 안개가 치유할만한 것이 없다고 했습니다."
rows["152:772397013"]="모든 것을 바로잡을 시간이 왔다. 살인자와 도둑이 득실거리는 너희 배신의 왕국을 무너뜨리고 말겠다. 퓨트리스는 시작일 뿐이었다. 그런 놈들이 더 많이 올 테지."
rows["152:789175567"]="당신은 당신의 현재 재능들을 모두 가격에 배워서 새로운 것을 선택할 수 있습니다.\010이렇게 하면 추가로 더 비싸게 될 것입니다."
rows["152:796343309"]="레리쿼리의 최고위원들만이 우리 계급의 대보호관이 어디에 있는지 알고 있습니다.$B$B어떤 사람들은 그것이 존재의 이 평면에서도 없다고 말합니다."
