rows["154:1345950258"]="화난 호젠, 격렬한 예티, 더러운 야크를 거쳐 왔는데 이제 샤도파인은 우리가 낯선 것처럼 행동한다$b$b정말 나쁜 운명이죠."
rows["154:1432549316"]="모고들은 그들의 거만 속에서 그들의 멸망이 그들의 적들 사이에서 아니라 억압받는 사람들 사이에 기다리고 있다는 것을 결코 예측하지 못했습니다."
rows["154:1434724987"]="저 빙하 위에도, 어둠을 뚫고 태양은 솟아오르고야 맙니다. 제겐 희망이 있어요, 타후. 상황이 아무리 암울해 보이더라도 우리는 이 난관을 극복하고 말 겁니다."
