rows["154:1767742575"]="이것은... 실버문? 으, 머리야... 다음번에 블러드밸러가 지원자를 모집하면 다른 방식을 제안해야겠습니다. 선행을 베푸는 혈기사의 모범을 보여주는 역할 말이죠!"
rows["154:1790704533"]="만약 당신이 세상을 구하러 온다면 당신은 올바른 장소에 왔어요. 얼굴 없는 신인, 혈액 신인 하카르가 우리 세상에 다시 데려온 것입니다."
rows["154:1801019101"]="이런 것은 영들 자신도 마찬가지입니다. 그들은 종종 화를 내는 데 빠릅니다. 그러므로 여러분은 그들의 분노에 사로잡히지 않고 귀를 기울이는 법을 배워야 합니다."
