rows["154:611889230"]="여기 보자...$B$B\"공정 f-stop를 찾아내기 F-수수는 '효과적' 열 직경으로 나뉘는 화력장이다\".$B$B이게 내 머리를 아프게 해"
rows["154:650542597"]="아직 불지방으로 진출할 힘이 없어서 먼저 우리군과 물품을 재건해야 합니다."
rows["154:650764986"]="너무 놀라지 마요! 우리는 용들이 의식적이지만, 우리 상자 안에 있기도 합니다. 제가 자라면서 음모와 음모를 들을 수 있었습니다. 저는 포로로 태어날 예정이었습니다."
rows["154:668138192"]="당신이 그 악당의 길을 따라가려면 서쪽 가장 큰 나무의 나선 아래로 서쪽 앙클라브에 살고 있는 시우르나입니다."
rows["154:669119111"]="당신은 해마로  ⁇ 을 죽이려고 하지 않고 적들을 죽일 수 있는 무기를 만들고 있습니다."
rows["154:67657294"]="강성, 브람블스타프 가족의 생명 혈통입니다. 제 후손은 오늘날 어떤 도전자라도 대할 준비가 되어 있는 신체적 위대함의 증거로 살아가고 있습니다."
rows["154:693403692"]="너희가 전투에서 쓰러지면 너희들의 죽음이 선행한 것이며 그가 부활했을 때 너희는 그분과 함께 있을 것이며 그분의 영광에 동참할 것이라"
rows["154:713968349"]="네더스톰의 소식입니다, 신사님 모든 혈액 보석 수입을 중단하세요.$B$B넥슨 공작은 보상으로 우리의 주식을 완전 가격으로 사게 될 거야"
rows["154:734327842"]="피 엘프 보물은 다른 보물들과는 다릅니다. 금이나 실크나 보석으로 사용되는 것뿐만 아니라, 시네도레이 공예품은 그 자체로 귀중합니다."
rows["154:740007225"]="우리는 머리가 없는 승마자의 공포에서 자유로워질 수 있습니다. 우리는 다시 쉬게 숨을 쉬게 될 수도 있지만, 머리와 결합한 동안 패배할 때까지 그는 돌아올 수 있습니다."
rows["154:765796427"]="내가 제안하는 것은, 우리는 Twilight 신단에 행진하고 이 영역에서 죽음의 날개의 이름을 꺼내지 않을 것입니다."
rows["154:772369763"]="십자군 사령관께서 너와 최근에 발견한 너의 친구들을 제거하라고 하셨지. 하지만 말이야 탤런, 이 말은 꼭하고 싶군. 꼭 명령이나 임무가 아니더라도 난 이 일을 하게 되어 즐겁다네."
rows["154:841227035"]="그곳에서 그는 알도르 사제회와 점술가 길드의 지원을 받아 일리단의 군대와 계속해서 전투를 벌이고 있습니다. 그렇다고 해서 그 두 진영이 서로에 대한 오랜 적개심을 잊은 것은 아니죠."
rows["154:852294568"]="그래, 물론 내가 그를 사냥하러 온 거잖아$b$b그들을 찾는 가장 좋은 곳은 호스나 아보레텀입니다."
rows["154:993662157"]="저처럼 모험가가 아니겠지만 근육이 없어진 건 아니잖아"
rows["155:1084595835"]="현재 상황은 이렇다. 경험 많고 더 좋은 장비를 갖춘 병력이 캘타스 왕자를 향해 진격하는 동안, 우리는 온 힘을 기울여 방어하고 있다."
rows["155:1129430043"]="정해진 시간에, 그들은 바람과 물의 원자체를 방출하여 폭풍으로 도시를 몰아넣고 우리 주인 영광스러운 복귀를 준비할 것입니다!"
rows["155:1142578758"]="아나크로노스, 이런 식으로 주의를 끌면 자네와 젊은 드루이드가 문을 봉인할 시간을 벌 수 있을 것이네. 속전속결로 끝내야 하네. 자, 그럼 놈들이 혼돈의 마법에 어떻게 대응하는지 볼까?"
rows["155:1160049584"]="그래, 잘못은 그들에게 있지만 나에겐 그를 막을 힘이 없다네. 툰카로 주민에게 경고해주겠나, 이방인이여? 그들의 선조와 과거가 위험에 처했다고 말이야."
rows["155:1173088497"]="오직 $3658E 크리스마스 전에 쇼핑을 하는 분들! 하지만 잠깐, 크리스마스가 되셨나요? $3659E 파티가 끝나기 몇 분 남았어요"
rows["155:1182021994"]="저는 빛에 대한 제 헌신이 이런 방식으로 사용되어 있다는 것을 자랑스럽게 생각합니다. 우리 고향에 대한 스컬지의 공격은 우리가 대책해야 할 집단 학살 행위입니다."
rows["155:1201694775"]="이 고원에서 그자와 그의 악마들이 태양샘을 가동시켜 그자들의 우두머리인 킬제덴을 다시 이 세계로 불러올 균열을 만들려고 한다."
rows["155:1289916496"]="지금, 저는 마을을 재건하는 데 집중해야 합니다. 할 일이 많이 있습니다. 여러분이 원한다면 여기서 쉬실 수 있지만, 우리는 더 이상의 도움을 받아들이지 않을 것입니다."
rows["155:1296569295"]="수천의 영혼이 느끼는 고통을 지금 너도 느낄 것이다! 너와 네 주인이 데려온 영혼의 괴로움을! 빛이 너를 갈기갈기 찢을 것이다..."
rows["155:1307876222"]="침입자다! 의심할 필요도 없이 은빛 여명회의 졸개들이겠지. 내 죄수들 사이에 놈들 중 하나가 있다는 것을 알고 있다. 어서 내 영역에서 물러가라. 그렇지 않으면 그 여죄수는 처형될 것이다!"
rows["155:1354059393"]="만약 당신이 여기 와서 제 일 특권을 빌려 왔다면, 당신의 회사는 매우 환영합니다. 그렇지 않으면, 당신은 나에게 유용할 가능성이 거의 없습니다."
rows["155:1376442978"]="악마들이 많이 죽으면 레지온은 다시 나무 캠프에 공격하는 걸 두 번 생각해볼 거야"
rows["155:1383635180"]="얼마 전 새로운 우편 배송을 봤어요. 썬더 블러프 은행은 하위 상승에 있습니다."
rows["155:1385101821"]="우리는 많은 위험들을 직면하고 있지만, 우리는 자연을 무시할 수 없습니다."
rows["155:1393563864"]="우리 둘 사이만 있어, 난 너무 짧아서 이런 일을 할 수 없어$B$B내가 이미 한 번 죽었어 두 번이나 하는 건 건 건지 않아"
rows["155:1479115538"]="당신 능력은 내 능력보다 더 높지만, 부티베이에서 노인 헤밍이 \"The Bass and You\"의 복사본을 가지고 있다고 들었습니다."
rows["155:1495564382"]="젊은 왕자님께 왜 이렇게 오래 걸리는지 모르겠지만 더 오래 견딜 수 없을 것 같네요"
rows["155:1510410317"]="보답으로 이 상자들을 받으십시오. 그 안의 물건들이 얼음왕관 성채 깊은 곳에서 아서스와 싸우는 동안 충실히 도움이 되길 바랍니다!"
rows["155:1518198745"]="당신의 세계 샤만은 이미 어둠의 암흑에 빠져 있습니다. 그는 이제 소비하기 위해 존재합니다."
rows["155:1519960939"]="제 지식은 제한적이지만, 저는 여전히 배우고 있습니다. 여행자 여러분, 앞으로 나아갈 시간입니다. 언더시티에서 조셉 그레고리안을 찾아서"
rows["155:1538010423"]="네 반해는 없네, 강아지, 하지만 다른 곳을 찾아서 자고 싶어"
rows["155:1545614769"]="해적보다 더 나쁜 것은 해적들이야! 우리 해변을 침공하고 물고기와 배와 맥주를 훔치는 거야"
rows["155:1592038030"]="우리 는 그 들 의 관심 을 듣지 않음을 결코 말 해서는 안 됩니다. 이 \"그리프타\" 개인 은 거짓 주장 을 하고 있으며, 우리 는 일 을 바로 잡으려는 의도 를 가지고 있습니다."
rows["155:1595878657"]="마틴 린드세이와 비전 풀에서 이야기해 보시면 영광입니다."
rows["155:1607853139"]="하지만 빛 는 내가 잃어버린 것이 아니라는 것을 보여주었습니다. 그 결과, 전 이 모든 사건과 제가 저지른 모든 악에도 불구하고 살아남을 수 있는 힘을 얻도록 도와주었습니다."
rows["155:1629528924"]="배신 혐의로 재판을 받으며 감옥에 갇히게 될 거야"
rows["155:1644864052"]="잃어버린 친구 들 과 동반자 들 을 너무 오래 생각 하지 마십시오. 아마도 그 들 에게 경험 을 나누는 특권 을 누렸다는 것 으로 영광 을 느낀 것 은 가장 좋다."
rows["155:1657894999"]="조심해, 아직 많은 함정이 있어 아마도 악마의 주문 중 하나가 앞으로 나아갈 수 있는 능력을 줄 수 있을거야"
rows["155:1721172597"]="이 깊은 곳들은 정말 악몽입니다.$B$B비록, 아래의 틈에서 함께 벌이는 전투는 이 새끼 고양이가 되고, 무지개처럼 보일 것입니다."
rows["155:172185300"]="내가 어떻게 누군가의 귀를 잘라서 알아차리지 못했을까?"
rows["155:1723124982"]="매일매일 미친 존 스터링이 내가 해달라고 하는 건 다 다크를 닦는 거야$B$B갑판을 씻어내세요?$B$B난 마법사야, 난 스와빈을 하지 않아!"
rows["155:1757456717"]="왕에게 돌아와서 친절한 척하고 검을 꺼내서 왕을 찔러 팔꿈치로 죽인다"
rows["155:1761961331"]="야심찬 어업자... 아멘 포드의 해안에 살고 있는 디크티나, 우리 모두를 공급하기 위해 네트와 막대를 이용하고 있어"
rows["155:177224548"]="언젠가는 죽음을 맞이할 가련한 존재여... 네 놈들이 무슨 짓을 저질렀는지 모르는구나! 그분의 의지가 실현될 것이다. 달숲은 파괴될 것이며, 그와 함께 말퓨리온 녀석도 죽음을 맞이할 것이다!"
rows["155:1846492401"]="병사들은 중요한 일을 하고 있습니다. 사람들의 안전은 더욱 중요하죠, 말. 당신에게는 고객이 하루라도 돈을 쓰는 게 중요하니 말입니다."
rows["155:1852223402"]="네스인그와리의 사파리 남은 것은 네 바람의 계곡 서쪽에 있습니다. 만약 당신이 서쪽으로 가고 있다면, 우리와 함께해 주세요."
rows["155:1889699601"]="하! 그렇게 원한다면야. 청금석 용제단 남쪽으로 가서, 횃불로 이루어진 원 안에 들어가 마그나타우르 대장에게 빼앗은 뿔피리를 불어 보려무나. 명복을 빈다. 그롬타르가 올 게다..."
rows["155:1916621058"]="이 시간대에서 내 존재를 지켜주어서 고맙도다. 이제 나는 돌아가서 나보다 높은 이들에게 보고해야 하노라. 그들도 내가 어떤 일을 겪었는지 즉시 알아야 하기 때문이로다."
rows["155:193938504"]="셸비 스톤플린트는 지역 사냥꾼들을 위한 애완동물들을 많이 보유하고 있습니다."
rows["155:1941075633"]="정말로 고맙습니다. 여기서부터는 혼자서도 백사장 야영지로 돌아갈 수 있겠어요. 참, 잊지 말고 모테가 파이어메인과 얘기를 나눠보세요. 제가 집으로 돌아갔다고 꼭 전해주셔야 해요."
rows["155:2015263255"]="보저는 재능 있는 연습생이고 좋은 친구인데, 하지만 나랑 얘기할 때 목에  ⁇ 이 걸리지만"
rows["155:2033893268"]="내가 섬기는 권능을 알았으면 내 앞에 무릎을 꿇고 우리 편에 합류하는 것을 주저하지 않았을 것이다. 불행히도, 당신의 무지성은 당신의 멸망이 될 것입니다."
rows["155:206321391"]="그녀의 미소를 보면 웃게 되고, 그녀가 마법을 던지면 나를 마법을 던지며, 그녀의 뿔을 보면 흥미롭게 느껴집니다."
rows["155:2082261528"]="신병이신게 틀림없어$B$B오치윈의 그림자 람리운트에서 우리가 이미 무머를 다시 통제했는지에 대한 소식이 있습니까?"
rows["155:2101706159"]="내가? 우서 경, 정당하고도 확고한 내 왕위 계승권에 따라 명한다. 지금부터 그대의 지휘권을 박탈하고 그대의 성기사들에게 근신 조치를 내리노라."
rows["155:314356875"]="무고의 역사는 야만적인 정복과 힘의 시험으로 가득 차 있습니다. 수천 년 후에, 그들의 인종에서 가장 강한 구성원들만이 살아남았습니다."
rows["155:348927240"]="한 번 기억합니다. 키샤인과 함께 낚시하러 갔던 레이크샤이어 오슬로우는 키샤인을 용서한 적이 없다고 생각하진 않나?"
rows["155:355285816"]="대검사가 오고 있어, 죽음의 기사님 준비하세요. 저 마법 반대부장으로부터 당신을 끌어내지 마세요."
rows["155:383223824"]="기운을 내게. 리치 왕은 그가 넬쥴과 합쳐진 곳에서 처치해야만 하네. 첨탑 꼭대기의 얼어붙은 왕좌 말이네. 그게 유일한 방법일세."
rows["155:453237755"]="워워! 진정해, 블랑쉬. 오늘은 너에게 줄 사과가 없단다. 내일 우리가 널 남녘해안으로 데려갈 텐데 너는 배를 타고 바다를 건널 거야."
rows["155:456543893"]="여기 한 명의 사냥꾼이 있는데 그 사람은 그리프 와일드하트입니다."
rows["155:497380346"]="그녀가 우리를 지켜주듯이 그녀를 지켜라. 우리는 죽음으로 함께 될 때까지 안샤와 무샤의 영원한 시선을 통해 기쁨을 누리게 해"
rows["155:508249721"]="벨의 통불에 4:00 오후입니다. 그것은 미들튼의 아포테카리움에서 행복한 시간입니다! 안으로 와서 독이 될 수 있습니다 또는 가스 또는 두 가지 모두 단순한 은 35 에 대해!"
rows["155:522053736"]="크리스탈 레이크에 사는 훌륭한 스킨러가 있습니다. 그녀는 스킨러 직업에 어떻게 시작해야 하는지 보여줄 수 있을 것입니다."
rows["155:522225004"]="여기 돌이 많아서 내가 발견한 것만으로도 세상에서 가장 부유한 사람이 될 수 있겠지"
rows["155:53143525"]="그는 정의롭고 의로운 모든 것을 대표하고 있으며, 다른 여러 덕목도 대부분에게 관심 없는 것입니다."
rows["155:54545579"]="이 엉망이 뭔지 봐 불모의 땅 난생할 거야$B$B이 정글은 밤새 나타나서 이미 내 캠프를 삼키고 도로에서 질식하고 있습니다!"
rows["155:570275907"]="아버지는 야만이고 어머니는 사우르 사제였죠$b$b난 스컬블레이드에게 부끄러움이야 내가 더러운 곳에서 죽을 거야"
rows["155:577359642"]="%s 의뢰를 |cFF0080FF|Hspell:104900|h[블루]|h|r, |cFF424242|Hspell:104894|h[검은]|h|r, 그리고 |cFFFFA901|Hspell:104901|h[유랑]|h|r  ⁇ 마의 피!"
rows["155:588885448"]="서쪽의 뱀 척추에 정복 사령관과 영광스러운 정복 사령관을 찾을 수 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["155:596150087"]="이 지구 표면에 인형 손 인쇄가 자리 잡고 있습니다. 끊임없이 조작되고 조작되는 것 같지만, 지구는  ⁇ 지 않은 채 남아 있습니다."
rows["155:639516310"]="%s 의뢰를 |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, |cFF088A08|Hspell:104898|h[녹색]|h|r, 그리고 |cFF0080FF|Hspell:104900|h[블루]|h|r  ⁇ 마의 피!"
rows["155:649768853"]="저 아래의 용들은 그들의 아버지의 성격을 물려받은 것처럼 보이지만 완전히 다른 존재가 되었습니다."
rows["155:651757166"]="말로는 표현하기 힘들지만, 모든 것이 훌륭할 것 같네요. 말푸리온이 돌아왔어요. 테일드라실은 마침내 용의 측면으로 축복받았죠."
rows["155:662235640"]="이 정도까지 왔어 다른 책상 옆의 라비니아 크로와 만나면"
rows["155:682208667"]="보그림이 옳을 수도 있고, 잠시 쉬어야 할지도 모릅니다.$B$B하지만 이제 우리가 여기 왔으니, 저는 손을 더럽히고 이 땅이 무엇을 제공하는지 연구하기를 간절히 바랍니다."
rows["155:694577303"]="흠, 이런 건 풍경으로나 써야겠군. 이런 것이야말로 전투가 한창일 때 소환하면 절대로 안 되는 것이니까 기록해 놓도록!"
rows["155:708382648"]="부디 일어나게, 내 친구여. 성스러운 빛의 힘을 나타내는 상징으로서 축복받은 마음을 간직하고 있으면, 오랫동안 모습을 감추었던 영웅들이 다시 한번 일어나 모든 이에게 용기를 줄 걸세."
rows["155:71584470"]="필멸의 존재여, 네 목숨 줄을 끊어버리지 않고 관대하게 보내주마. 어쨌든... 내가 왜 가장 쓸모 있는 하인을 없애버리겠느냐? 난 그 힐드니르 광산에서 몇 주간 널 기다렸다."
rows["155:77990279"]="플레쉬브릭스는 스컬지의 괴물, 혐오, 육류 거대 생산의 핵심입니다. 우리가 그것을 제거 할 수 있다면, 리치 왕는 크게 약화 될 것입니다."
rows["155:818079131"]="저는 스칼테스입니다. 이 곳의 조명을 찾는 샤만의 안내자입니다. 하지만 다른 길을 걷는 사람들에게도 한 두 가지 보여줄 수 있습니다."
rows["155:82839412"]="자드 부족은 황금 가을 위기 이후 최악의 일이야 생산이 이미 몇 달 뒤쳐져 있습니다. 뱀은 더 젊지지는 않습니다!"
rows["155:866601098"]="이 과정은 힘든 과정입니다. 먼저 원자들의 동원자들을 불러야 합니다. 그리고 나서 제 부하들이 준비할 수 있도록 그들을 파괴해야 합니다."
rows["155:900886068"]="다운의 꽃에 갔어? 거기 있는 동안 골든드라프트 한 잔 더 챙겼나?$b$b이 곳에서 배달하는 것은 쉬운 일이 아닙니다."
rows["155:923648382"]="리 페이 선생의 목소리는 \"화감한 후오는 굶주림으로 유명하다. 그는 텐더를 먹고 싶어한다. 바람의 애정이 그를 깨우치게 한다\"."
rows["155:927820548"]="우리 형제는 길을 잃어 지었습니다. 그는 땅을 태우고 물을 증발시키고, 너무 많은 공기를 삼키고 있습니다.$B$B그를 균형과 조화로 되돌릴 수 있도록 도와줘"
rows["155:947591191"]="내 전문성을 뛰어넘는 것들을 배우기 시작해"
rows["155:986086319"]="로머스, 동맹 없이 우리는 이 전쟁의 물결에 의해 압도될 것입니다. 가로시와 중간 경로는 없습니다. 우리는 그와 함께 또는 그에 대항해야 합니다."
rows["156:1083778658"]="전문 판매자 는 항상 각종 트레이너 근처 에 발견 될 수 있다. 다른 종류의 판매자 는 스톰윈드 전역 에 흩어져 있다.$B$B뭐라 생각했지?"
rows["156:1087062123"]="레드리지에 사는 사람들이 얼마나 조롱한지 알아봤나?"
rows["156:112677249"]="그리고 가장 좋은 점은 다른 인간형의 육류에 대한 갈망이 있다는 것입니다. 그들의 부패한 시체를 먹어버리는 것이 저에게 힘을 줍니다."
rows["156:1147765156"]="오크를 죽이는 걸 좋아하고 말을 많이 하지 않는 사람이라면, 잘됐어요!$B$B그렇지 않으면, 이쪽에서 아름다운 포털이 있는데, 이 때 아주 아름답다고 들었어요."
rows["156:1152622282"]="코르크론, 오그림의 망치호 최후의 비행을 준비하라! 용사들이여, 성채 위쪽 적당한 곳을 찾아 비행포격선을 대겠네. 거기서 만나세!"
rows["156:1161124687"]="모고 제국은 수백 년 전에 무너졌는데, 이 유적들은 여기 남아있었고 버려져 있었습니다. $B$B왜 지금 다시 올까요?"
rows["156:1163369398"]="저층 방사능은 치명적일 수도 있지만 무시하는 것이 더 치명적일 수도 있습니다"
rows["156:1201008693"]="하지만 얼라이언스은 우리의 권리를 인정하지 않습니다. 그들은 이 땅을 그들의 소유라고 주장하지만, 이 왕국을 설립한 사람들의 주장을 무효화하려고 시도합니다."
rows["156:1206975428"]="마칸 앤볼이 썬더브루 디스틸러리에서 몇 개를 다시  ⁇ 을 거면 안되니"
rows["156:1209605025"]="기름에 가득 차 있다면, 불꽃이나 불꽃의 모든 원천을 피하십시오. 촛불과 연소, 마법사, 케스터의 가게, 그리고 비서 클렁키!"
rows["156:1214397304"]="실버브룩은 북서쪽에 있습니다. 사냥꾼과 함정꾼들의 작은 공동체입니다. 그들은 땅의 배경을 알고 있습니다."
rows["156:1220071829"]="목재 창고를 열려고 합니다.$b$b나무들이 다 잘려내기 위해 기다리고 있는 거니, 이 기회를 놓치지 않는 건 바보같아!"
rows["156:1236017398"]="마침내, 진해가 일어나기 몇 달 전인 후,  ⁇ 은 돌아왔다. 옷들을 갈라지고 대대를 땅에 던지면서 지진과 홍수파에 대해 이야기했다."
rows["156:1260928078"]="잘했어, 눈 안의 불꽃이 있잖아... 나도 잘 알아, 내가 강아지였을 때랑 같은 불꽃이야!"
rows["156:1266480903"]="농사를 짓기 전에 식사가 어디서 왔는지 생각해 본 적이 없어요.$B$B이 경험 은 조금이라도 설명 할 수 없을 만큼 유익 한 경험 이다!"
rows["156:1278725447"]="네가 왜 왔는지 안다. 저 평원의 멍청한 마그나타우르 하나가 문제를 일으켜서 용을 끌어들이고 만 게지. 그래, 용족의 앞잡이 노릇이 맘에 드느냐?"
rows["156:1314327126"]="한몽드 자데드라는 학자가 당신을 도울 수 있습니다. 당신은 그를 달의 성전에서 찾을 것입니다."
rows["156:1338959275"]="우리가 맞서고 있는 세력은 Twilight's Hammer, Ragnaros 또는 Deathwing를 넘어선 것입니다."
rows["156:1341580334"]="제가 알고 싶습니다. 아마도 그것은 안개와 관련이 있을지도 모릅니다. 아니면 10천 년 전에 해양에서 방출된 힘과도 관련이 있을지도 모릅니다"
rows["156:1350241137"]="더욱 희한한 것은 그 거대한 악마가 둥둥 떠다니는 자그마한 빛 같은 것들에 죽임을 당하는 것이었습니다. 아, 그리고 저는 여자 엘프였습니다. 네... 황당했지요..."
rows["156:1351521378"]="난 그롬골로 갈 수 없어 너무 불공평해 덥고 증기있는 해변 크로콜리스크, 랩터"
rows["156:1361206257"]="신예의 실크마스터 타이이 가 지지를 깎아 내렸을 때 이렇게 미세한 실크줄을 만들었던 때를 기억합니다."
rows["156:1382302861"]="이 요새는 강화되었지만 우리 적들은 모든 곳에서 가까이 다가오고 있습니다. 우리는 더 깊은 내륙으로 진출하기 전에 해안에서 위치를 확보하는 것이 현명합니다. "
rows["156:1443146533"]="도시에는 세 개의 은행이 있습니다. 북쪽으로는 달라란 은행, 남쪽으로는 달라란 상인 은행, 그리고 도시 아래에서 더 많은 은행이 세로로 있습니다."
rows["156:1511319131"]="그렇다면 우리 는 역사 에 대한 당신 의 지식 을 시험 해 보겠습니다. 아타스가 그녀를 죽은 사람 들 로부터 부활 시키기 전 에 스컬지에 봉사 하기 위해, 시드라고사 는 어떤 용 비행 의 일부분 이었습니까?"
rows["156:1561216911"]="자엘라, 배신자 바보... 당신은 당신의 영혼을 호드에 팔았습니까?"
rows["156:1577666411"]="그 덩어리들은 5세대 동안 우리 가족의 집이었다.$B$B우린 그걸 되찾아갈 거야$B$B우린 숫자로 적자지만 와일드햄어야"
rows["156:1601063842"]="노블레가든, 다른 사람들이 그들의 존엄성을 버리고 색다른 달걀을 사냥하는 것을 보는 것은 너무 재미있지만, 그들은 이상한 마법의 분위기를 가지고 있습니다."
rows["156:1627321721"]="그들이 폐허의 도시 샤트라스로 이끌려 왔을 때 살아남은 소수의 드레나이 사제들은 바로 이곳의 부서진 신전에서 의식을 거행하고 있었습니다."
rows["156:1632409491"]="마드 카오 파오와 그의 보석 다니오는 마지막에 발견된 곳은 영속 꽃의 계곡에서 $b$b<벤은 네 지도에 지점을 표시한다.>$b$b"
rows["156:1638679133"]="스카르렛들이 수년 동안 겪은 고통, 고문, 열정, 살인 등$B$B계속할 수 없지"
rows["156:1638974179"]="<라티온은 혼자 앉아 손가락에 게임 조각을 돌고 있다. 그는 게임 보드에 집중적으로 쳐다보고 있지만 그의 마음은 다른 곳에 있다는 인상을 얻는다.>"
rows["156:163907783"]="그 소년은 자유롭다고 믿었지만 자유의지가 대가를 치르지만 내가 멀리했던 악마들은 이제 그에게서 풀려났고, \010"
rows["156:1652381991"]="또 다른 학생이, 멋지네요. 그래서 라이돈이 감독을 맡고 있고 내가 강사로 갇혀있어요. 또 다른 교수상을 받으면,"
rows["156:1671571734"]="하지만... 아직은 리치 왕을 섬길 때가 아니다... 그래... 더 큰 운명이 너를 기다린다. 힘을... 나를 섬기기 전에, 너는 더 큰 힘을 길러야 한다."
rows["156:1676448601"]="카엘타스를 떠나고 있는 것은 우리 중 한 명이 한 최고의 일이었습니다. 그의 추종자들은 그가 어디로 인도하는지 깨닫지 못하기 위해 너무 맹인이나 너무 두려워합니다.$B$B하지만 우리 는 그렇지 않습니다."
rows["156:1750287288"]="모구지아를 조사해봤어? 그 작은 오징어 왜너가 다른 곳으로 도망쳤다고 말하지 마."
rows["156:1786599397"]="브루마스터 블랑시를 만났나요? 그녀는 남쪽과 동쪽으로 길을 떠다니며"
rows["156:1795985456"]="시로나스 유신들이 사루안을 위한 계획을 가지고 있다는... $B$B< 글쓰기는 갑자기 멈춰서 긴 줄이 페이지에서 사라집니다. 이 드레네이가 입장을 작성하는 동안 죽었습니다.>\010"
rows["156:1821317575"]="이 상자가 난 죽기 전에  ⁇ 고 피가 흐르고, 그리고 그 정신은 오랫동안 어둠 속에 버려질 것입니다."
rows["156:1828001683"]="내가 준 왕관은 네 세 번째 눈처럼 될 거야 우리를 묶어줄거야 네가 보는 걸 보게 돼"
rows["156:1850986021"]=" ⁇  주 신하, 만티드들은 90년 전부터 이런 숫자로 보이지 않았어."
rows["156:1904577217"]="여기  ⁇ 을 찾는게 별로 행운이 되지 않겠지만, 아이언포지은 재능 있는  ⁇ 을 사는 곳이죠. 왜 경비원한테 물어보지 않는가?"
rows["156:1935332061"]="당신은 정말로 당신이 리치 왕의 군대를 이길 수 있다고 믿습니까? 살아있는 군대의, 당신이 가져오 수있는 힘은 내 순위를 파괴 할 수 없습니다!"
rows["156:1938466408"]=" ⁇ 프들은 내가 가게를 운영하는 데 도움을 주도록 허락해줬어요!$B$B<아들린은 갑자기 당신을 쳐다보고 매우 진지한 모습으로 보입니다.>$B$B꽃이 좋아?"
rows["156:196034643"]="낚시는 정말로 쉽지요. 낚싯대에 줄을 묶어 끝에 미끼를 달고 물에 던지기만 하면 되거든요. 그러면 고기들이 입질을 시작할 겁니다."
rows["156:1972891267"]="네, 좋은 일이 있어... 너와 네 사람들한테 더 잘 됐어 기술공하지만 우리 모두는 왕국을 발전시키고 움직일 여유가 없습니다."
rows["156:198817365"]="내가 너랑 장난을 치고 있다고 생각하니? 난 너랑 장난을 짓지 않아. 난 여기 오그리마에서 왔어. 난 노그의 머신샵에서 왔어, 그리고 난 자비의 임무로 왔어."
rows["156:2009168421"]="우리와 함께 하여 최후의 길을 택하라 되살아난 자육신보다 강하다!"
rows["156:2010471323"]="그림너의 빛은 잘 작동했지... 오, 모든  ⁇ 이 너무 아프지 않았으면 좋겠다... 하지만 고기를 맛볼 때, 그것은 가치가 있다는 것을 알 것이다!"
rows["156:2030714007"]="당신은 로 핑 사령관과 정의의 표지를 교환할 수 있습니다. Townlong Steppes에 있는 Niuzao 성전에서 찾을 수 있습니다.$B$B네 지도에 그의 위치를 표시해 줄게"
rows["156:2033774589"]="우리는 벽의 감시자, 어둠의 관리자, 그림자의 주인입니다."
rows["156:2057901834"]="멋진 여러분, 오늘 여러분은 위대한 챔피언으로 여기 증명되었습니다. 스컬지 어쩔 수 없는 일이죠!"
rows["156:209036765"]="적에 피해를 주면서 동시에 날 지속적으로 회복시키려면 착취 독을 사용하라. 악몽 접근 기술은 매우 강력하지만, 나에게까지 피해가 오니 내 체력이 많을 때만 사용해야 한다!"
rows["156:2102536102"]="%s 의뢰를 |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, |cFF0080FF|Hspell:104900|h[블루]|h|r, 그리고 |cFFFFA901|Hspell:104901|h[유랑]|h|r  ⁇ 마의 피!"
rows["156:2106521684"]="알란나 라벤예는 그녀의 마법의 재능의 일부를 오라클 글레이드에서 영들과의 교류로 유인합니다."
rows["156:274012351"]="아직도 신기한 보물을 찾았다고 믿기지 않아요. 그 모든 민속이야기는 사실이었지 않겠지만, 여전히 이야기를 하는 걸 좋아합니다."
rows["156:287725198"]="당신은 나의 주인이신 일리단 님의 적이 되는 겁니다. 그러면 살아남을 수 없으리라는 사실은 알고 있겠지요? 과연 거인들이 해그늘 주둔지의 군대를 상대할 수 있을까요?"
