rows["156:395348904"]="이 땅은 한때 위대한 진주 제국으로 속해있었고 우리 왕국이 쇠퇴하면서"
rows["156:404207992"]="더는 돌벽과 성문 뒤에서 기다릴 수 없다! 복수의 기회를 놓칠 수 없다. 우리가 분노를 터뜨리는 날 용족은 두려움에 떨리라."
rows["156:407242261"]="내 외모만큼이나 내가 존경하는 유일한 것은 이 곳 주변에 자라는 희귀한 흰색 꽃입니다.$B$B하지만 찾아보기 힘들죠."
rows["156:416127590"]="이 사후의 일은 별로 나쁘지 않아, 많은 사업 기회를 볼 수 있어"
rows["156:468318208"]="티토야, 우린 집으로 갈 방법을 찾아야 해! 늙은 마법사가 우릴 도와줄 수 있을 거야! 허수아비, 사자, 양철통아... 우리? 오... 맙소사, 손님들이 온 것 같아!"
rows["156:501608629"]="사테인은 에버송에서 린크스 스킨을 발견했는데, 그의 창조에 완벽해."
rows["156:504739096"]="이봐, 낯선 사람, 전 명예로운 로어워커에게 말한 것과 똑같은 것을 말해줄게$B$B매너가 한 마디로 더 가까이 다가오며 눈을 넓혀요$B$B- 아니, 제이드!"
rows["156:50736207"]="동부 왕국을 그리워요? 스톰윈드 정말 복귀를 갈망한다면 더 따뜻한 날씨가 좋겠군"
rows["156:613840916"]="누군가 제 일을 진지하게 받아들이는다면 감사할 겁니다. 난 상어와 싸우고,"
rows["156:807012347"]="내 동생이 잘 지내길 바랍니다 듀로타 ⁇  냄새가 나는 오크들이 많아요."
rows["156:835935447"]="마더리 해머 탈북자, 동남쪽 산들을 자세히 살펴봐"
rows["156:914241564"]="프라우드무어여, 대족장께선 진실을 말하고 계시다. 이번 일은 바리마트라스와 퓨트리스의 얕은 꾀로 일어난 일이지. 호드가 한 일이 아니다."
rows["156:956201839"]="내가 가르치는 것을 배우기 위해 당신의 능력이 충분하지 않아 그 대신 그쪽 마크와 이야기해봐요. 당신은 더 고급 수업을 준비할 때까지 그는 당신을 도울 수 있습니다."
rows["156:956667073"]="이 사람 중 한 명에 대해 이야기 들었는데요. 스피프트의 수베타이는 뛰어난 활사꾼이자 천재 도둑으로 잘 알려져 있었습니다. 그는 부유한 사람들에게 훔쳐갔고, 모든 것을 자기에게 보관했습니다."
rows["156:962570868"]="이 일지를 번역하면서 일지를 쓴 사람보다 '앤드류 클레멘타인'이라는 자가 술에 취해 세운 공적에 대해 더 많이 알게 되었군그래."
rows["156:96812305"]="브루월 페스티벌에 갔어? 정말 반갑습니다. 축하를 위해  ⁇  라이 키커를 준비하고 있어요.$b$b빈 마을에 같이 가자?"
rows["157:1013157137"]="내 군대는 아직 오지 않았어 내가 고용한 사람들을 믿을 수 없다는 걸 알았어요. 우리는 새로운 사람들을 모집할 것입니다. 우리는 이 사과들을 팔고 우리의 새 군대가 그들을 꺾을 것입니다."
rows["157:1019512802"]="내가 돈으로 살 수 있는 최고의 괴물 부품들을 가지고 이 블러드 엘프 배에 주먹을 수 있었지"
rows["157:1020056869"]="마지막 구절은 와일드햄러를 행동으로 불러 일으키는 사랑의 기념일입니다$B$B\"통일... \"에 대한 리임이 필요해"
rows["157:1036625478"]="스컬지가 오기 전에, 저는 훌륭한 사업을 했습니다. 저는 모든 것을 사고 팔았습니다. 모든 것을!$B$B그리고 내 가격은 미친 짓이었어!$B$B그냥 죽지 않은 사람한테 물어봐"
rows["157:1038644144"]="우리 스카이 가드 에더 테크와 그녀의 여사는 바시르 크리스탈 forgings 연구하고 있습니다. 그녀는 도움이 필요!"
rows["157:1084627403"]="클라라 헨리는 마법의 물품을 들고 있습니다. 당신은 건물에 들어서면서 왼쪽에 있는 공예관에서 찾을 수 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["157:1095776346"]="제가 승용으로 기소된 유출자가 사라졌다는 것을 알려드리기 위해 죄송합니다. 다른 유출자를 승용할 수 있도록 허락해주시겠습니까?"
rows["157:1114202718"]="등록자는 임무를 올리기 전에 임원장 모이프  ⁇ 과 이야기해야 합니다.$B$B승인되지 않은 게시물을 작성한 사람은 처벌을 받게 될 것입니다.$B$B결제도 안하고"
rows["157:1285089259"]="수직을 배울 수 있는 희망이 있다면 메린을 찾아보셨을 겁니다. 다르나서스."
rows["157:1309670368"]="화재가 발생했을 때 승무원들의 신속한 대응을 보장하기 위해, 연료 저장소는 승무원 방에서 옮겨 승객 방 아래로 배치되었습니다."
rows["157:1346507173"]="그 브램블스타프 소년이 야생에 있는 거고, Thunder Cleft의 타우런들과 동행하고 있어.$b$b- 같이 갈래?"
rows["157:1347229357"]="비극적이군. 저 늙은 폴드링이 아직 살아 있다니... 이보라고, 당신은 너무 오래 살았어. 뒤틀린 황천에 있는 아들을 따라가고 싶지 않으면 다시 동굴로 돌아가서 숨어서 지내라고!"
rows["157:1356749125"]="이 전쟁은 네가 본 전쟁과도 다른 전쟁의 전선이다$b$b도움이 될 수 있다면 전력을 완전히 발휘해야 합니다."
rows["157:1386406695"]="린링은 총기술관을 운영하고 있습니다.$b$b세가지 목표가 있을 뿐이고, 더 빨리 할수록 더 잘할 수 있습니다.$b$b개인적으로, 이건 제가 좋아하는 게임 중 하나입니다."
rows["157:1415298179"]="네가 온 이후로 모든 것이 좋아지기 시작했어\010농장에서 친구들에게 무슨 일이 일어났는지 생각해보는데..."
rows["157:1417816392"]="육상 공격에 필요한 물품이 충분해 명령들을 전달하고 자격을 갖춘다면"
rows["157:1417956289"]="이 나이트 엘프 사원 밑을 지나는 지맥은 이제 청금석 용제단으로 흘러가게 됩니다. 곧 적들을 물리칠 힘이 형제들에게 전해질 겁니다."
rows["157:1427817201"]="|TInterface\\Icons\\ability_deathknight_remorselesswinters2:20|t동맹군으로부터 멀리 떨어져라 |cFFF00000|Hspell:136991|h[냉각을  ⁇ ]|h|r!"
rows["157:1431094759"]="이제 우린 좋은 친구니까 고백해야 해 농부 펑을 좋아하지만, 또 다시,"
rows["157:1486462691"]="그는 속삭이는 시민들보다 더 많은 것을 알고 있으며, 이 배신자가 도시들의 마지막 잔류라고 확신하고 있습니다."
rows["157:1529872363"]="어리석은 자들아, 우리 주자가 눈이 멀다고 생각하느냐? 우리가 이 침략을 알지 못한다고 생각하느냐? 우리 여동생들이 와서 그들의 분노에서 벗어날 수 없다."
rows["157:1544333570"]="아세스미팅 기술을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면, 아세스미싱이 만들어야 하는 모든 레시피를 잊어버릴 것입니다!"
rows["157:1610780017"]="\"북쪽\"과 \"서쪽\"을 뜻하는 룬은 뺐습니다. 거인에게 어떤 영향을 미칠지 확실하지 않아서 말입니다. 그리고 얼마 동안 제어할 수 있을지 정하는 룬도 넣고 있습니다."
rows["157:1641892491"]="이 벙커에서 남서쪽에 있는 프로스트울프 분기장."
rows["157:1657158228"]="유명한 아이사 클라우드싱거에게 도움을 요청하러 왔지만 그녀의 운동에 방해를 받기 힘들어요."
rows["157:1681419622"]="아니, 난 다시 돌아갈 수 없어 오그리마내 가족들을 위해 애도하지만, 그들은 그들의 선택을 했고, 나는 내 결정을 내렸다."
rows["157:168264306"]="어서 농장에 가서 한번쯤은 할 수 있겠지만 당장 할 수는 없어 먼저 시장에서 해야 할 일이 있어"
rows["157:1804767438"]="윈드워드 섬에서 희귀한 오닉스 알을 발견할 수 있다는 걸 알고 있었나요? 뱀장어에게 하나를 가져와도"
rows["157:1816679063"]="분노는 우리 모두의 일부이지만 통제를 중요시 합니다. 오크들은 한때 분노에 의해서만 움직였는데, 그들은 혈식 상태에서 살았지만,"
rows["157:1881037736"]="전투에서 경쟁자들을 만나야 한다. 승리하든 패배하든 전투 기간 동안 남아 있으면 경쟁자 타바드라는 우편을 보내야 한다."
rows["157:1912585101"]="만약 그래면, 호네의 스웨이 디쉬 셰프가 당신이 찾고 있는 것을 가지고 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["157:1943453407"]="달라란 북서쪽에 있는 마구스 무역 거래소에서 농림 약국에 온실이 있습니다."
rows["157:1992423752"]="티탄이 이 세계를 돌보지 않은 지도 오랜 시간이 흘렀습니다. 이제 이곳엔 한때 무리를 이루고 살았던 나이트 엘프들만이 이 땅을 지키기 위해 남아있을 뿐입니다. 오, 이런! 다음 구절이 아주 흥미롭군요!"
rows["157:2011266032"]="아, 왜냐하면 이 이야기에서 배우이기 때문입니다!$B$B그냥 오래된 무더기에서 역사를 읽는 것보다 훨씬 낫죠, 동의하지 않나요?$B$B이제 앞으로 가서 배우고!"
rows["157:203022155"]="내가 시노도레이와 협상을 하려고 했지, 그들을 얼라이언스에 데려오려고 논의를 열고 있었지!"
rows["157:2053697405"]="오늘, 여러분은 많은 훈련자들을 만나게 될 것입니다. 그들은 그들의 기술을 정교하고 자신을 증명했습니다. 애완 동물들은 여러분도 같은 이야기를 할 수 있을까요?"
rows["157:2058112531"]="멍청한 드루이드, 너의 본질을 분할하는 것은 너를 약화시켰고, 내 주인에게 에메랄드 드림을 지배할 수 있는 문을 열어주었다."
rows["157:2125375498"]="할아버지의  ⁇ 을 나머지 도구와 함께 남겨뒀어요$B$B그 땅을 채굴해서 다른 것을 위한 공간을 확보할 수 있습니다."
rows["157:237342707"]="리리안, 넌 나처럼 포세이큰 중 한 명이야. 그래서 질문은 이러지: 왜 붉은십자군가 널 구두에 넣었나?"
rows["157:263155608"]="드디어 그 끔찍한 저주에서 풀려났구나! 고맙습니다! 릴라크에게 저는 무사하다고 전해 주십시오. 저는 스케티스에서 할 일이 있습니다. 테로크를 처치해야 합니다!"
rows["157:264980631"]="쉬워요, 아들아, 우린 지금 다른 전쟁을 벌이고 있어요. 이건 호드에 대한 증오가 아니라 옳은 일을 하는 것에 대한 사랑입니다."
rows["157:280008856"]="무기가 끝났어. 우리 일을 호드적들이 왜 우리를 두려워해야 하는지 상기시켜주도록 사용하세요!"
rows["157:289526607"]="오늘 밤, 충직한 동료의 도움을 받아 고향으로 돌아가기 위해서 필사적으로 노력하는 길 잃은 한 소녀를 통해 인간의 영혼은 그 깊이가 얼마나 되는지 알아보겠습니다!"
rows["157:317964208"]="더 가까이 오지 마, 필사자. 내가 서 있는 곳에서 악이 봉쇄를 통과하는 것을 느낄 수 있다.$B$B잠깐만요, 물품을 확인해 주세요"
rows["157:317989099"]="소크레타르가 네 정신을 흐리게 하고 있어, 카일란! 네가 그런 말을 할 리가 없는데! 열심히 훈련하던 네 어린 시절 모습을 난 기억한다. 그때 네 의지가 훨씬 강했어!"
rows["157:328989716"]="진정한 지혜의 교훈은 여러분 안에 있습니다. 사랑하는 영웅들, 그리고 여러분이 하는 선택에서요."
rows["157:33123797"]="브랙이 이 텔레포터 기기가 테스트됐다고 했나요?"
rows["157:355353203"]="엄마 없는 무산 목자들이여, 당신들의 족속을 비난하겠지만 두개골은 너무 덩어리해서"
rows["157:380620488"]="바네사 반클리프는 여전히 어딘가에 있습니다. 우리에 대항해 음모하고 있습니다. 다행히도, 이 기지가 없으면 그녀는 얼라이언스의 힘에 대해 거의 무력합니다."
rows["157:458330359"]="이 여왕 은 대지사태가 발생 하고 포세이큰가 그 나라 를 공격 한 후, 그 들 의 백성 을 탈출 시키기 를 감독 하였다."
rows["157:468037151"]="요르문가르는 즉시 무너졌고, 녀석의 머리는 경련을 일으키는 몸뚱어리에 간신히 붙어 있었습니다. 제 아버님께서는 경외에 차 그 드워프에게 돌아서시고는 찬사를 보내면서 주먹을 치켜 드셨습니다..."
rows["157:470882782"]="여기 한 농민에서 다른 농민에게 팁이 있습니다. 하프힐 시장에서 구입할 수 있는 업그레이드들이 많습니다. 지나 무드클라우는 도구를 판매하고, 머처트 그린필드는 씨앗을 판매합니다."
rows["157:505094579"]="지금, 내가 무슨 생각을 하는지 알아요. 올그리프타가 곤경에 처해 있어. 이건 아무 것도 아니지. 아직 내 주머니는 많이 있어요."
rows["157:544841095"]="포크 포크는 호드과 거래를 하지 말라고 명령했다.$B$B<상가가, 분노하여 땅에 뱉어내지만 더 이상 이 문제에 대해 말하지 않음>"
rows["157:551865323"]="내 신뢰 영웅을 얻었으니, 스태프를 썬더 킹의 대리 위에 올려 놓으면 나머지는 다 할 거야."
rows["157:562752794"]="내가 어릴 때 그랬던 것처럼 높은 곳을 두려워하지 말라 두려움은 우리를 끔찍한 일에 이끌 수 있습니다. 아, 하지만 나처럼 당신은 용기 교훈을 배웠음을 봅니다."
rows["157:581445579"]="이 물건은 철 군대를 파괴해야 해 더 좋은 건, 내가 본 기계들과 달리 네 얼굴에 폭발하지 않을 거야"
rows["157:5889450"]="얼마나 끔찍한 최후인가. 영웅들이여, 갑시다. 그 노움의 말이 진실인지 확인해야 해요. 아서스와 서리한을 떼어놓을 수 있다면, 그를 막을 기회가 있을지도 몰라요."
rows["157:618409701"]="오늘 큰 공을 세웠군. 말가니스가 남긴 건 모두 너희 것이다. 보상으로 받아 둬라. 난 이제 노스렌드 원정 준비를 시작해야겠다."
rows["157:682819663"]="알케미스트들은 태양의 궁전에서 위치하고 있습니다. 당신은 캠베론을 발견할 것입니다. 당신이 맥주 조션의 예술에 대해 알고 싶은 모든 것을 가르쳐 줄 것을 간절히 바랍니다."
rows["157:686582760"]="테룸 딥포리지는 당신이 얘기하고 싶은 왜기입니다."
rows["157:699119112"]="배고프지 않아? 출출한데... 툴타쉬의 보존용 햄으로 만든 스테이크가 또 생각나서 견딜 수가 없네. 육즙 가득한 그 구운 고기를 한입만 먹었으면!"
rows["157:755278046"]="가장 좋은 것은 우리가 계속 피를 흘리는 영광을 높여주게 될 것입니다. '인간'이라는 인종은 동맹의 적입니다."
rows["157:796667963"]="이건 정말 이상해요. 샤도파인은 최고의 고객입니다. 우리는 그들에게 물품을 팔고, 그들은 우리를 안전하게 지키죠.$b$b왜 우리를 회피하고 있는 걸까요?"
rows["157:82365249"]="루아다는 아저워치 동부에서 젊은 전투자들을 훈련시키고 있습니다. 실제 전쟁 예술에 대한 훈련이 당신이 찾고 있다면, 그녀는 당신을 도울 것입니다."
rows["157:841563861"]="아락세스! 지원이 필요합니다! 광산에 갇혔습니다. 제가 있는 위치가 정확히 어딘지는 모르겠지만 여기까지 오면서 땅에 자유연합 추적장치를 떨어뜨려 놓았습니다."
rows["157:923020448"]="브루마스터 시나리오에 참여하는 사람들은 용기를 얻습니다. 그리고 당신이 브루마스터와 모험을 할 때 희귀한 물건을 발견하면, 그들은 당신의 것입니다!"
rows["157:991488729"]="리리아가 훈련이 필요하다면 얘기해야 할 사람인데"
rows["158:1069921591"]="스톰하트 왕께서는 우리를 잘 지도해 주셨습니다... 서리 거인들과 싸우며 용맹을 떨치던 과거의 우리보다 더 대단한 전사로 우릴 탈바꿈시켜 주셨습니다."
rows["158:1084315516"]="우리는 운 좋게도 골짜기를 찾았습니다. 그 골짜기는 문을 열고 나서서 피난처를 찾아보았으며, 안전한 항구지를 찾았죠.$B$B길을 잃었나?"
rows["158:1101884337"]="안녕하세요, 익숙해 보이시죠?$B$B우리가 만난다면... 비밀 코드가 주어졌어."
rows["158:1128117410"]="안녕하세요, 파트너, 미스 다라가 저를 만들어서 모든 순례자들이 안전하고 잘 지내도록 만들었습니다.$B$B클랭키 부장님 안전 조언에 귀를 기울여주세요!"
rows["158:1155824909"]="사실 알도르의 많은 사제들이 나루를 섬기겠다고 맹세한 그 마법학자들에게 살해되었었지요. 사제회의 일원들은 한때 적이었던 자들과 같은 도시에 산다는 게 별로 달갑지 않았던 것입니다."
rows["158:1216039695"]="이 자료에 따르면 모고와 그들의 주인은 판다리아로 보내졌는데, 그들은 큰 어둠을 쫓아다니고 있었습니다."
rows["158:1238818380"]="전투에서 경쟁자들을 만나야 한다. 승리하든 패배하든 전투 기간 동안 남아 있으면 경쟁자 타바드라는 우편을 보내야 한다."
rows["158:1310632289"]="그 마녀는 분명히 유망원도들을 불러내지 않았죠! 다음 도전은 아르헨트 십자군 기사들과 싸우는 것이겠죠."
rows["158:1312199878"]="이 탑은 완전하고 완전히 미친 짓이야 이건 도서관이 아니라 책들이 엄청 많고 바늘도 존재하지 않는다고 생각해요!"
rows["158:1312397305"]="마을 북서쪽의 큰 텐트 안에 차브 스트롱하이드가 살고 있습니다. 그는 현재에 대해 알아야 할 모든 것을 가르쳐 줄 것입니다."
rows["158:1314700711"]="전쟁꾼들은 보통 돼지와 휘슬 타버너나 구시대의 병합에서 찾을 수 있습니다."
rows["158:1318663066"]="빌헬름 형제 는 종종 리리아 두 라크 와 함께 골드샤이어아마 그에게서 paladin가 되는 것에 대해 배울 수도 있을 겁니다."
rows["158:1400682682"]="아타스 왕자, 전 듣듯이 프라우드무어 딸을 쫓아다니며 시간을 보냈어요\010"
rows["158:1401372311"]="이 일을 끝낼 수 있을 만큼 오래 살아남을려면 그들을 꺾어야 합니다."
rows["158:1420242302"]="널 저주한다, 아카마! 나는 네 장기판의 말이 아니야... 내 의지는 나만의 것이야. 내가 일리단을 쓰러뜨릴 때 네 멍청한 계획은 아무짝에도 도움이 안 될 것이다!"
rows["158:1433295708"]="데레는 뱀의 성지였는데, 바ಂಬ라 동쪽에는 덤불이 있고, 덤불에 목을 던질 수 있어."
rows["158:1500606498"]="여기에 모인 우리는 모두 명예로운 전투의 개념을 가지고 있습니다. 명예로움을 담고 처신하며 자신이 대우받고자 하는 것처럼 자신의 적을 대우하는 일은 존중을 나타내는 길입니다."
rows["158:1502532644"]="\"목숨으로써 날 섬긴다면 네 영혼에 깃든 연약함을 제거해 주겠다. 그 존재 자체를 지워주겠다!\" 그분께 선택받고자... 난 그렇게 리치 왕의 축복을 받게 되었다."
rows["158:1505673129"]="적어도 악마들은 숲을 더 이상 손상시키지 않을 거야 하지만 내가 이 힘을 내 소유로 주장한다면"
rows["158:1602379967"]="아르젠트 오브란스 형제들의 희생은 결코 잊혀지지 않아야 합니다. 빛 이 땅으로"
rows["158:1642980392"]="오스틸 드 몬이시죠. 그는 항상 남동쪽 끝의 타버너에서 놀고 있어요."
rows["158:1708912854"]="하지만 파티가 별로 필요없어요. 가로쉬라는 위험한 전쟁 지도자가 신성 벨을 찾았어요."
rows["158:1715846058"]="제 주인 바론 사벨메인의 명령으로 이 자리에 있습니다. 제나리온 탐험대에 그들의 종교적인 문제들을 해결하도록 도와드리려고요.$B$B이런 일에 대해 저는 전문가입니다."
rows["158:1734912065"]="랭킹 아레나 경기는 $4262d 시작됩니다. 챔피언이 될 가능성이 이미 자신의 기술을 향상시키고 그들이 할 수있는 최고의 장비를 획득하는 데 바쁘다. 당신은 준비가 될거야?"
rows["158:1807908966"]="옷은 더 큰 문제의 표명일 뿐이에요. 당신은 배울 수 있을 거라고 믿어 의심치 않습니다. 하지만 정신과 형태를 모두 바쳐야 합니다."
rows["158:1906273362"]="텐그 스터머말트와 얘기해봐요, 네 바람의 계곡에 있는 스톰스타우트 맥주 공장에서 찾을 수 있어요.$B$B지도에 위치를 표시해줄게요"
rows["158:1929116320"]="아래를 보세요! 우리들의 도시와 동굴에 대한 지속적인 공격은 적들을 혼란에 빠뜨렸습니다. 모고와 젠다라리들은 이미 호드의 힘을 두려워하고 있습니다."
rows["158:1940557659"]="내가 술 마실 때 수백개의 병을 깨고 있었겠죠. 잔은 너무 부서지기 어려웠어요."
rows["158:1982432318"]="경비원, 서둘러 나가자! 신타르, 다음 위치로 가는 게이트를 잘라내라. 우리는 작은 포병을 떠나서 북서쪽으로 가려고 합니다."
rows["158:2004155859"]="이 탈북자들의 행동은 우리 모두를 부끄럽게 합니다. 이 수치심은 너무나 강력해서 이해되기 위해서는 목격해야 합니다. 이 때문에 우거도르가 여기 있습니다."
rows["158:2030589512"]="무세크 영들의 방법을 연구하러 왔어요 야생 마술이죠 부두술사 우즈리가 저한테 보내서 숲의 작은 생물들과 연습을 시작하도록"
rows["158:2070349193"]="우리는 어서 가서 다른 신도들과 합류해야 한다. 다시 한번 불모의 땅에 대한 회복을 시도하려면 그 전에 많은 준비가 필요하다. 살펴 가거라, 용맹한 이들이여!"
rows["158:2072774116"]="눈은 무서운, 똑똑하고, 전능하고, 증오로 가득하며, 칼을 휘두르는 얼굴, 굴욕과 날개를 돌리는 모든 곳에 있고,"
rows["158:215317122"]="내 망명한 바보들은 오래전부터 죽었으니 날개를 들고 새로운 모습을 살펴볼께요"
rows["158:246647681"]="분석 완료. 행성 생명 유지 시스템이 부분적으로 손상되었을 뿐 아니라, 행성 수호 장치 대부분이 완전히 손상됐다."
rows["158:280544705"]="어쩌면, 하지만 우리 스스로 이름을 만들 수 있는 기회로 아제로스,  ⁇ 의 살인자 스컬지!"
rows["158:282145432"]="힐다가 모든 서류를 내게 남겼어요. 우리가 발견한 유물들 중 하나라도 위해, 제가 채울 수 있는 6개의 양식이 있다고 알고 있어요."
rows["158:327370516"]="전하가 사라질 때까지 다시 사용할 수 없습니다."
rows["158:331563071"]="당신 의 힘 이 무엇 에서 나온다? 대답 하기 전 에 신중 하게 생각 하십시오. 많은 모험가 들 은 자신 들 의 무기, 장비, 혹은 신비 한 힘 을 가리키고 있습니다."
rows["158:385545772"]="공기의 영들은 지하에서도 발견될 수 있습니다. 그들은 지구에 둘러싸여 있고,"
rows["158:397745374"]="도망치는 것은 지금 내가 하고 싶은 선택이 아닙니다. 우리는 다른 방법을 찾을 것입니다. 아마도 울두르에서 이 태블릿은 우리의 상황을 조금 밝혀 줄 것입니다."
rows["158:398642464"]="소환 주문이 준비됐지만 나즈샤린의 십자가에 의존해서 힘을 끌어내야 해"
rows["158:416381794"]="또한 작전을 위한 공군 지원을 확보하고 곧 배치될 준비가 되어 있습니다."
rows["158:423482476"]="끔찍한 사업!$b$b끔찍한 울음소리가 그 지역을 거쳐 울려 퍼져나갔다.$b$b가난한 놈...$b$b미안해, 술 좀 마실 필요 있어요"
rows["158:423979692"]="라슬로 크루시코그가 사라졌어요. 아이언포지의 사람들은 오늘 한 목소리로 이야기합니다."
rows["158:442079655"]="곧 젊은 여러분, 곧 호드의 군대가 도착할 것입니다. 우리는 행진합니다. 저주받은 문으로 행진하고 우리의 길을 모든 것을 꺾습니다. 그들이 칼림도어의 힘을 느낄 수 있도록!"
rows["158:456442732"]="그는 지구 반지의 가장 강력한 샤만이었는데, 그 ceremony는 그를 없이는 계속될 수 없습니다."
rows["158:464133627"]="시장에 갔어요. 공식적인 티러의 노동조합 사업은 하프힐 마켓에서 찾아주세요. 그렇지 않으면,  ⁇ - ⁇ 가 모든 필요를 처리할 수 있습니다.\010- 하오한 무드클라"
rows["158:526391185"]="걱정 마요 제 그리폰들이 아직 살아있지 않을 수도 있지만, 그들은 여전히 충실히 당신을 목적지로 데려갈 것입니다."
rows["158:527874568"]="그들은 거의 제 동생 로크세이를 이 모임에 보내버렸어요. 그는 개들을 돌볼 수도 없고, 붉은십자군를 능숙하게 대표할 수도 없습니다."
rows["158:537383481"]="이곳은 내가 전체적으로 연구해왔으니 바보 같은 보물 사냥꾼들이 덤벼들어 박물관으로 가져갈 만한 보물을 훔쳐가게 두지는 않을 것이오. 내가 앞장서리다."
rows["158:551477341"]="그냥 다음 모험가가 지나가기를 기다렸다가 저 길로 가라고 말해주자... 그 모험가가 지뢰를 터뜨리고 나면, 우리는 그냥 걸어가서 연장을 집어 오는 거지!"
rows["158:562287432"]="한 곳에서 이렇게 많은 코크론을 본 적 없어!$b$b그 오크들은 거칠고 화난 놈들이야"
rows["158:577453865"]="날 찾아온 건 친절하지만, 넌 내 능력도 넘어서지 실바나 포스트문과 얘기해줘"
rows["158:631407023"]="우리 손으로 이 집을 지었습니다.$B$B믿으세요, 우리는 발가르데에 대한 포부를 포기할 계획이 없습니다."
rows["158:654769668"]="나는 마그하르의 대족장 그롬의 아들 가로쉬 헬스크림이다! 아버지 헬스크림의 전투 함성이 그대들에게 용기와 힘을 줄 것이니! 내 자유의 함성이 그대들을 충만케 할 것이오!"
rows["158:689042453"]="이 문으로 카엘의 군대가 선웰으로 물러나고 있습니다. 그의 일부 랩드그는 여기 남아 있습니다. 레지옹은 그들을 매우..."
rows["158:718049201"]="내 백성의 복수, 우리 땅을 덮친 재앙을 없애기 위해... 호드."
rows["158:784808622"]="모두 함께 일하면서 얼마나 쉬운 일이었는지 보세요."
rows["158:939689455"]="블러드하프 장군, 이 말은 이상하게 들릴 수도 있지만, 젊은 보드가 좀 당황해"
rows["158:957581113"]="오늘 내가 본 전투는 토너먼트에 참가하는 마스터들보다 미미한 것이지만 확실히 효과적이죠"
rows["158:991900468"]="포털은 오래된 사막 유적들을 보여 주죠. 바람이 올라오고, 모래 폭풍이 내면 부어오고 있습니다. 이 포털은 중요한 곳으로 인도해야 합니다."
rows["159:1025732962"]="$p지금 당장, 당신의 도움에 감사해요. 당신이 원하는 대로 사자의 착륙으로 돌아갈 수 있는 포털이 있습니다."
rows["159:1040102899"]="몇 밤 전 어떤 남자가 공을 던지고 내게 데려오라고 말했다. 나는 그와 같은 짓을 했지만 그의 머리로"
rows["159:1121971187"]="모고의 귀환과 서부에서 온 마티드 무리의 위협이 증가하면서 평소보다 훨씬 많은 훈련자들이 헐벗게 되었습니다."
rows["159:1186202853"]="형제자매들이여! 오늘 밤 우리는 사냥을 한다! 오늘은 마티스라고 하는 블러드 엘프를 심판하는 날이다! 가장 먼저 그를 발견하는 자는 일주일간 엑소다르를 타고 휴가를 즐기게 될 것이다!"
rows["159:1203232332"]="이웃, 뭐 얘기하는 거야?$B$B아빠가 항상 말했듯이, 만약 양파라고 부르면 여전히 분홍색 멜론을 먹으실 겁니다."
rows["159:1222013308"]="이봐, 젤펠린이 바로 데려다 줄 거야 썬더 블러프우릴 괴물으로 만들면 누가 와이버너를 필요로 하는 거야?"
rows["159:1234005198"]="강은 강하지 않고 고귀한 것인데 육체는 강하다 강은 강은 그것을 사용하는 사람에게서 얻는다. 그러나 그것만으로도 충분하다."
rows["159:1239121062"]="저는 농민, 귀족, 상인의 아들, 간부들을 대했습니다. 여러분께 한 가지 지혜를 말씀드리겠습니다."
rows["159:127403897"]="난 그 증오를 일리단과 불타는 군단에게 돌렸지만 그들은 우리를 배신하지 않았어. 우리는 나루의 선택을 받았었지! 우리는 그들을 위해 살았고 그들을 위해 목숨도 바쳤어!"
rows["159:1392097163"]="아무도 날 이길 수 없어요$b$b저는 몇 주 동안 이 섬에 있었고 매일 듀얼을 치고 있었는데 아무도 승리에 가까이 오지 않았습니다.$b$b파다리아가 제공하는 최고의 것?"
rows["159:1434528790"]="많은 독이 있다, 웨이커. 어떤 것은 살아서 끓여줄 수 있고, 일부는 네 고기를 먹어 버릴 수도 있고, 일부는 내면에서 널 찢어놓을 수도 있다.$B$B정말 많은 멋진 품종들이 있습니다."
rows["159:1460215083"]="비행장들을 도와서 지지가 찢어지자 도망친 히포그리프들을 모았습니다. 지금도 우리 새들은 미끄러져 있습니다."
rows["159:1537133469"]="아자몬의 여동생과 관련된 모든 건 오해가 많았어요. 내가 한 게 아니었어요!"
rows["159:1583779661"]="오누누는 자유클을 도전하고 순위에 올라가고 있습니다.$B$B그리고 오누누스가 발하라스에서 싸우고 승리하면 오누누스는 리치 왕에 일하게 될 거야!"
rows["159:1588145136"]="건조한 농작물은 물을 필요로 합니다!$B$B이제 스프링클러가 있어서 쉽게 처리할 수 있어야 합니다."
rows["159:1591689478"]="에메랄드 드림은 위험한 장소가 되었습니다. 저는 아제로스에서 깨어 있는 삶을 희생한 사람들을 위해 점점 더 걱정됩니다."
rows["159:1606096591"]="보통은 조용한 곳인데, 가끔씩 사우로크 사냥꾼들이만 문제가 되고, 그리고 사우로크는 폭풍이 강하더라도 나오죠."
rows["159:162066436"]="린은 화가 났어요. 지야는 그의 좋은 친구였는데, 우리는 전투에서 그를 잃었습니다. \010린이 무례하게 행동하길 원하지 않아 내가 그를 잃으면 어떻게 하겠는지 모르겠어"
rows["159:1621582389"]="오크들은 우리 가 가져오는 물건을 보호하려고 해왔을 때 내 아내를 물 속으로 던져버렸어 스톰윈드이럴 수 없어!"
rows["159:1659738067"]="네, 친구, 내가  ⁇ 마리 지도를 찾아볼게."
rows["159:1718966887"]="그는 살아있어요, 그리고 그는 외로처럼 살고 있습니다 레이크샤이어 지난 5개월 동안, 아니면 알아차리지 않았나요?"
rows["159:1763557118"]="현재 수업 전문성을 한 가격에 배워서 새로운 것을 선택할 수 있습니다.\010이렇게 하면 추가로 더 비싸게 될 것입니다."
rows["159:1787433851"]="여기 조용히 손녀를 기다리는 할머니가 계십니다... 백발이 성성한 이 숙녀분을 두려워할 이는 아무도 없겠죠!"
rows["159:1837068015"]="까마귀는 준비가 덜 된 상태로 너무 높이 날다가 다시 떨어졌다. 비상할 때를 위해 영겁의 시간은 암흑의 감시자를 준비했다. 지평선 너머 어둠의 망토를 드리우고자..."
rows["159:1888470345"]="이 포털은 먼 타나리스에서 땅 아래 깊은 시간의 동굴로 이어집니다.$B$B하지만 당신이 더 강해질 때까지, 나는 당신이 거기에 여행하지 않을 것을 요청해야합니다."
rows["159:1894848545"]="데리롬은 살아있어요! 아라코아가 앞뒤로 걸어가고 있는 것을 알 수 있습니다. 계속해서 똑같은 질문을 던지고 있습니다. 또 다른 오크카도 있습니다."
rows["159:1924506049"]="다거가 살아있어요! 아라코아가 앞뒤로 걸어가고 있는 것을 알 수 있습니다. 반복해서 똑같은 질문을 던지고 있습니다. 또 다른 사람이 있습니다."
rows["159:1943245149"]="어제 현지 조사에서 마르두크가 보여 줬듯이 용은 죽은 지 얼마 되지 않은 인간의 고기도 먹긴 하지만 그 인간이 천천히 그리고 고통스럽게 죽은 경우에만 그 고기를 먹는다."
rows["159:207581004"]="파다렌 건설 현장의 폭발조각에 있는 액체 불을 이용해 발전을 촉진하세요! $B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t"
rows["159:2111313592"]="우리는 문명이라고 부르는 것에서 꽤 멀리 떨어져 있습니다. 적어도 호드가 더 많은 보대를 보내기 전까지는요."
rows["159:2122537063"]="길 잃은 형제여, 우리는 당신을 도우려고 왔습니다. 당신의 목숨을 거두기 전에 회개할 기회를 주는 것이 관례입니다. 나루의 명령에 따라 당신에게 회개할 기회를 드리겠습니다."
rows["159:220139768"]="난 네 무기를 내 특별한 혼합물로 덮어놨어, 웨이커 넌 모든 시체를 유동균으로 감염시킬거야"
rows["159:263911913"]="신생 식물 전문가가 되니까 피로드렌 문칼러와 함께 템플 가든에 가 봐"
rows["159:280840685"]="우리들의 계속적인 묘지와 아래 마을에 대한 침략은 이미 결실을 맺고 있습니다. 모가나 잔다라리도 반격을 할 수 없을 것입니다."
rows["159:28608841"]="고문으로 죽으면 우리는 다른 사람을 납치할 것이고, 너희 중 한 명은 고통 속에서 깨어나서 필요한 정보를 줄 것입니다."
rows["159:364532345"]="티리온의 성지위에 자랑하는 것에 너무 쉽게 속아져서 당신은 항상 겁쟁이였어"
rows["159:387386332"]="어떤 먹이를 쓰는지 알고 있었지?$b$b우린 그를 노들러라고 불렀어$b$b소문이 나고 남쪽으로 갔다고 합니다."
rows["159:407315781"]="다른 여러 조각의 문장에서 한 표지가 돋보이는데, 이 포스터에 붙여진 표지판은 뼈 폐기물의 뼈를 깎아내는 사람들을 죽이는 데 대한 요청입니다."
rows["159:408845651"]="|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:109807|h[Arcane Destruction]|h|r! 그녀를 막기 위해 기둥을 활성화하십시오!"
rows["159:414705960"]="최근까지 이 지역의 모고들은 숲 속의 여행자들을 기망하는 것에만 만족했습니다. 이 습격은 다른 것이었습니다. 그들은 조직적이었습니다."
rows["159:432101057"]="인간과 동맹을 벗겨낼 수 없는 것은 너무 아쉽지만, 그 피부는 낭비될 겁니다."
rows["159:456049130"]="10분 후 위커먼 축제가 시작됩니다! 할лоу의 끝과 스컬지에서 해방을 축하하기 위해 로데론 궁전의 유적에 우리와 함께하세요!"
rows["159:503545330"]="츠즈와 장난을 치는 거야? 상관없어... 에테리온이 여기 있어, 우린 난민 캠프에 몰려들게."
rows["159:591149677"]="리치 왕은 대영주님의 한도가 무엇인지 압니다. 부하를 향해 발포할 수 없는 분임을 알지요. 이해가 안 가십니까? 리치 왕에게는 한도가 없습니다. 어떤 것에도 구속받지 않는단 말입니다."
rows["159:616349991"]="연구 완료, 잘 싸웠어요. 본부는 우리의 측정에 대해 쏟아져 내리고, 행운을 빌어 바시어의 의도를 밝혀낼 것입니다. 이제 하늘로!"
rows["159:642526754"]="난 그 애완동물을 좋아하지 않았어. 게다가 사람들은 항상 와서 반려동물을 내게 주거든 내가 한 마리 잃으면 상관없어, 나는 더 많은 것을 잃을거야!"
rows["159:666921984"]="그리모테마는 우리를 마지막으로 공격했고, 그들의 잘못된 길을 가르칠 수 없기 때문에, 우리는 그들을 짐승처럼 파괴할 것입니다.$B$B지구 어머니께서 우리를 용서해 주시옵소서"
rows["159:858742767"]="보존 방을 개발하면서 주의 깊게 기록한 덕분에 코보크를 여기도 보존할 수 있는 수정된 버전을 만들 수 있었습니다."
rows["159:894910192"]="당신은 오직 이토록 오랫동안 신의 고통 뒤에 숨어 있을 수 있습니다. 호드."
rows["159:895259111"]="아르타이드, 우리의 안정적인 마스터는 보호 센터 밖에서 발견할 수 있습니다. 그는 Exodar의 주요 입구 근처의 중앙 허브의 상단 수준에 위치하고 있습니다."
rows["159:908886678"]="그리고 영웅들이여... 내게 그대들이 찾고 있는 것이 있다. 다시 한번 아제로스에서 악마가 사라지는 모습을 볼 수 있기를... 레물로스, 우리의 용사에게 녹색용군단의 파편을 건네 주도록 하라."
rows["159:934154462"]="내가 여기 있는 모든 곳에서 술을 마시고 있어요."
rows["159:96516948"]="마그니 형님께서 이곳 노스렌드에 와 계십니다. 형님을 찾으려고 말이죠. 윈터가드에 있는 현자가 말하길 형님께서 돌아가지 않으셨다고 했다더군요. 그래서 마그니 형님께서는 즉시 아이언포지를 떠나 형님을 찾으러 오셨답니다."
rows["15:1001936783"]="아, 여기 하나 있어요."
rows["15:1005654071"]="집중해야 해"
rows["15:1011328498"]="넌 영웅이야"
rows["15:1011748283"]="늑대가 우는 거야?"
rows["15:1014136518"]="우두이 사라졌어!"
rows["15:1020231876"]="우리는 인내해야 합니다."
rows["15:1024962596"]="예,  ⁇ 기자!!"
rows["15:102946782"]="오, 예, 예"
rows["15:1033867522"]="길을 떠나!"
rows["15:1035511638"]="세계 평화!"
rows["15:1036263180"]="호드에 대한!!"
rows["15:1042148476"]="적의 시야!"
rows["15:104282761"]="제국으로!"
