rows["160:1047080999"]="우리가 티탄을 가장 절실히 찾는 이때 그들은 어디에 있는가? 우리의 여인들은 두 발로 혼자 설 수조차 없는, 꼴사나운 기형아들을 낳고 있다. 약하고, 추하고... 쓸모없는 것들을..."
rows["160:1086041402"]="에라카 노 킴볼$B호랑이의 신, 짐승의 신, 고양이들의 왕, 먹이의 운명$B$B무헤자라가 없으니$B죽음의 신, 수면의 아버지, 시간의 아들, 밤의 친구."
rows["160:1137875610"]="아서스 메네실 왕자, 오늘 엄청난 암흑이 네 영혼을 사로잡았다. 네가 다른 이에게 안겨주려고 했던 죽음은, 오늘 널 찾아올 것이다."
rows["160:1142654585"]="길, 내 제안을 더 생각해봐요? 난 많은 피부와 고기를 가지고"
rows["160:1147690809"]="너무 많은 관심을 끌지 말고, 저는 협의회가 관객을 허락하기를 기다리고 있습니다."
rows["160:1165867192"]="군대를 준비해 주세요. 길네아스 해방 전선은 그레이먼 장벽에 모여 있습니다. 곧 스톰윈드의 보강이 도착할 것입니다."
rows["160:1203983158"]="그 숨겨진 곡물 상자를 찾아서 아카네 디스터퍼를 써라!$B$B아타스는 스트라톨메의 학살을 시작하기 위해 필요한 증거를 갖게 될 것입니다."
rows["160:1267952247"]="기억이 안 나지만 중요한 건 알 수 있는 느낌은 느껴졌어?"
rows["160:1314712837"]="마음 굳게 먹고 정신 차려라. 땅에서 발을 뗄 수 없는 노예가 된 이들의 약한 마음을 어둠의 날개들이 교란하여 갉아먹을 것이니라."
rows["160:1320743406"]="우리는 끔찍한 비극을 목격했다. 선한 이의 피가 이 땅을 적셨다! 명예로운 기사들이 죽어갔다. 자신을, 우리를 지키기 위해..."
rows["160:1353071578"]="당신의 강철은 강하고, 당신의 능력은 더 강해 내 친구 샤이스 스틸푸리에게 당신의 강철과 힘을 가져가라"
rows["160:1359207601"]="\"그라는 번개로 짐승 을 겁나게 하고 농민 의 마음 을 공포 로 가득 차 줍니까, 번개가 내 소식 을 전하리니, 내 힘 이 온 땅 에 퍼져 나리라\"."
rows["160:1419048817"]="도시의 마지 및 포털 트레이너는 동 달라란의 큰 건물에서 도시 중심부에서 루네비버 광장과 크라스스의 상륙 사이에 발견 될 수 있습니다."
rows["160:1419478860"]="이번 휴가철에 포장용 종이를 준비하는 것을 잊지 마세요. 친구나 가족에게 포장된 갑옷과 무기만큼 \"이상한 겨울 베일\"이 없습니다."
rows["160:144667014"]="|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[불명예]|h|r 에너지 회전선에서 꺼내야"
rows["160:1446950370"]="울두아르에서 벌이는 우리 일을 바위 거인들이 방해하면, 너와 네 영주에게 책임을 묻겠다. 필멸의 존재들이 거인을 도우러 오게 놔둬서는 안 된다."
rows["160:1450319248"]="마그니 형님께서 이곳 노스렌드에 와 계십니다. 형님을 찾으려고 말이죠. 윈터가드에 있는 현자가 말하길 형님께서 돌아가지 않으셨다고 했다더군요. 그래서 마그니 형님께서는 즉시 아이언포지를 떠나 형님을 찾으러 오셨답니다."
rows["160:1474301675"]="|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|t슬라브 마스터 히티스는 |cFFFF0000|Hspell:127414|h[프라이머컬 호출]|h|r로 동맹의 힘을 증가시킵니다!"
rows["160:151008691"]="드루이드 트레이너를 찾고 있다면 공원에서 갈 수 있습니다. 테리단과 말드린은 보통 현의 중심에 있는 달수에서 찾을 수 있습니다."
rows["160:1533723964"]="그 애를 드라노쉬라고 이름 지었었다. 오크 말로 \"드레노어의 심장\"이라는 뜻이지. 흑마법사들이 그 애를 데려가게 두지는 않았다. 가라다르의 장로들이 숨겼으니 안전할 터였지."
rows["160:1611757069"]="운이 어떻게 이렇게 웃는 거야? \010어느 날 이 모든 것만으로 만족할 수 있다고 생각했을 때 정말 운이 좋았어요!"
rows["160:1642372846"]="한 약물의 성분 에 대한 작은 변화 가 가라도 근본적으로 그 성분을 변화 시킬 수 있습니다."
rows["160:1681225497"]="탐험가들의 리그의 일원이면서 이 지역에서 유물을 찾아왔어요. 윈터스프링에는 마법 같은 물건들이 많이 들어있다고 합니다."
rows["160:169209616"]="\"호튼, 왜 배를 타고 강을 따라가나?\" 라고 물으면 \"왜 안 돼?\""
rows["160:1759995815"]="기계가 당신을 마주하게 됩니다.$B$B기계 뒷면에 빈, 이상하게 변형된 슬롯이 있습니다. 그레이브레이션이 있습니다. \"Propirtee o'Cap'n Gelkak Gyromast\""
rows["160:1764534481"]="물론, 난 이 단순한 기계를 쉽게 피할 수 있겠지만, 너무 바쁘다."
rows["160:1825326775"]="만약 당신이 가죽으로 꿰매는데 관심이 있다면, 당신은 확실히 올바른 장소에 왔습니다. 패드론과 테론이 진정한 예술가들이며, 저는 그들로부터 많은 것을 배울 수 있기를 바랍니다."
rows["160:1835755223"]="미친 열렬한 사람들의 마지막 성지입니다. '그곳에서 그들은 그들의 적색 유니폼을 만들어, 마법의 적색 끈에 의해  ⁇ 어!$B$B스트라톨메, 모험가!"
rows["160:1836092642"]="브루페스트는 첫 해부터 몇 가지 변화를 겪었습니다. 이제 우리는 티켓 대신 브루페스트 토큰을 발행합니다. 만약 오래된 티켓이 있다면, 저는 그들을 교환할 수 있습니다."
rows["160:1929028289"]="내 동생은 수년간 독성성 곤충의 치료법을 연구해왔고, 그의 메모를 사용하여 저는 침으로 전락한 곤충을 회복하는 과정을 완성했다고 생각합니다."
rows["160:2034000476"]="음모가 많아요. 제가 하는 일을 이해하는데 시각이 부족한 사람들이 있고, 저를 어둠 속에 묶여 두려고 노력하는 사람들이 있습니다.$B$B흙에 발을 내리지 마"
rows["160:2102786088"]="난 당신과 함께 발로 가서 불길을 비켜버리겠다."
rows["160:215174185"]="여자들이 무죄로 숲을 지나가면서,  ⁇ 은 피닉스가 그녀를 사냥꾼으로 쫓아다니고 있습니다."
rows["160:234357375"]="좋아요, 여러분 한번만 해보세요 37066 이 기간 동안, 시간을 채우기 위해 우리와 함께 춤을 추도록 초대합니다."
rows["160:290788304"]="유적들이 있는 곳으로 안내하겠다 하지만 당신은 내 영혼을 잘 지켜야 한다 수호자 유적들 중 유일하게 내가 그 유적들의 봉기를 깨고"
rows["160:310275853"]="정령들이여, 내게 힘을 주소서! 이 오랜 상처로부터 내 영혼을 가져가 모든 이들이 볼 수 있도록 해주소서! 헬스크림의 아들이 자신의 아버지에 대해 알 수 있게 해주소서! 온 백성에게 누가 자신들을 구원해 줬는지 알게 해주소서!"
rows["160:342886644"]="이 두 멍청이들은 \"샤킹\"이라는 패드에 빠져있어요$B$B몇 달 후에 그 사진에 대해 멍청하게 생각하겠지"
rows["160:384938030"]="조용해, 내 사랑, 마음을 진정해 넌 의무의 노예가 됐어"
rows["160:422548618"]="힘겨워$b$b잔인하게$b$b먹을 수 있는 것보다 더 많은 것을 죽여라$b$b친구도 없고 반려동물도 없지$b$b싸우면서 죽게$b$b이 과 많은 것 들 은 크로시크 로부터 배울 수 있는 교훈 이다."
rows["160:472679016"]="크리스탈 홀에 수 많은 샤만 트레이너들을 찾아볼 수 있어."
rows["160:492880879"]="그는 말퓨리온 님의 현신을 파괴하고자 수단과 방법을 가리지 않을 것이다. 그것만은 결단코 막아야 한다... 우린 티란데 님께서 도착할 때까지 그 괴물을 붙잡고 시간을 끌어야 한다."
rows["160:544714060"]="여기로 오기 위해 발목을 왜곡하지 않았다면, 내 친구들과 함께 있을 거야."
rows["160:567312737"]="암초 옥토피는 여기쯤에 있는 것 같아요. $b$b벤은 네 지도에 제이드 숲의 동북해안에서  ⁇ 을 넣고 있어$b$b"
rows["160:576749667"]="이 이더리얼 기술을 믿을 수 있나요?$B$B내가 그들과 함께 있을 수 있게 해줘서 다행이야, 많은 걸 배울 거야"
rows["160:600913988"]="낯선 사람들과 얘기하지 않았지만 그들의 챔피언이 파멸 깊은 곳으로 발을 들여놓고 무사히 돌아왔다는 것을 목격했습니다."
rows["160:614621021"]="아직 때가 아닙니다, 락스베인 양. 때가 되면 모든 것이 밝혀질 것입니다. 주인님께서는 아직도 혼란스러워 하고 계십니다. 노즈도르무 혈족이 이 땅에 돌아왔는지 하늘을 보십시오.."
rows["160:618286489"]="그의 정신을 굴복시키는 일은 꽤 힘들었다. 그 영혼을 잔인하게 괴롭혔지... 오랫동안 저항했지만, 머지않아 자신이 섬길 왕 앞에 무릎 꿇고 말리라."
rows["160:623743429"]="제가 보기엔 당신이 빨리 배울 수 있을 겁니다. 그건 저에게 좋죠. 요즘은 항상 바쁘거든요. 사실, 그것은 제게 상기시켜줍니다."
rows["160:639965336"]="추적용 지옥사냥개 장비를 열고 사용 설명서를 읽어봐야 할 걸세. 여기서 남쪽에 있는 절벽거인의 반도가 가까워지면 그 야수를 소환하게나."
rows["160:641336587"]="샤 공격이 시작되었을 때, 제 학생들 모두가 주저없이 전투에 달려갔습니다.$B$B저는 그들에게 많은 것을 가르쳐 왔지만, 그들은 여전히 내 기대를 뛰어넘습니다."
rows["160:693824874"]="너무 오랫동안 자리를 비운 모양이군... 내가 없는 동안 위대한 영웅들이 목숨을 잃었다. 네놈이나 이 사악한 마녀같은 쓰레기가 아무런 제재도 없이 활개를 치고 다니다니..."
rows["160:714647368"]="|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|t가라'잘은 영토템을 불러오. 그것을 |cFFFF0000|Hspell:116260|h|h|r로 영세계에 사용하십시오!"
rows["160:734725399"]="내가 마찰을 활성화하는 동안 내 등을 지켜봐요. 모든 용들이 타이탄들의 언어를 타고난 것으로 알고 있다는 것을 아십니까?"
rows["160:783687844"]="우리가 퍼뜨리는 이 특별한 전염병은 고드프리의 군대가 기지를 떠나지 못하도록 해 주지만, 여전히 우리 군대를 이동시켜 포세이큰를 위해 그것을 가져갈 수 있게 해 줄 것입니다!"
rows["160:792052398"]="포스팅의 세부 사항은 거대한 늑대의 처형을 요구합니다. 호드 요새"
rows["160:800158737"]="난 그에게 지옥의 잔소리가 우리를 배신하고, 자기 백성에 대한 책임감을 버리고 말았지만 나즈그림은 너무 충성스럽고 자랑스럽다"
rows["160:806265840"]="여러 가지 잎 과 가지 는 이 물체 에 붙어 있으며, 이 물체 는 어떤 생물 의 둥지 의 일부 로 사용 된 것 을 알려 준다. 그렇지 않으면 별 일 이 없다."
rows["160:829484120"]="인테리전 정보원들은 윈터엑스 트롤들이 갓빈 엔지니어들을 포로로 잡았다고 보고했습니다"
rows["160:832631260"]="이 포스터에 금을 제안하고 있다고 써있어요."
rows["160:847085502"]="내가 걱정하는 건 그가 아니라 여기 온 신생들이랑 그들이 가져온 끔찍한 보라색 엘프들 뿐\010"
rows["160:86361865"]="스틸그릴의 브론크 매장에 가서 보시면 되요. 그가 이상한 기기를 만들지 않을 때, 그는 보통 조종사들에게 그들의 증기 탱크에 대해 이야기합니다."
rows["160:863964761"]="|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|t가라'잘은 영토템을 불러오. 그것을 |cFFFF0000|Hspell:116161|h|h|r로 영세계에 사용하십시오!"
rows["160:877902980"]="그는 자신을 털 바론이라고 부르고 난 그를 바보라고 부르며, 쥐 털로 만든 새색 동계 주머니를 얻는데,"
rows["160:901187592"]="<리드로는 그의 옷으로 손을 뻗어, 무겁고 평평한 엘프 칼을 제시한다.>$B$B옛날 시대, 고대 전쟁 이전에도 이 칼이 있었다."
rows["160:919043769"]="솔직히 말해서, 처음에는 발드린 의 비전 들 이 진실 한 것 이라고 믿지 않았습니다. 하지만 이 곳 은 특이한 마법 을 전파 합니다."
rows["160:93238991"]="너희가 보는 이 세상들은 이미 심판을 받았으니 그들은 멸망할 것이며"
rows["160:943939515"]="한 가지 다르나서스'하이번'은 아카인 리포저로, 에크소다르의 마법사와 함께 일하고 있습니다."
rows["160:958013262"]="볼진이 그가 돌아오기 전까지 계속 드럼을 치라고 했지$B$B여기 기다려 음악을 즐기세요!"
rows["160:967972960"]="내가 도와줄 수 있는 몇 가지 기본적인 것들을 배워야 합니다. 제 연습생인 Vhan에게 말해주세요. 그는 친절하고 인내심이 있고, 당신이 알아야 할 것을 가르쳐 줄 것입니다."
rows["161:1040792610"]="당신은 우리의 글로벌 방어력을 낮추고, 이견적인 판사와 열풍으로 고통받는 험담한 군대를 진정시키려고 합니다."
rows["161:1072773428"]="밴시 여왕이여, 모르겠네. 어쩌면 스컬지가 아제로스를 쓸어 버리지 않는 유일한 이유는 리치 왕 안에 아서스의 일부가 남아서 그들을 막기 때문이 아닌가 하네."
rows["161:1104769530"]="미안하지만, 당신은 팩 코도의 넓은 측면을 쏠 수 있는 것 같지 않아요.$B$B우리끼리 시간을 낭비하지 말고, 당신은 올바른 트레이너를 찾아가"
rows["161:1169947224"]="영원히 입을 다물지 않을 놈이라고 생각했다. 마침내 그 입을 신드라고사가 막았구나. 영웅들이여, 투영의 전당으로 향하라! 목표가 가까이 있음이... 느껴진다."
rows["161:1304701793"]="시그리드 아이스본이 북서쪽에서 다가오는 것을 들어요."
rows["161:1331682905"]="마지막 총이 발사될 때까지 거리에서 싸워서 탄약이 없어지면 도시를 포장하는 돌로 그들의 두개골을 꺾어 버릴 거야"
rows["161:1351630619"]="여러분의 의심과 증오가 이 모든 유적들을 파괴했습니다."
rows["161:1356705964"]="형제자매들이여, 잘 들으시오. 우리 종족의 생존에 대해서 논해 봅시다. 지난번 재앙에서는 가까스로 살아남았을지 몰라도 다음엔 우리 모두 멸망할까 두렵습니다."
rows["161:1408052991"]="이 조각을 마이너우에 넣고 마이너우를 해수욕장 어딘가에 남기고 동부 왕국들 사이에 놓았는데"
rows["161:1432506357"]="\" ⁇  스톰스타우트\" 우리 모두 영웅이 될 수 없어 책임에서 도망치고,"
rows["161:1435876824"]="무라딘아, 너를 다시 보게 되다니 정말 기쁘구나. 그리고 네가 거느린 무리의 왕이 되었다는 게 무슨 소리냐? 브론즈비어드 가문은 항상 왕가의 혈통이 될 운명을 타고 났지 않니."
rows["161:1474787291"]="너희 행동은 비논리적이다. 이 전투에서 가능한 결말은 모두 계산되었다. 결과와 상관없이 판테온은 관찰자의 전갈을 받을 것이다."
rows["161:1480924044"]="피바람을 불러 일으키자! 호드의 용사들이여! 쓰러진 형제자매를 위해 싸우리라! 슬퍼할 필요는 없다! 그들은 모두 명예롭게 죽었노라!"
rows["161:1495102244"]="그녀는 Kirin Tor에 새로운 미래를 만들 준비가 되어 있었습니다. 호드 동맹의 Sunreavers와 얼라이언스 측의 은 Covenant이 평화롭게 함께 일할 수 있는 곳이었습니다."
rows["161:1503179706"]="여기서 어디로 갈지는 알 수 없지 영웅이 아니라$B$B에본 블레이드의 기사들은 당신을 환영합니다."
rows["161:1512177409"]="이 항구에서 테라모어로 가는 길을 찾을 수 있습니다. 제 말들을 들어보세요. 그 땅은 얼라이언스 주민들이 여행하기 위해 거의 안전하지 않습니다. 발걸음과 등을 조심하세요."
rows["161:153478940"]="비행장님은 주 테라스에 위치하고 있습니다. 두 계단 꼭대기에 위치하고 있습니다. 그리고 당신은 주요 건물에 들어가기 전에요.$B$B지도에 위치를 표시해 줄게요"
rows["161:15354553"]="록타르 오가르! 승리가 아니면 죽음뿐! 바로 우리를 호드로서 묶어주는 말이다. 호드의 모든 용사들에게 있어 가장 신성하고 중요한 믿음이기 때문이다."
rows["161:1591065575"]="무장공작의 능력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면 무장공작이 만들어야 하는 모든 레시피를 잊어버릴 것입니다!"
rows["161:1753559758"]="알도르와 스크라이어스의 세력은 아카마와 그의 나쁜 형제들이 알아르를 죽인 직후 성곽을 공격했습니다."
rows["161:1783890881"]="크하하하! 이 애처로운 장면은 뭔가? 대체 뭘 기다리는 거지? 음, 배가 고프군. 보아하니 한 끼 식사거리로 충분하겠군!"
rows["161:1800807546"]="더러운 풀은 내가 본 적보다  ⁇ 어있어요"
rows["161:1806653289"]="운 좋은 날인 줄 알라고. 좋아, 말해 주지. 그러니 날 제발 좀 내버려둬. 이봐, 내 말이 믿기지 않겠지만, 그건... 으, 젠장, 할란이 쏜 게... 윽..."
rows["161:1822930697"]="자이드 숲의 그린스톤 광산에 있는 광부들이 있습니다. 그들은 아마도 당신의 기술을 향상시킬 수 있을 것입니다."
rows["161:1847296205"]="쯧쯧... 이봐요. 나오하인. 왜 모도루는 아직도 저 우스꽝스러운 로브를 입고 있는 걸까요? 이세계에서 암멘 골짜기에 도착해 밖으로 기어나온 지 여섯 시간도 채 안 된 시골뜨기처럼 보이잖아요."
rows["161:1875139938"]="내가 당신을 위해 한 번 더 감사하고 싶었어요. 당신이 내게 용기를 줬어요. 숲의 짐승으로부터 내 집을 되찾으려요. 그렇게 함으로써, 저는 마그윈을 찾았습니다."
rows["161:2012065533"]="그 녹색 쓰레기통은 남해안의 너희 집을 괴롭혔고 레드리지에 있는 너희 아이들을 포위했고 테라모어에서 모든 남자와 여자와 아이를 학살했다."
rows["161:204803052"]="내가 그들을 찾았어요. 왕에게 그들이 위협이 된다는 걸 보여주려고 했거든요."
rows["161:2092706940"]="검수술 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면, 당신은 검수술 을 만들어 내기 위해 필요한 모든 요리법을 잊을 것입니다!"
rows["161:2137541747"]="리시애나는 적절한 서류를 제공할 수 있고, 동북부 공예인 테라스에서 거주하고 있습니다. 다르나서스여러분의 동정심이 밤 엘프들에게 영광을 가져다 줄 수 있기를 바랍니다."
rows["161:270017650"]="탐험 지점은 얼라이언스레지온 전선과 가장 가까운 접촉 지점입니다."
rows["161:336699598"]="빨간 판다에 흥미로운 점이 있는데, 브루마스터 샤도포어의 음료는 맛이 좋도록 어떻게 고쳐야 할지 생각해봤어요."
rows["161:37022984"]="우리들 중 가장 민첩한 사람은 가끔은 알아보기 힘들지만 그럼에도 불구하고, 당신은 아마도 살인 줄 안에 있는 악당인 셀라니스와 그의 동족들을 만날 것입니다."
rows["161:429207414"]="샌 레드스케일은 클라우드 뱀의 사단장입니다.$B$B제이드 숲의 아보레텀에서 찾을 수 있습니다.$B$B네 지도에 그의 위치를 표시해 줄게"
rows["161:5364476"]="아, 수업을 진행하는 선생님을 찾고 있어요?$B$B고향으로 돌아가서 찾아볼 수 있어요"
rows["161:55245246"]="마지막 전투는 칼림도어 그것은 우리 위에 있나니 권능의 대왕이 칼림도어 군대가 아안키라지에 진출하고 그들의 길을 가는 모든 사람을 파괴하도록 명령한다."
rows["161:578505504"]="난 이 소위 전투자들의 무능한 전투를 연구하고 있어$B$B저는 그들 모두를 능가하고, 그 후에 저는 리치 왕에 봉사하는 데 승격하게 될 것입니다."
rows["161:683774696"]="아나테라... 난 당신 없인 이 영원한 삶을 견뎌낼 수가 없소... 당신이 떠난다면 나도 당신을 따라 흙으로 되돌아 갈 것이오."
rows["161:706054697"]="그리고 이 사건들은 우리 조직의 다른 구성원들에 대한 증오가 분열된 사건들이었습니다."
rows["161:715156065"]="평화에도 여전히 전쟁이 있고 많은 부족들이 여전히 전쟁의 장군의 깃발 아래 싸우고 있습니다. 오그리마?"
rows["161:736699913"]="%s 그녀의 몸이 무너지면서 배내  ⁇ 을 내리는 끔찍한 울음 소리가 블랙록 스파이어의 홀에서 울고 있습니다. 뭔가 매우, 아주 화가 나 있습니다."
rows["161:737467041"]="네 가치를 증명하는 여러 가지 방법 중 가장 간단한 방법을 요구해"
rows["161:819657950"]="필멸의 존재여, 내게서 죽음이 느껴지느냐? 그 죽음은 내가 만지는 모든 것을 덮치지. 손가락만 까딱해도, 네 영혼은 지옥에 떨어져 영원히 괴로움에 몸부림칠 것이다."
rows["161:840534440"]="우린 여전히 앞선 지휘관으로부터 끊어졌지만, 당신들의 협상 덕분에, 우리는 조금만 팔꿈치 기름으로 도로를 다시 열 수 있을 겁니다."
rows["161:861880758"]="이 길을 걷고 싶지 않아, 정신이 불안해해\010고대 유물에 대해 조금이라도 알고 있다면 그들을 안고 싶은 방법을 찾을 수 있을 겁니다."
rows["161:877875907"]="|TInterface\\Icons\\inv_misc_blackironbomb.blp:20|t 이 |cFFdd7400시크'티크 암버윙|r 위치로 이동하여 |cFFFF0000|Hspell:120559|h[폭탄]|h|r 플랫폼!"
rows["161:895404081"]="엘드린은 유일한 엘윈 숲 이스트벨 목재 캠프에서 찾을 수 있습니다."
rows["161:904749560"]="우리는 강력한 힘을 모아서 테르말플러그의 장군들을 물리쳤고, 도시로 진입하는 데에 맞서 싸웠지만,"
rows["161:965093664"]="나랑 같이 해봐 영웅, 다시 밸리로 가자. 이 사건의 전환에 특히 관심이 있는 사람이 있다고 생각합니다."
rows["162:1024612580"]="그 브램블스타프 소년이 야생에서 덤프하저 피난처의 타우런들과 동행하고 있어$b$b- 같이 갈래?"
rows["162:1031763650"]="됐어, 됐어. 세상 깊숙한 곳을 다듬게 하려고 창조주가 돌로 토석인을 만들었지? 그런데 부작용은 왜 생겼나? 모형 불안정화 어쩌고 하는 얘기 있잖나."
rows["162:1072396275"]="육상에서 달리는 짐승을 잘 알고 있는 것처럼 보이지만, 날려나려면 훈련과 헌신이 필요해"
rows["162:108921642"]="내가 그를 제 왕의 명령에 따라 처형하고, 내 백성에 대한 그의 범죄에 대한 보복으로 죽기 전에 고통스럽게 고통받는 방식으로 그렇게 한다."
rows["162:1184720944"]="고엘, 당신은 계속 워체프와 샤먼의 경계선에 걸을 수 없습니다. 한쪽 쪽으로 완전히 헌신해야 할 시간이 올 것입니다. 그 시간은 빠르게 다가오고 있습니다."
rows["162:121776448"]="명령대로 해라. 듀로 마나괴철로가 마나 생명체의 공격을 받고 있으며 도저히 수습할 수 없는 상황이다. 명령 불복종은 용납하지 않는다!"
rows["162:1232823151"]="도움 감사합니다. 이 메모들은 제 공부에 중요합니다. 여러분의 사람들은 지식도 소중히 여기죠."
rows["162:1250097944"]="바쁜 일이 많고 시간이 너무 부족해$B$B여기 어딘가에 있는 거 알아요, 방금 손가락을 태웠어요!"
rows["162:1263644349"]="이 기회는 얼라이언스 우리는 트롤을 방해로 사용 할 것이고, 얼라이언스 함대 모집, 이해가 되니?"
rows["162:1288652283"]="각오해라. 종은 이미 울렸다! 병자와 노인과 어린 아이들을 숨겨라! 너희 모두 죗값을 치를 테니! 자비를 구해라! 심판의 날이 다가왔다!"
rows["162:1307007981"]="재밌는 건, 내가 돌아온 지금 내 아버지는 그 어느 때보다 행복해졌다고 생각합니다!$b$b어려운 시간 들 은 단순 한 것 을 소중 히 여길 일깨워 준 것 같습니다."
rows["162:1317385754"]="아마 당신은 거주하는 채굴자가 없는 마을을 찾을 수 있다고 생각하지 않았겠죠?"
rows["162:1323479972"]="준비해라, 종이 울렸다! 약한 자와 어린아이, 노인을 숨겨라! 너희 모두 마지막 값을 치르게 될 것이다! 자비를 구하라. 심판이 왔다!"
rows["162:1328320606"]="이놈의 부상은 엄청난 일이었습니다. 그의 영혼에 대한 내가 저지른 잔혹한 행위는... 그는 오랫동안 저항했지만, 곧 왕 앞에 굴복할 것입니다."
rows["162:1345820660"]="상처가 심각하지 않았으면 좋겠어요!$B$B지도에 위치를 표시해 줄게요"
rows["162:1377412160"]="전 어떻게 느꼈는지 믿을 수 없어요\010제이뉴를 지배하는 것과 같은 존재가 저를 사로잡았을 것이라고 생각하면..."
rows["162:1385965385"]="이런 말이 있지요... \"동트기 전이 가장 어둡다.\" 그래도 새벽은 옵니다, 타후. 해는 늘 떠올라요. 조화로움은 반드시 제자리를 찾을 겁니다."
rows["162:1403840143"]="이 마을은 많은 사람들 중 첫 번째가 번개왕에 대항할 것입니다. 이것은 위대한 승리로!"
rows["162:1423142229"]="제국이 성장하면서 모가들은 계곡의 비밀을 실험하기 시작했고, 살아있는 육류와 돌로 끔찍한 무기를 만들었고, 내 사람들은 두려워했습니다."
rows["162:1456467721"]="금으로 남은 물건들을 팔 수 있을지도 몰라요. 우리가 살아남기 위해서는 다른 마을에서 물과 음식을 사야 할 겁니다."
rows["162:1485555265"]="건조한 농작물은 물을 필요로 합니다!$B$B여기 남긴 노년한 물통을 쓸 수 있어"
rows["162:1491815186"]="여러분들께 진심으로 사과하고 싶습니다. 제가 여러분보다 더 부유한 사람이라는 사실에 대해요."
rows["162:1531276953"]="나한테 배울 준비가 되기 전에 더 많은 훈련이 필요해"
rows["162:1573659479"]=" ⁇ 스볼을 뱀에게 던져서 얼마나 오랫동안 공중에 유지할 수 있는지 보자."
rows["162:1587768681"]="네, 스킨링,  ⁇  칼을 쓰는 데는 요언 딥컷보다 더 잘하는 사람이 없다."
rows["162:1589857952"]="내가 거기 없었지만 실버파인에서 시브반스가 죽었다고 들었는데 그녀의 소중한 발키어는 그들의 목숨을 희생해서 그녀를 부활시켰다고"
rows["162:1635876458"]="이 게으른 놈들 중 한 명을 내버려두면 다른 놈들을 꺾고 일하게 될 거야$B$B우린 여기서 일을 해야 돼!"
rows["162:1645403739"]="어떻게 할 수 있을까요? 저는 다양한 것들을 시도했습니다. 나그란드 주민들을 돕기 위해 최선을 다했습니다."
rows["162:1748869126"]="이곳의 진실은 단 두 가지입니다. 첫째, 시간은 무질서하며 끊임없이 흐르고 매우 순응적이다. 둘째, 인지하는 것이 현실은 아니다."
rows["162:1756767756"]="저는 틸러족의 일원입니다. 파다리아의 열심히 일하는 농부들입니다. 우리에 대해 더 알고 싶다면, 우리는 네 바람의 계곡의 하프힐에 위치하고 있습니다."
rows["162:1762260952"]="낯선 자, 당신은 평온한 호수에서 돌이 떨어지는 것을 본 적이 있습니까? 모든 행동이 파동을 일으키고, 심지어 우정의 약속을 받아들이는 것까지요."
rows["162:1826745228"]="스피드바지 공격은 사업적인 오해일 뿐이야 내가 재발되면 피즐과 포지크와 계약을 협상할 수 있어"
rows["162:1834638297"]="루매크는 항상 낚시하는 대신 싸우다 그 명예의 계곡의 호수에서 그를 발견할 거야"
rows["162:1882115577"]="만약 당신이 쉬고 힘을 되찾을 시간이 필요하다면, 당신은 Dolanaar에서 최고의 숙소를 찾을 것입니다."
rows["162:1900206941"]="내 능력은 내 능력도 못해, 낯선 사람. 스톤탈론 산맥의 태양암 피난처에서 Hgarth에게 이야기해봐. 그는 내가 할 수 있는 것보다 더 많은 지식을 제공해 줄 것이다. "
rows["162:1950190639"]="내가 그들을 지켜보고 나의 벌이 있나니 이는 거만한 자들을 물리치며 너희는 내 벌에 대항하여 거만한 것을 거역하려 하느뇨"
rows["162:196579292"]="숫자를 잘 아는 사람이 늘 있어!$B$B내 머릿속에서 얼마나 빨리 덧셈, 빼셈, 분수 방정식을 할 수 있는지 본 후, 그들은 즉시 나를 고용했습니다!"
rows["162:1998925882"]="불타는 군단 때문에 오크들이 드레나이에게 등을 돌렸을 때 이곳에서 가장 격렬한 전투가 벌어졌습니다. 드레나이는 끝까지 싸웠지만 결국 도시는 함락되었죠."
rows["162:2073867265"]="그 브램블스타프 소년은 야생에 있는데, 야생 엘프들과 함께 애기하고 있어$b$b- 같이 갈래?"
rows["162:2132738363"]="로데브다. 역병지대의 살아 있는 역병과 아제로스의 수렁 괴물을 결합시킨 끔찍한 괴물이지. 로데브에게는 치유 그 자체를 좌지우지하는 힘이 있다."
rows["162:303826461"]="호젠도 무술을 배울 수 있어$b$b켄-켄은 다른 놈들보다 더 낫다 특히 똑똑한 아시오, 멍청한 진주보다"
rows["162:305333466"]="이 곳은 폐허만큼 안락한 곳이 아닙니다. 그리고 이 곳의 공기는 약간 습합니다. 제가 직접 말한다면, 하지만 편안하고, 가정적인 느낌을 줍니다.$B$B- 아니, 그렇지?"
rows["162:324068673"]="적색 비행을 통해 자신을 기쁘게 할 기회를 놓칠 수 없다고 생각합니다."
rows["162:476565777"]="호그랄을 찾고 있어? 술집을 확인했어? 오! 만약 당신이 거인, 그리고 그 중 왜성자를 찾고 있다면, 당신은 숙소에서 시작해야 한다!"
rows["162:517478236"]="이번엔 패했지만 실망하지 말고 특수 공격에 집중해 가라"
rows["162:545558909"]="비스턴 핑치위슬, 스팀위들 전투 경주 공식 아레나 판매자"
rows["162:592593454"]="모고들은 엄청난 위협이지만, 저들과 사람들이 공포의 폐허에서 겪은 끔찍한 것에 비해 아무것도 아닙니다."
rows["162:631605677"]="걱정 마요, 조용한 묵상과 함께해 주시기 바랍니다."
rows["162:665289099"]="네가 준비되면 내가 너를 머리 위에 올려놓고 스컬지 당신은 나를 지시해야 해 적들을 파괴하도록!"
rows["162:712932286"]="하지만 마상시합은 다른 방식의 명예로운 전투입니다. 아마도 익숙해지려면 어렵겠지요. 하지만 당신의 무용이라면 오크족이 지닌 힘을 모두에게 보여줄 수 있을 거라 확신합니다."
rows["162:727989688"]="매년 이 시간쯤 시리투스에 가는데 날씨는 제  ⁇ 이기에 환상적입니다.$B$B나랑 산책해봐, 친구, 관광지도 즐기"
rows["162:730732862"]="여기서 대기하라. 내가 먼저 소규모 부대를 이끌고 스트라솔름에 들어가겠다. 로데론의 모든 이를 위해, 감염자를 격리하고 처치해야 한다!"
rows["162:744393457"]="그대에게서 어떤 불안정함이 느껴지는구나. 그들과 한편이건 아니건 나는 그대를 믿을 수 없다. 칼루아크에 대한 내 점괘를 알고 싶다면 먼저 그대 자신을 내게 증명하라."
rows["162:744651970"]="이 마을의 행운을 위해 울고 있습니다. 그들의 힘든 시간은 끝없는 것 같습니다. 그리고 계곡에 있는 모가와 함께, 그들은 아마 어느 때보다 오래 걸릴 것입니다."
rows["162:750934163"]="이 마법의 이미지로도 당신을 감지할 수 있습니다. 쿠루타스가 나타나면 아탈마스 크리스탈을 되찾을 것이라고 생각하시지만, 당신은 틀렸습니다!"
rows["162:769724580"]="시내 최고의 요리사 중 한 명인 실란은 웨이파레어 레스트 타버너에 올라가서"
rows["162:782549702"]="사우르 사제들은 내 약함을 보았고, 짐승들이 날 때려서  ⁇ 어라 부르며, 내가 보호할 바실리스크가 없었다면, 나는 혼자 있었을 것이다.$b$b아마 죽었을 거야"
rows["162:784618383"]="그러나 저는 믿음으로 자신을 위로하기보다는 최전선에 서고 싶어요. 그냥 눌러앉아서 상황이 나아지기를 바라고 있을 수만은 없습니다."
rows["162:83259499"]="보아 밴스 언더글룸은 남동쪽의 갈로우스 엔드 타버너에 상층에 상주 방을 들어갔다고 합니다."
rows["162:881719533"]="그래서 우리가 도착했지. 나와 내 부대는 저 아래 뼈로 덮인 길에서 통상적인 정찰 임무를 수행했지. 우리는 먼저 정찰병을 보내서 위험한 일은 없는지 주변을 살폈소이다."
rows["162:924903427"]="내가 싸움을 운영하고 있어, 만약 당신이 내기를 하고, 자신감 있게 도박을 하고 싶다면,$B$B내가 직접 확인해볼게!"
rows["162:950474418"]="애가마스, 첫 번째 문이 침범됐습니다. 킬제덴의 두 명의 가장 강력한 부교수인 사크로라쉬 여신과 대마술가 알리테스는 공격에 취약합니다."
rows["162:973330081"]="저는 그들의 지도자를 공격할 수 있는 짧은 기회를 얻었고, 그는 어떤 마법으로 보호받았어요."
rows["163:1050645777"]="이 탐험에 부티 베이의 관심을 대변하기 위해 왔어요$b$b상황이 악화되면 부티베이도 곤경에 처해 있을 거야$b$b우리는 여전히 재앙의 사건으로부터 회복하고 있습니다."
rows["163:1066415903"]="우리가 겪은 가장 어려운 전투가 될 것이지만 우리의 결단과 선웰의 힘은 우리가 위대해질 때까지 우리를 지지할 것입니다."
rows["163:1138897581"]="천상의 토너먼트는 다른 경쟁자들과의 반려동물 전투를 통해 당신의 리더십 능력을 시험합니다. 그리고 당신이 충분히 성공한다면, 천상의 자녀들."
rows["163:1165183008"]=" ⁇ 은  ⁇ 이 날려서 눈치채는 걸 봐요, 전 앞의 거대한 마그마 벌레가 방문객들을 억제할까 걱정했어요."
rows["163:1169991358"]="하지만... 그는 당신의 승리를 알게 됐습니다 스톰윈드북부 함대군에 있어 실바나스의 소아적인 반란을 포기할 수 있는 잠재력을 갖고 있다고 생각하죠"
rows["163:1174632006"]="이건 가족 농장이야, 아직 알아보지 않았다면...$b$b하지만 우리는 음식을 즐겨 먹습니다."
rows["163:1198900418"]="아제로스의 죽음 날개의 귀환은 두 세계 사이에 큰 격차를 일으켰습니다. 이 침해는 우리 땅이 파괴될 위협을 받는 재앙의 힘입니다."
rows["163:1245362189"]="저는 방금 그 소식을 들었습니다. 현재 우리는 $2021w 이 중 $2020w 평화의 꽃 $2050w 이 중 $2051w 불꽃과 $2054w 이 중 $2055w 보라색 호두 허브 요청"
rows["163:1249081884"]="아니면, 그들은 우리 대부분을 죽였죠. 저는 마을의 치료가였습니다. 그들이 저를 지나쳤을 때, 저는 제 의학적 능력을 충분히 적용해 살 수 있었습니다."
rows["163:1263925942"]="우리는 자이드 숲에서 당신의 \"지원\"을 목격했습니다. 이 \"호드,\" 이 \"얼라이언스\" - 당신은 자신의 자연에 대한 통제를 할 수 없습니다. 당신은 당신의 발자국 뒤에 불행을 남겨두고 있습니다."
rows["163:1267283131"]="서리요새에 거의 다 왔어요. 떠나시기 전에 스톰하트 왕께 저를 좀 소개해 주시면 정말 고맙겠습니다. 우리 모두 그분께 큰 빚을 졌으니까요."
rows["163:1347334019"]="어떤 드워프가 말이지요, 노움은 원래 땅속에서 태어난 존재라고 주장하는 거 있죠. 모든 노움의 시조는 모래 노움이라나? 말이 되는 소리를 해야지요! 모래 노움? 세상에나!"
rows["163:1356813905"]="더 이상 가르칠 수 없지만 아서 무어와 얘기해 포세이큰 이 사람은 언더시티내가 보낸다고 말해"
rows["163:1443219424"]="우리가 취할 방법에는 두 가지가 있다, 고드프리. 첫 번째 방법은 네가 이 책에 기록된 부정한 문자를 해독해 달라는 내 요청을 들어주기만 하면 된다. 어떻게 하겠나?"
rows["163:1458313855"]="내가 당신에게 제시한 도전을 감당할 준비가 되어 있다고 느끼는가? 귀신이 당신에게 지나갈 것이라고 말하지만,"
rows["163:1493580843"]="기젤톤 대상단을 보호할 경호원을 구합니다! 저희는 코르메크의 오두막에서 동쪽, 콜카르 켄타우로스 마을에서 북쪽에 있는 길가에 서 있습니다."
rows["163:1581512725"]="키린 토르는 이 섬의 힘을 전혀 알지 못해, 그들은 우리를 막기 위해 온 거야."
rows["163:1585258935"]="무기를 만드는 능력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면 당신은 모든 레시피를 잊어버릴 것입니다."
rows["163:1606258975"]="자마야 최고의 요리사가 되세요 오그리마- 아뇨$B$B델밸리의 중심 건물 남쪽에서 찾을 수 있습니다. 배담시는 자마야가 만든 음식을 판매합니다."
rows["163:1619453603"]="난 아이언포지 만약 내가 너희들에게 내 능력을 충분히 가르쳐 줄 수 있다면,"
rows["163:1676566495"]="핵융합핵을 안정적으로 유지하면 거의 모든 계산 능력을 부과할 수 있습니다.$B$B마지막 유지보수 주기에 유동점 오류가 해결되었으면 좋겠습니다."
rows["163:1708925677"]="가장 미친 짓은 내가 얼마나 많은 병을 보관하든, 수량이 늘어나지 않는 것 같아서"
rows["163:1711704545"]="아직 쉬지 못해, 내 딸아. 히알은 여전히 서 있지만, 불의 주님 문턱에 흔들리면, 모든 것이 여전히 사라질 수도 있습니다."
rows["163:1728180844"]="바보야, 내 암흑 샤만은 원자들을 마일이나 뒤집고 고문해 왔어"
rows["163:1799130986"]="저는 무기와 같은  ⁇ 에 배합된 붕대를 보고 있습니다. 제가 여러분들에게 그림자를 위한 대막을 제공했을 때, 햇빛에 사라질 때까지 남겨진 음식들을 분명히 봅니다."
rows["163:189677149"]="이 섬 남쪽 끝 무렵에 동굴이 하나 있다. 숨겨진 동굴이라는 곳이지. 총사령관은 그 안에 숨어 리치 왕과 마지막 결전을 벌일 준비를 하고 있다."
rows["163:1903964427"]="언젠가는 생명이 다할 나약한 존재여, 이 폐허를 더럽히지 말라. <눈부신 빛이 온몸을 둘러쌉니다. 기억나는 것이라고는 온통 화염으로 이루어진 어떤 생명체를 본 것뿐입니다.>"
rows["163:1951038409"]="반려동물 전투는 가장 놀라운 힘입니다 아제로스 하지만 내가 봤어, 아빠의 횡포를 발견한 아이처럼"
rows["163:1970460374"]="네, 실력이 있긴 하지만 내가 가르친 순간마다 죽은자가 고통받는 순간이 더구나"
rows["163:1999518808"]="저놈은 전설의 무기를 만들어서 위대한 영웅들을 위해 특별한 무기를 만들죠"
rows["163:200427051"]=" ⁇  알가스에서 내려오는 길에 호수 한가운데서 트레사돈을 사냥하는 개미를 봤어요."
rows["163:2091936746"]="그렇다. 우리는 그자가 죽었다고 알고 있었지만 실상은 그렇지 않다. 그자는 태양샘을 통해 불타는 군단의 우두머리, 킬제덴을 이 세상으로 불러들이려 한다."
rows["163:2093522295"]="그림자 부부의  ⁇ 툴을 찾고 있어요?"
rows["163:239267420"]="그루이드의 길은 샤만의 형제자매입니다. 제니아 루네토테마는 그러한 지식에 빠져 있습니다. 블러드하프 마을 동쪽에 있는 큰 텐트에서 그녀를 찾아보세요."
rows["163:248868325"]="예전에 참전한 참전용사였어 킬램이 다시 이 일을 할 수 있어"
rows["163:33573424"]="그래요... 보드라시일의 마법은...$B$B제발, 내가 도와줄게 운명이 날 이리로 데려왔어"
rows["163:36270367"]="만약 우리가 Twilight's Hammer가 이런 포털을 모든 곳에 열어주면 아제로스지구를 구할 수 있는 군대가 없습니다."
rows["163:37983559"]="뼈 깎아주는 놈들은 싫어요!$B$B눈이 빠지거나, 가끔씩 아쉬운 마법을 느끼지 않았다면, 저는 항상 저들을 쏴서 있을 겁니다!"
rows["163:404597949"]="흑요암을 만든다는 것은 라그나로스 님의 뜻이었지. 흑요암이 검은바위 첨탑에서 검은바위 오크를 쳐부수면, 우리 동지들은 불타오르는 심연에서 하나가 될 수 있어."
rows["163:416060729"]="아자르 스트롱햄러는 젊은 패러디들에게 한두 가지 보여줄 수 있어"
rows["163:461102344"]="해머스미팅 기술을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면 해머스미싱이 만들어야 하는 모든 레시피를 잊어버릴 것입니다!"
rows["163:513645546"]=" ⁇ 머스터 장은 한때 실크의 섬유를 너무 얇고 부드럽게 휘두르며 시간이 지나면서 균열을 통과했습니다. 아직 다시 나타나지 않았지만, 우리는 언젠가 그것을 기대합니다."
rows["163:547931934"]="아뇨, 내 사랑!$B$B오늘 우리 날, 해적의 날입니다!$B$B ⁇ 무켓과 저는 이 아이디어를 떠올렸습니다. 그리고 공포의 대장이 이 아이디어를 들었을 때..."
rows["163:578401113"]="내가 작은 챔피언들을 데리고 타랑데와 직접 얘기해줄게 안두인, 내가 이 일을 처리할 수 있어"
rows["163:582661623"]="아이사와 지가 영들을 데려왔고, 당신은 그들과 함께 가서 위대한  ⁇ 진 수와 이야기해 우리 백성을 구하기 위해 필요한 모든 것을 해야 합니다."
rows["163:61497799"]="<데미트리안은 무릎을 꿇는다>$B$B내 주인의 영원한 감옥을 되찾았어!$B$B오, 오랫동안 이 날을 기다렸는데 마침내 실현되었습니다.$B$B그는 풀릴 필요가 있어요!"
rows["163:628663407"]="스톰스타우트 맥주 공장 황금시대 이후 이런 복잡성과 명확성을 맛본 적이 없어요"
rows["163:637084695"]="뉴아발론의 고장검사의 죽음은 눈에 띄지 않을 거야 당장 여기서 나가야 돼"
rows["163:690595287"]="말만 해도 우리 위치가 얼마나 불안한지 알잖아. 얼라이언스와 Thunder King 사이에,"
rows["163:703823853"]="덩가르 롱드링크를 찾고 있어요. 카즈 모단 이쪽에서 가장 빠른 그리폰들을 가지고 있어요."
rows["163:705020213"]="당신에겐 희망이 없어 당신의 암흑해안은 폐허에 놓여 있습니다 다르나서스 당신이 할 수 있는 동안"
rows["163:733369824"]="제 동생을 순서로부터 멀리 할 수 있는 비밀스러운 방법을 만들 수 있고, 그가 조금도 현명하지 않고도 그를 멀리 할 수 있고,"
rows["163:81832935"]="초급은 사제 치료가 불가능하지만, 도움이 되죠."
rows["163:852127057"]="그래니스 스위프트렉스가 스윙 스틸에 대해 몇 가지 보여줄 수 있을거예요."
rows["163:863474814"]="너희는 지식과 이해에 대해 찾아왔다고 말하지만, 전쟁에 대비하고 있다. 그래서 내가 너희와 네가 해야 할 일을 기꺼이 하고 있다는 것을 묻는다."
rows["163:880314413"]="한 번 메디프에 봉사했거나, 그랬던 것처럼 했었는데, 바이올릿의 눈을 도와 주인을 지켜봤어요.$B$B하지만 이제 내가 생각할 수 있는 건... 한 번씩  ⁇ 을 만드는 것뿐이야"
rows["163:966882469"]="만약 번개왕이 패배하지 않는다면 판다리아가 고통받을 것입니다. 하지만 더 나쁜 것은, 호드가 그의 힘의 원천에 손을 내밀면,"
rows["163:97921068"]="사우로크족은 모고족 때부터 이 땅을 괴롭혔다. 협상할 수 없습니다. 하지만 우리는 결코 멈추지 않습니다."
rows["163:998037834"]="야간 엘프 파괴자들이 이 일을 저지른 건 아닐까?"
rows["164:1003022273"]="신께 감사해요, 도착한 시간이었죠. 영웅들. 오그림의 해머가 이미 떠났어요. 빨리 스카이브레이커로!"
rows["164:1006097447"]="빨리 일어나야지 신생아, 이건 스케티스 밖에 있는 우리 편의 뒷마당이 아니라 블레이드즈 엣지 산맥이야!"
rows["164:1042440911"]="지금 우리 앞에 있는 훨씬 더 큰 문제도 있습니다. 제 학생들,  ⁇ 진 수는 고통 받고 있습니다. 만약 우리가 행동하지 않는다면, 우리가 서 있는 땅 자체가 죽을 수도 있고, 우리 모두는 그 안을 겪게 될 것입니다."
rows["164:1081471246"]="오, 그건 마치 불염고래처럼 네 입 너머로 아무것도 볼 수 없어. 우리는 드래곤마우에서 엉덩이와 팔꿈치까지 다녔어. 하지만 당신은 도움을 위해 새를 보냈습니까?"
rows["164:1089039544"]="이 얼라이언스 타바르드를 입는 순간, 그들은 죽었습니다. 저는 적선 너머의 계속되는 유대 관계를 용납하지 않을 것입니다. 호드의 배신자들은 배신자처럼 죽을 것입니다!"
rows["164:1169929768"]="또 다른 돌을 찾았어? 우리는 무엇을 배웠습니까? \"육의 저주\"는 모그를 치명적시켰습니다. 하지만 나중에 그들은 그 과정을 되돌릴 방법을 찾았습니다. 똑똑한 인종입니다."
rows["164:1179943271"]="부족 가죽 을 만드는 일 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 그것 을 포기 하기 를 선택 한다면, 부족 가죽 을 만드는 일 을 필요로 하는 모든 요리법 을 잊을 것 입니다."
rows["164:1207363392"]="아주 잘, 난 그 밖의 천문호를 찾을 수 있다고 확신합니다. 이 방패를 사용할 수 있습니다.$B$B네 위축 크리스탈이 있네 그 옷보다 더 행복해 해 줄 수 있기를 바랄게요"
rows["164:1244475219"]="난 이미 결심을 굳혔네. 이건 내 일생을 바친 계획이야. 그 목표를 위태롭게 하는 일은 우리 신념을 위해 목숨까지 바친 모든 이들을 배신하는 일일세."
rows["164:1248439758"]="워싱글루치 전투는 우리가 이길 수 없는 전투입니다. 우리는 우리의 명예를 위해 싸우고, 우리는 우리의 땅을 위해 싸우고,"
rows["164:1256160925"]="아기와 그만둬, 라자블레이드. 당신은 워시프의 엘리트군 중 한 명처럼 행동해야 합니다."
rows["164:1317299131"]="오늘 이 순간부터 모든 브리쿨은 낡은 믿음을 버린다! 우리는 더는 해묵은 신을 섬기지 않을 것이다! 모든 브리쿨은 이미론에게 충성을 다하라! 이미론이 고귀한 우리 종족을 보호할 것이다!"
rows["164:135910937"]="내가 널 보냈다고 말하지 말고 중앙탑의 지하층에서 붉은 옷을 입은 여자를 찾아라\010레디아 뱅트라는 이름이 있지만 날 언급하지 마!"
rows["164:1381223656"]="우리 아이들을 훔친 사람들을 싸웠으니, 더 나은 신뢰를 받을 기회를 주겠소"
rows["164:1447863077"]="이런 건 오크가 싸우는 방식이 아니란 말이오! 대족장님에 대한 내 임무는 개인적인 명예를 담고 싸우는 것이오. 난 당신의 그 성스러운 빛에 아무런 믿음을 가지고 있지 않지만 조언자로 보이니 당신의 얘기를 듣고 싶소이다."
rows["164:1481438970"]="|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000남동|r 문이 열리기 시작하여 |cFFFF0000|Hspell:136889|h[폭력 풍속]|h|r를 일으켰습니다!"
rows["164:1498893660"]="포털을 보면 모래로 가득한 눈만  ⁇ 니다. 사막 유적으로 둘러싸인 물의 풀이만이 알 수 있습니다. 이 포털은 어디로 인도할 수 있을까요?"
rows["164:1523731118"]="이상한 일이라는 거 저도 압니다... 필멸의 존재들은 대부분 이곳에서 본 것을 이해하지 못한답니다. 그들의 지각 능력으로는 여기서 보게 되는 것을 완전히 받아들일 수 없으니까요."
rows["164:1583056582"]="난 수주 공작 하이드라시스인데 넌 초원적인 사람이 아니니까 우리 투쟁을 이해할 수 없어"
rows["164:1583138650"]="이 문서들은 여러 트롤 스파이들을 포함하고 있습니다. 그들의 머리를 빼앗겼다고 생각하세요. 당신의 보상을 받아 현명하게 지출하십시오. 스톰윈드."
rows["164:1585907095"]="내 지식보다 더 많은 사람이 있다. 당신은 그녀를 찾으려고 준비되어 있어. 스톤탈론 산맥의 태양암 피난처로 가서, 하거트를 찾아, 훈련을 계속해 나가라."
rows["164:1590903816"]="그렇다면 우리 는 역사 에 대한 지식 을 시험 해 보도록 하자! 아이언포지 도서관 에는 특이한 규모 의 양 양 양 의 골격 이 복제 되어 있다."
rows["164:1723214338"]="셰프트라는 더 이상 없어 칼림도어 곧 황폐한 사막이 될 것이다. 나는 물론 동부 왕국들을 비틀거리고,"
rows["164:1730482845"]="이제 정말 믿어요 모가들이 타이탄들의 일을 하고 있다고 생각했고"
rows["164:1740345997"]="순위 경기장은 $6318d에서 다시 시작됩니다.$B$B챔피언이 될 수 있는 선수들은 이미 자신의 기술을 향상시키고 최고의 장비를 획득하는 데 바쁘고"
rows["164:1770557808"]="오닉스 뱀은 윈드워드 섬에 알을 낳는 것으로 알려져 있습니다. 만약 당신이 그런 알을 발견하고 안리 노인에게 가져와면, 당신은 정당한 보상을 받게 될 것입니다."
rows["164:1771746841"]="아타스 가 사라진 후, 로데론의 죽은 자 들 을 통제 하는 것 은 그 와 비슷 하였다. 내 몸을 회복 한 후, 남은 스컬지 를 해방 시켰습니다."
