rows["164:1882232116"]="난 10천년 만에 자유로웠지만 내 동생은 여전히 내가 악역이라고 생각하네"
rows["164:1905600566"]="고마워요, 친절한 영혼. 당신은 나를 코일스카르의 수수 감옥에서 해방시켰지만"
rows["164:2093665507"]="서리요새에 거의 다 왔어요. 떠나시기 전에 스톰하트 왕께 저를 좀 소개해 주시면 정말 고맙겠습니다. 우리 모두 그분께 큰 빚을 졌으니까요."
rows["164:2124892495"]="만약 그들이 알을 가지고 있다면, 총격적인 공격을 위험하게 할 수 있을 겁니다. 당신은 거기에 속삭여서 그들이 뭘 하고 있는지 알아내야 합니다. 그리고 어떤 비용으로든 알을 가져오셔야 합니다."
rows["164:220067069"]="잠자로부터 배우고 싶은 건 드래그 상위 층의 보르스탄의 불굴로 가는 것인데, 왼쪽의 계단을 타고 힘의 계곡에서 들어오는 것인데"
rows["164:249782710"]="북쪽의 너희 형제가 돌 괴수를 굴복시켜 울두아르로 가는 길에 배치했다. 머지않아 판테온의 나머지 방어군도 제거될 것이다."
rows["164:254333925"]="마법에 대한 지식에서 정말 뛰어난 것 같군요. 더 많은 것을 배울 수 있습니다. 다르나서스."
rows["164:303350847"]="끔찍한 소식이에요, 여러분. 썩은얼굴이 죽었답니다. 그런데 끝내주는 소식도 있어요, 여러분! 썩은얼굴은 죽어서 수액을 남겼답니다! 아니? 제가 이런 명언을 알다니... 놀랄 노자예요!"
rows["164:369607617"]="내가 하는 일은 물론, 내가 애를 하고, 애를 하고, 증오하고, 음모하고, 그 순환이 끝나면, 다시 애를 하고,"
rows["164:416395002"]="네놈들이 쓰러뜨린 호드 병사와 쓰러진 얼라이언스 쓰레기 하나하나가 리치 왕의 군대를 더 강대하게 했다. 지금 이 순간도 발키르가 쓰러진 너희 병사를 스컬지로 일으켜 세우지."
rows["164:475982228"]="앞에 보이는 기둥 아래쪽에 있는 문에서 무쇠 드워프들이 쏟아져 나오고 있습니다! 입구를 파괴하세요. 그럼 놈들도 후퇴할 겁니다!"
rows["164:504303027"]="바리안은 네가 방어를 완성하는 동안 성전을 지켜볼게 보냈어\010조금만 인내하고 바리안이 말해주기 전까지는 성전 가까이 가지 마세요."
