rows["165:1058880008"]="제 말은, 운명을 알리기 위해 세이지를 방문해 주시기 바랍니다.$b$b난 알아, 난 알아... 그는 괴짜이지만, 그는 당신의 미래를 예측할 수 있는 특별한 괴짜야!"
rows["165:1060204927"]="이 땅에는 빛이나 그림자가 있는지 아직 확실하지 않지만, 당신 마음이 강하다는 것을 알고 있습니다."
rows["165:1067751110"]="달의 성전은 엘루네의 사제들의 집입니다. 그곳에서 여러분은  ⁇ 드리아와 라리아를 발견할 것입니다. 그들은 사제직의 길을 더 나아가도록 안내할 것입니다."
rows["165:1095381993"]="그는 아마 우리가 Brawlpub에서 한 번도 겪은 가장 치명적인 싸운자일 겁니다. 불행히도, 그는 그의 요소를 조금 벗어났습니다."
rows["165:1119103335"]="리치 왕은 여태까지 상대하셨던 적과 다릅니다, 대영주님. 비록 희망의 빛 예배당의 신성한 땅에서는 물리치셨지만, 지금은 리치 왕의 영지 안이란 말입니다."
rows["165:1156963907"]="암흑 신부 베릴을 찾고 있어요. 그는  ⁇ 로우스 엣 타버너의 독서실에서, 읽고 기도하고 있어요."
rows["165:1218098948"]="방문하는 울리부시 왜성 중 한 명은 고고학자라는 걸 알아요\010아내 페나라고 생각하니 둘 다 탐험가야"
rows["165:1254212522"]="새로 도착한 하이번을 찾고 있나요?\010달의 성전 서쪽 날개에서 발견할 수 있고, 울리는 오크에서도 하나 있을지도 모릅니다."
rows["165:1262147893"]="환영합니다, 하위 도시 자유민의 친구, 하지만 오래 머물지 마세요.$B$B내 내방에서 전투 소리가 들리는데, 내 동포들은 여러분의 도움이 필요해요!"
rows["165:1277534189"]="안녕하세요, 저는 수호자 출입자입니다. 유두름의 판이 이미 디스크 세트에 통합되지 않는 한, 저는 유두름 복합에 출입을 허용하지 않을 것입니다."
rows["165:139984530"]="몇 년 전, 제 아버님과 여러 서릿결 부족원들은 용의 안식처를 통과하여 길고 힘든 여행에서 돌아오셨었지요. 엄청난 눈보라가 닥쳤습니다... 전에 겪었던 것보다 훨씬 대단했지요."
rows["165:1408541707"]="올해 새: PX-238 윈터 워더볼트. 올라와 부끄러워하지 마세요!$B$B그리고 시도하기 전에 이 양식을 서명해 주세요. 우리는 여전히 이 물건에서 몇 가지 버그를 연구하고 있습니다."
rows["165:1710162216"]="켄-켄은 여전히 그가 접촉하는 모든 것에 대해 방해가 되고, 그리고 자극이 되고 있습니다."
rows["165:1799335950"]="무료 사탕은 나쁜 사업일 수도 있고, 아니면..."
rows["165:1826551755"]="이 도서관은 수천 년의 역사와 전통을 담고 있습니다. 파다리아 전체에서 가장 큰 지식은 여기에 보관됩니다.$B$B그래서 우리는 이 위대한 보물을 안전하게 지켜야 합니다."
rows["165:182679445"]="미친군, 그 나쁜 마법을 방해해줘$B$B언자리 펠톤거는 동남부에서 더 높은 건물에 있습니다."
rows["165:1862288144"]="그들은 매일 하루 한 시간 동안 불을 켜고 있었습니다. 뜨거운 석탄은 원시적인 수용소에서 다른 수용소로 옮겨졌습니다."
