rows["165:2095355586"]="자린은 요리업에 대해 잘 알고 있는 것 같습니다. 왜 가서 요리법을 보여주지 않는지 보죠. 그는 보통 도라나르의 숙소에서 요리합니다."
rows["165:308138421"]="우리는 가정이나 가족을 지키기 위해 싸운다는 것이 귀족이라고 동의할 수 있습니다. 하지만 복수? 분노는 어떨까요?"
