rows["165:852962726"]="에스코다르의 전용 섬유는 위험하게 줄어들었고, 만약 당신이 이 섬유를 기부함으로써 우리에게 도움을 주면, 이 곳의 드레네이와의 명성은 높아질 것입니다."
rows["165:861158795"]="만약 빨리 그렇게 되지 않는다면, 수많은 탈북자들이 사랑하는 사람들을 쫓아다니며 스스로 죽게 될 겁니다!"
rows["165:879222951"]="만약 이 탑이 두 배 더 많은 볼륨을 자랑한다면, 그것은 여전히 나에게 충분하지 않을 것입니다.\010내 도움이 필요해?"
rows["165:951062256"]="구름 뱀의 질서가 자이드 숲을 지키기로 맹세합니다. 우리는 자이드 숲에서 자이드 뱀의 성전 북쪽에 있는 아보레텀에서 훈련합니다."
