rows["166:1121595638"]="드래곤 애스펙트들이 나나 내 동료 모험가들에게 도움을 주지 말라는 겸손한 부탁입니다."
rows["166:1138888416"]="책 의 페이지 에서 수백 가지 의 여러 가지 도표 와 스케마 가 형성 되고 있습니다. 일부 도표 는 인식 할 수 있지만, 다른 도표 는 낯선 것 이지만 익숙 합니다."
rows["166:1185802510"]="가라다르는 혼란에 빠졌어, 이상하네. 할머니가 병에 걸린 이래 가로쉬는 깊은 우울증을 겪어왔어. 그는 확실히 아버지의 아들이 아니다.$B$B큐큐쉬가 숨쉬는 것\010"
rows["166:1231086373"]="도시의 아카네 리포저인 마녀 피라가 당신을 도울 수 있습니다. 그녀는 종종 세단나와 그녀의 마녀의 연습생들과 함께 태양의 궁전에서 발견됩니다."
rows["166:1244740406"]="돌에서 울리는 거침없는 목소리...$B$B이게 뭐야? 나는 조금 이교도  ⁇ 을 느끼기 시작해!  ⁇ , 벌레, 또는 공의회의 주인의 분노를 직면!"
rows["166:1283755784"]="땅은 가혹했습니다. 반복적으로 볼진과 그의 사람들은 호드의 생존을 보장했고, 우리를 굶주림으로부터 구하거나 공격당했을 때 무기를 들고 있었습니다."
rows["166:1301494400"]="여녀야, 두려워하지 마요, 난 단지 네 하단에 있는 구두를 고정시키고 싶어."
rows["166:1384678649"]="이 \"SI:7\" 사람들은 저를 데리고 가기로 결정한 것에 기쁘습니다.$b$b우리 호수 안락을 떠나지 않는 게 거의 없습니다. 이것은 내가 집에서 가장 멀리 있었던 것 같습니다."
rows["166:148666087"]="안녕하세요. 저는 드레네이의 아코리트 아vuun입니다. 저는 그들의 병에 대한 치료법을 찾을 수 있을 것으로 기대하며,"
rows["166:1558329008"]="내 영혼은 수년간 에메랄드 드림에서 자고 있었고,"
rows["166:1672891073"]="이 과정에서 인장을 위험으로부터 보호하는 방법에 대해서는, 각 감시자의 상태를 분석한 계산 결과를 참고하십시오."
rows["166:1753093344"]="반짝이거나 두 번 불을 붙여줄 생각? 나 직접 불꽃놀이를 사야겠어!$B$B지도에 위치를 표시해 줄게요"
