rows["166:178843784"]="제가 생각했던 모든 지혜에도 불구하고, 저는 호드을 거의 함께 유지할 수 없었던 순간들이 있었습니다. 화난 게이트와 언더시티는 충분히 명확하게 보여줬습니다."
rows["166:1809267523"]="아, 그 허물은 잃어버리지 마라. 불타는 평원에는 검은용군단의 허물로 강력한 물건을 만드는 종족이 있다고 하니까."
rows["166:1815660617"]="한 번 퀴라 윈드블레이드를 전투에서 본 적이 있어서 내가 목격한 것을 고려하면, 그녀는 당신을 잘 훈련시킬 것이라고 확신합니다."
rows["166:1821943794"]="우리 병력을 유령의 땅 전체에 분산하면 데솔름을 공격할 때 거의 힘을 쓰지 못할 것이오. 아우리페러스 귀부인, 안 됩니다. 저는 다르칸을 죽이러 여기 왔고 그 목표를 반드시 이룰 것이오!"
rows["166:1897248837"]="자네가 윈터가드를 구했네! 텔잔이란 더러운 존재가 사라졌으니 나머지 스컬지는 7군단이 손쉽게 처리할 수 있을 걸세. 여기 일을 마치거든 앙그라타르로 와서 보고하게!"
rows["166:198662732"]="이 문제를 해결하기 위한 호드여기 나무를 모으는 노력이 잿빛 골짜기밤 엘프들과 그들의 동맹들은 쓰러질 것입니다!"
rows["166:2124805956"]="더 이상 걱정하지 마, 타타카 호드 당신과 당신의 사람들을 보호하고 구원할 것입니다. 하지만 먼저 당신은 호드."
rows["166:2137913070"]="어쩌면 네가 필요한 걸 가지고 있지, 그렇지 않을지도 몰라. 그렇게 한다면 내가 너를 데려가서 네가 알고 싶은 것을 가르쳐 줄게."
rows["166:269453616"]="더 이상 가르쳐 줄 게 없어 이제 나가서 사루를 가까이 하지 마"
rows["166:269990865"]="수십 명의 조종사가 북쪽으로 더 떨어진 곳까지 격추되었습니다. 우리 자신의 SI:7 요원 중 한 명을 포함했습니다.$B$B우리 모두 도와야 하지만 먼저 호드를 처리해야 합니다"
rows["166:293814908"]="버드의 팀원이라고 말해서?$b$b'그들 외엔 죽은 놈들, 버드는 그들을 싫어하고, 두려워하는 것 같지만, 그렇지 않을 것 같네.\010"
rows["166:310007252"]="아름다운, 아름답습니다. 시간이 있다면 동쪽 성전을 방문해 보세요. 우리의 위대한 동상과 우리 삶의 방식에 대한 중요성을 더 깊이 이해할 수 있습니다."
rows["166:33669157"]="걱정 마요, 제가 말했듯이 우리 사람들은 거의 슬라이더링을 발견하고 있습니다. 그들은 적절한 희생을 할 것입니다. 심지어 자발적으로도 말이죠."
rows["166:368975919"]="보물과 관련해서는 다른 사람의 쓰레기를 훔치는 것을 결코 옆으로 보지 말아라. 훔친 물건은 훨씬 더 달콤해, 그렇죠?"
rows["166:415168060"]="우린 당신들의 전쟁 중 더 오래 갇혀 있지 않을 겁니다."
rows["166:444789267"]="지금도, 원천들은 여러분을 찢어내고 있습니다. 그리고 이 불행한 세상에서 마지막 생명 스파크가 꺼질 때까지 여러분의 의심과 두려움에 먹이를 줄 것입니다."
rows["166:450573996"]="호드는 정의를 원한다! 이제 얼라이언스에 도전한다! 성기사여, 우리가 그대의 기사를 대신하여 싸우도록 하라. 호드를 모욕한 대가를 이 쓰레기들에게 보여줄 테니."
rows["166:455949410"]="만약 여러분이 이 대륙이나 세계 어느 대륙에서든 최고의 공예품을 찾고 있다면, 여러분은 올바른 곳으로 왔습니다!$B$B그림드 엘모어, 당신의 서비스!"
rows["166:489920485"]="한 선조가 투  ⁇ 의 봉기에 참여했고, 지금은 무덤들 사이에 있다."
rows["166:550983075"]="이건 어둠 속의 칼에 대한 이야기입니다!$B$B이 곳에서는 용기 있는 3명의 모험가들이 호드의 다크스피어 트롤의 지도자인 볼진을 암살으로부터 구해냈습니다."
rows["166:631299240"]="세계적으로 유명한 노겐포거 엘리시어는 여기 팔려요!$B$B가드게잔에서 온몸으로 만든 재료로 마셔 팔았어요"
rows["166:659474641"]="피부 치료 및 피부 작업 을 배우려면 북쪽으로 오그리마 로 이동 하십시오. 오그리마 그런트 중 한 개 는 피부 작업 트레이너 로 가는 길을 알려 줄 수 있습니다."
rows["166:71041928"]="|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t 동맹군으로부터 멀리 떨어져라! 한 Sra'thik Amber Trapper가 당신을 캐스팅하고 있다 |cFFF00000|Hspell:121881|h|h|r"
rows["166:786885463"]="난 워크겐이 더 좋아했는데, 작은 무리를 지어서 접할 수 있는 엉망이었죠. 얼라이언스 더 어려운 문제입니다."
rows["166:791815531"]="우리는 여러 동물의 시체 중 한 개에서 천을 향해 총을 쏘아 올린 세일과 리네스를 발견했습니다.$b$b좀 맑고 마법이 있고, 프레스토... 새것처럼 좋네요!"
rows["166:794913052"]="난...  ⁇ ... 내가 할 수 있는 최선을 다하고 있어, 알았어?! 스프리트는 내 손에서 구슬을 때리고 있거나$B$B난 이런 것들을 싫어!"
rows["166:832854283"]="무슨 짓인가? 너 때문에 내 정체가 거의 드러날 뻔했잖아, 멍청한 녀석! 내가 분명 나침반하고 항해 지도를 안전한 곳에 두라고 하지 않았나. 바보도 쉽게 찾을 수 있는 뻥 뚫린 곳 말고!"
rows["166:905615042"]="물론 그 형상은 내가 아니었다. 네가 앞뒤를 재보고 다녔다면 과거의 내 환영을 봤을 게다. 하지만 네 녀석이 그 일과... 날 위해 잘 해내 주었으니 감사해야겠구나!"
rows["166:91975198"]="이리엔이아 달불은 다르나서스 그리고 Timberline Arms의 Bixi Wobblebonk 아이언포지 무기를 제대로 사용하는 방법을 보여줄 수 있습니다."
rows["166:953569821"]="강아지들이 며칠째 우리를 공격해왔지만, 그레이트 라이트닝스톤은 여전히 안전해$B$B수홀루가 우리에게 도움을 줄 수 있는 거요. 강아지들은 기회가 없어서"
rows["167:1107738860"]="루시우스는 라벤하일드 맨어의 오랜 친구이고, 저와 함께 논의해야 할 일이 많아요. 만약 제 도움이나 조언이 필요하다면 레이크샤이어에 항구에서 찾아보세요."
rows["167:1138565373"]="이 곳을 '말시'라고 불렀는데 그 당시엔 몰랐어요."
rows["167:121142274"]="우리가 먼저 신성 벨을 못 찾으면 거북이 간과의 괴짜가 갈로쉬를 잡을 거야 호드 그 힘은 삐걱거리는 것을 지배한다."
rows["167:1227069325"]="에샤 루마메이든은 옷의 기술로 유명하다.$B$B그녀는 숙제실에서 왼쪽으로 들어갑니다.$B$B지도에 위치를 표시해 줄게요"
rows["167:1234407382"]="우편 상자? 보내야 할 편지, 아니면 받은 편지도 있으세요? 좋은 것 같으면 좋겠어요. 다르나서스의 중심에 은행 밖에서 우편 상자 있습니다."
rows["167:1271762696"]="전투장들은 파스트라이더스 광장에서 있는 블러드 라이트의 한반도의 거리에 편안하게 싸우고 있습니다."
rows["167:130020468"]="필사자, 우리 안의 성전을 침범할 용기가 있어\010 돌아가지 못하는 문턱을 넘으면"
rows["167:1320895095"]="전보다 먼저 온 모든 사람들을 가르치는데 더 많은 시간이 있었으면 좋겠다 하지만 불행히도 그런 방법이 아니다."
rows["167:1330247282"]="이 새로운 땅을 우리 소유로 삼으려면 우리 전투로 지친 몸을 휴식할 곳이 있어야 합니다."
rows["167:1345421313"]="테라모르의 경호자들은 최고의 무대입니다 얼라이언스 에 있는 군인 칼림도어우리 의무를 다하고 얼라이언스 우리 집에서 너무 멀리 떨어져 있긴 하지만"
rows["167:1355134942"]="야자나무는 잠들면서 저를 견뎌냈지만 시간이 지남에 따라 그 힘이 사라지는 것을 느꼈습니다.$B$B네가 날 깨우지 않았다면, 나는 곧 영원한 잠에 빠졌을 것이다."
rows["167:1431776341"]="지식의 자리에는 고고학 석사가 있습니다. 이 곳 영원한 꽃의 계곡에 있는 모구'산 궁전 위에 있습니다.$B$B지도에 그들의 위치를 표시해 줄게요"
rows["167:1551819382"]="내가 내 일을 하고, 카드 게임을 즐기고 있었는데, 은 계약의 총기들이 우리 물건들을 넘겨달라고 말했어요."
rows["167:1554030357"]="사실, 언젠가 셰를 무기로 활용할 수 있을지도 모르지만 그 과정에서 우리 자신의 사람들을 파괴할 위험이 있습니다."
rows["167:1597468095"]="여러분처럼 저는 고대 판다렌 전통에 참여하는 기회를 거부할 수 없었습니다. 여러분이 준비가 되면,"
rows["167:166205798"]="난 악의 천지를 빼앗아간 위대한 릭-리크의 아들이야 그는 죽었어 이제 나는 장군이네"
rows["167:1701688159"]="이 세상이  ⁇ 에 무너지고 있는 것 같군. 드레너에서 이런 증상을 본 적이 있어... 우리는 이것을 막을 수 없을지도 몰라 도망치는 것이 최선의 선택일 수도 있다."
rows["167:173385200"]="하지만 엘룬은 그 사랑을 허락하지 않았소. 악마의 오염된 칼날이 아나테라의 갑옷을 뚫고 들어왔지. 격렬한 전장에서 누구도 그녀를 구할 수 없었소."
rows["167:1903716774"]="더 경험이 풍부한 선생님을 선택해야 합니다. 왜냐하면 당신은 제 능력을 뛰어넘었기 때문입니다. 저는 여러분께 리리시아 나이트브리즈와 이야기해 주시기를 권합니다. 그녀는 많은 지식을 제공 할 수 있습니다."
rows["167:1930696346"]="스컬지와의 싸움의 첫 단계는 잘 진행되었습니다. 우리는 몇 가지 성공을 거뒀습니다. 그리고 내 도움이 앞으로 전투에 성공하는 데 도움이 될 수 있기를 바랍니다."
rows["167:1947064540"]="이건 확실히 제 일반적인 정보 수집 작전보다 더 흥미롭습니다. 이제 서둘러 가로쉬를 돌봐요, 이것이 SI의 마지막 임무가 되길 바라지 않습니다:7."
rows["167:2019060361"]="놀랍군요. 이것은 티탄이 칼림도어에 살았을 때 운고로가 그의 집이었다는 주장들과 일치합니다. 아마도 아만툴이 직접 '신들의 땅'을 지키고 있었던 것 같습니다."
rows["167:2079665841"]="데렌다 엔클레신은 마법의 물품을 들고 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["167:2080686465"]="제로드한테는 일하는 게 나쁘지 않아 가끔씩 화를 잃는 게 있지만, 그는 돈을 많이 내고,"
rows["167:230792154"]="블러드 엘프 군대가 바로 이 다리를 건널 때 알도르 사제회의 총독과 구원자들이 빛의 정원을 방어하고자 진을 쳤습니다. 그런데 그때 전혀 예상치 못한 일이 벌어졌습니다."
rows["167:328120104"]="정말 멋진 일이었어요! 잘 해냈어요. 이미 여러분의 승리를 축하할 계획을 세우고 있습니다. 다음 주에 준비는 끝납니다."
rows["167:342316819"]="토마스는 최고의 요리사가 아닐 수도 있지만, 몇 가지 요리가 있어 현재 레온 프라이드 인에서 일하고 있습니다."
rows["167:391553067"]="이 마나 폭풍의 눈 안에 있는 세포는 소중한 물건입니다. 우리는 그들을 드레네에 잃지 않을 수 있습니다!"
rows["167:40045196"]="우리가 할 일이 많지만, 시간이 거의 없습니다. 만약 우리가 프리윈드 포스트에 도움을 주고 그리모테마를 다시 밀어내려 한다면요.$B$B토르 일리사'테라'나'알, 우리 적들이 조심해!"
rows["167:458748548"]="아르타스의 약점은 그의 자부심입니다. 그 약점은 그의 힘과 함께 성장합니다. 에본 블레이드는 그 한 번의 왕자를 공격할 기회를 가질 것입니다."
rows["167:494672651"]="아저워치에는 화공이 없는데, 하지만 남해안의 이상한 캠프에서 몇 명의 젊은 화공이 왔을 거 봤어요."
rows["167:579850962"]="바늘은 작지만, 끈은 강하고, 꿰매기는 잘합니다. 트롤과 다른 사람들과의 우리의 조약은 유지됩니다. 호드이 땅에서 쫓겨날 수 없습니다."
rows["167:596673919"]="카르텔 전쟁 전부터 술은 섞고 있어 곧 그만두지 않을 거야$B$B구매자가 있을 때까지, 올'바바는 판매를 준비할 거야!"
rows["167:623217368"]="모가족은 고통과 고문, 암흑 마술과 잔인한 무기의 주인이었습니다. 판다렌, 호젠, 또는 진이우는 그들의 권력을 저항할 수 없었습니다. 그리고 제 사람들은 두려워했습니다."
rows["167:684205064"]="우리 조상들은 그의 재탄생을 목격하기 위해 먼 미래를 바라봤지만, 그 대신 우리는 우리 인종이 많은 위험으로 인해 괴롭혔다는 것을 보았습니다."
rows["167:692730970"]="그럼 역사에 대한 지식을 시험해 보겠습니다. 실바나스 윈드런너의 자매 중 한 명이 고위 엘프와 키린 토르의 무장파를 이끌고 있습니다."
rows["167:793383375"]="오리온 대장, 이번 작전에는 적당한 인명피해가 있다고 보고하고 있습니다."
rows["167:851500622"]="누구든... 언젠가는 죽음을 맞이하게 마련이지만, 때 이른 죽음을 자초하는 사람도 있지. 오늘 우리는 그런 이를 눈먼 영웅이라 부르지만... 내일 누군가는 그를 바보라고 부를지도 몰라."
rows["167:893612009"]="귀국한 하이보른 중 한 명을 찾고 있어요$B$B그들의 미스터리 포퍼 중 한 명은 마법사 타라단과 시간을 보냈습니다."
rows["167:905786930"]="다른 사람에게 말하지 마, 하지만 나도 모든 걸 몰라! 계속 배우고 싶다면, 가게의 주인인 스프링스핀드 피즈레거와 이야기해봐."
rows["167:91810815"]="내 힘이 최고조에 달한 지금이라면 꿈의 집중을 사용할 수 있도다. 그걸로 다른 비룡들을 치료할 수 있지만, 내 체력도 닳게 되므로 착취 독과 함께 사용하는 것을 잊지 말아라!"
rows["167:967967645"]="그리고 네, 쇼갈은 Twilight's Hammer를 설립했을지도 모르지만 오늘날 그 모습을 만든 사람은 누구였죠?"
rows["168:1015233034"]="무분별한 무모한 무얼버릭이 날 때렸어 내가 기지로 돌아오지 않으면 모든 것이 사라질까봐 두려워"
rows["168:1078419201"]="말론은 어떤 식으로든 가장 섬세한 허브를 손해하지 않고 채우는데 그 사람이야"
rows["168:1104035570"]="저는 전투기를 바라보는 것이 아니라, 전투 마스터들의 임무입니다.\010제 관심은 두 신생생들을 치료하는 의무가 있습니다. 지금까지 제 학생들은 잘하고 있습니다."
rows["168:1113967909"]="파다리아에서, 저는 호드가 마땅히 사는 땅을 봅니다. 우리는 그것을 우리 자신의 것으로 받아들일 것이고, 누가 우리의 길을 걸으면, mogu 또는 얼라이언스"
rows["168:1209772126"]="할머니가 우리 모두를 키웠어요. 여러분이 보는 마가리족은 할머니가 특별한 방식으로 그들의 삶을 만났습니다. 그녀가 세상을 떠날 때 우리는 그녀를 그리워할 것입니다."
rows["168:1214292460"]=" ⁇ 더들! 그들은 더 이상 잘리지 않을거야. 그들은 너무 어제!$B$B만약 우리가 로켓을 만들려면 - 만약 우리가 X-52를 발사하려면 - 더 나은 기술이 필요합니다!"
rows["168:1236074220"]="만약 당신이 화학에 대한 훈련을 필요로 한다면, 스톰윈드에서 갈 필요가 있는 곳은 하나만 있습니다."
rows["168:1309085918"]="인간들은 아라티 계곡에서 포세이큰에 맞서 싸우는 데 당신의 도움이 필요합니다."
rows["168:1359697408"]="저는 두 가지 일에 전문적이죠. 작은 것들을 가지고 거대한 물건으로 폭발시켜요. 그리고 거대한 물건들을 작은 곳에 넣는 거죠.$b$b오늘 어느 쪽이 필요해?"
rows["168:1414545183"]="그림자의 갈래에서  ⁇ 도잔을 찾아라 그 동굴로 몇 개의 터널이 있는데 하나는 지혜의 계곡 남쪽이고 다른 하나는 드래그에 있습니다"
rows["168:1447940167"]="스파크 하나 둘을 꺼내야 한다고 생각하니 내가 직접 불꽃놀이를 사봐야겠어$B$B지도에 위치를 표시해 줄게요"
rows["168:1516418804"]="신호등이 서로 노래하고 있어 외계인 중요한 메시지가 보내지고 있어$b$b당신의 귀는 메시지를 듣지 않을 것입니다. 오직 클라시티가 신뢰하는 사람들이 그들이 말하는 단어를 듣습니다."
rows["168:1579115938"]="네 이름이 스랄이라고? 네가 노예로 지낸 건 다 과거일 뿐이다, 손자야! 하지만 더는 아니란다! 듀로탄을 마지막으로 만났을 때 듀로탄은 아직 태어나지 않은 아이의 이름을 알려줬었지... 듀로탄이... 정말 자랑스러워했는데..."
rows["168:1604716689"]=" ⁇ 은 모든 창조물에서  ⁇ 을  ⁇ 어$b$b무료 음료를 마실 때, 많은 사람들이 그들의 차이점을 놓을 수 있는 것 같습니다."
rows["168:1632521929"]="좋은 카파 잔보다 더 좋은 것은 없다. 씨앗을 제대로 굽고, 신선하게 마르고 순수한 물에 끓이면 된다.$B$B피곤한 여행자나 공부하는 승려에게 완벽합니다."
rows["168:1632799929"]="모데라 대장님은 간단한 전략을 취하고 있습니다. 모게를 힘으로 물리치고요. 저는 더 많은 연구를 통해 모게의 약점을 발견할 수 있을 것이라고 믿습니다."
rows["168:1670299566"]="달 축제의 중심은 무롱라드입니다. 다르나서스의 센리온 앙클래브에 있는 드루이드는 걸을 수 없다면 당신을 데려갈 수 있습니다."
rows["168:170938023"]="이 꿈에서 그들은 어떻게든 아이스크림을 발명하고 딸기와 맛을 내는 것을 끝으로..."
rows["168:1826094417"]="고대 지혜는 네 개의 원자 영의 목소리로  ⁇ 진 수에게 말을 했다고 합니다. 하지만 영들은 우리 위대한 성전에서 도망쳤고 그들의 힘은 사라지고 있습니다."
rows["168:18447227"]="매우 특별한 시험에 오신 것을 환영합니다! 리더의 지혜는 그의 추종자들의 위대함에 반영됩니다. 당신의 훈련이 정말로 당신이 이끌 사람들을 영감을 주는지 확인해 보도록 합시다."
rows["168:1868233758"]="<트레엘로스 관장님, 웃겨서 쳐다보고 잠시 멈추고, 분명히 싸우고 있습니다>$B$B장그라마시, 진실에 너무 가깝다$B$B얼굴이 또 미쳤어$B$B아직도 지켜보고 있냐?"
rows["168:1921967531"]="다르나서스의 공예들 가운데, 여러분들이 선택한 공예품에 대한 지식의 천년대가 있습니다. 이제 말해 주십시오."
rows["168:1923349354"]="지금 날보다 더 높은 곳에 올라가고 있어 아이언포지내가 할 수 있는 것보다 더 많은 것을 보여 줄 거야!"
rows["168:1933186429"]="그 비참한 짐승은 쫓겨났지만 내 소중한 물은 오염됐습니다.$b$b여기서 계속 머무르면 방어할 준비를 해\010"
rows["168:1938303345"]="클래스 트레이너들은 빛의 테라스의 중심 구조의 다양한 지하층 날개에서 찾을 수 있습니다.$B$B알도르, 스라이어 아니면 다른 사람이 당신을 도울 수 있을 겁니다."
rows["168:1939136123"]="콤즈 씨는 선박의 엔지니어이자 사령관으로, 당신이 필요로 할 모든 물품을 공급할 수 있습니다. 기술공또한 장비가 수리할 필요가 있다면"
rows["168:1970405563"]="코일스카르의 나가들은 죄수들에게 극히 잔인하다. 내가 그 수심한 감옥 안에서 살아남은 것은 기적이에요."
rows["168:1970894468"]="그루머누스를 찾고 싶다면, 먼저 아이언포지로 가야 해. 도시의 중심으로 가서 그레이트 포지스를 찾아라."
rows["168:2088097636"]="당신은 봉사할 자격이 없습니다 리치 왕 죽지도 못해 열심히 일해 내가 널 이 세상에서 영원히 풀어줄 수 있어"
rows["168:318500969"]="리 페이 선생의 목소리는 \"그 도전을 극복해 나가, 후의 존재로 영광받아 그의 불꽃을 다시 부추어 주며, 당신의 정신이 순수하다면 그는 당신을 따라가게 될 것이다\"."
rows["168:348713285"]="테라모어의 수강장 밖에서 왜리한테 조심해\010그는 술에 취하고 폭발물도 가지고 있지만 충분히 친절하고 광산을 잘 알고 있습니다."
rows["168:400512911"]="드라카리는 제단 건물에 내 몸을 죽기 가까이 보관하고 있지만 내 영혼을 볼 수 없습니다.$B$B우리 모두 함께 일해야 해 그들이 내 힘을 얻을 수 없도록"
rows["168:4379686"]="아델라, 당신은 먼 동쪽으로 공격해야 합니다. 호드 당신의 판단은 총격력만큼 강해질 수 있기를 바랍니다."
rows["168:441235037"]="이런 머릿속 통증은 날 죽이고 있어요$B$B저들을 구하러 보냈을 거야 너무 오래 걸렸어"
rows["168:465579831"]="프라우드머 레이디의 군대는 아르키몬드와 그의 불타는 군단를 지연시키기 위해 피를 흘려보았으며, 이제 이 비참한 임무는 우리 손에 달려 있습니다."
rows["168:524893038"]="존재 포세이큰 저는 물 아래에서 살 수 있고, 물에 잠겨 있을 수 있습니다. 233- 다른 살이 있는 필사자보다 더 길어 233%%."
rows["168:581227850"]="이 모든 것... 우리 형제 자매들이 지나고, 린이 야롱로에게 잡혔고, 내 맥주는 사라졌는데\010어쩌면 난 맨티드까지 싸워갈지도 몰라"
rows["168:586702684"]="악마들을 불러내는 것은 위험한 관행이지만 그 결과의 힘이 엄청나게 될 수 있습니다."
rows["168:587216328"]="먼저 마상시합의 최고 용사 셋을 상대할 걸세! 이 용감무쌍한 싸움꾼들은 다른 이들을 모두 이기고 마상시합의 최고 수준에 올라선 자들일세."
rows["168:605924903"]="수천 년 전, 모가족은 모든 권력을 가지고 있었고 철수다구로 이 땅을 통치했습니다. 하지만 제국이 성장하면서"
rows["168:618878805"]="안녕하세요! 당신이 호드과 내가 얼라이언스에 속한다는 것을 알고 있지만, 이번엔 그걸 뒤로 치면 어떨까요?"
rows["168:685846956"]="전... 세상... 다시 한 번 그를 필요로 합니다. 하지만 그는 항상 다른 사람들의 욕구를 자신의 것보다 먼저 두었습니다."
rows["168:761513710"]="하늘로 날아다니는 것만큼은 정신을 자유롭게 하는 것은 없습니다. 당신이 공기를 통해 날아가고 싶다면 마을의 중심에 있는 바람 라이더 마스터 타크와 이야기 할 수 있습니다."
rows["168:837116143"]="좋은 일이죠. 제가 할 수 있는 모든 여가 시간을 최고의 열정을 위해 보냈습니다.\010몇 개를 이용해 게이트에 방어 위치를 설정해 봅시다"
rows["168:8482982"]="나루는 캘타스를 배신한 이들을 받아들였습니다. 점술가 길드라고 불리게 된 그들은 지금 저 위 언덕에서 살고 있죠. 그곳은 점술가 길드에 속한 자들만이 마음 편히 드나들 수 있습니다."
rows["168:958658526"]="가살꾼이라고 말해요? 응원 훈련자! 네, 네일라 간호사가 동남쪽의 갈로우스 엣 타버너 안에 서 있는 걸 보면 그 이유를 알 수 있을 겁니다."
rows["168:97460042"]="제이나, 내 말 잘 듣게. 리치 왕을 쓰러뜨려야만 하네. 그를 설득할 수는 없어. 리치 왕은 자네와 동료를 모두 처치하고 강력한 스컬지 병사로 다시 일으킬 걸세."
rows["169:1035648676"]="이제 내 눈과 귀가 마치... 귀가 마치... 강력한 귀가 있는 어떤 것 같구나!"
rows["169:1036165093"]="감히 얼라이언스가 내 요새 안에 이렇게나 깊숙하게 쳐들어왔단 말인가? 명예의 요새의 포로들을 데려오고 사형 집행인을 불러라! 이곳을 침범한 대가는 목숨으로 치러야 할 것이다!"
rows["169:1147524426"]="드라카리, 이 일은 우리가 당신의 야생 신들의 힘을 훔치도록 막지 않을 것입니다."
rows["169:1168392634"]="내가 아달에게 말했어요. 많은 난민들을 수용하는 것은 곤경에 처해버릴 뿐이라고 하지만, 그는 듣게 되겠나?"
rows["169:1203052813"]="타락한 타이탄의 부패, 파괴자의 부패, 결국 스태프는 증오의 씨앗에서 만들어졌습니다."
rows["169:1214052624"]="린나, 여기 머물고 캠프를 세우고. 의료막과 피난처가 우선되어야 합니다. 농민들이 도착하면 항구 건설을 시작하도록 하세요."
rows["169:1226764121"]="여기 사람들은 항상 도움을 필요로 하지만 당신은 아직 충분히 강하지 않습니다. 이 땅을 더 걸어 한 번, 다시 와서 그들은 당신을 도와 달라고 간구합니다."
rows["169:1412298618"]="여기 다크크레스트와 블러드스케일 부족의 나가 지도자들에게 보상 공지사항이 있습니다."
rows["169:1427318428"]="내 칵테일을 만드는 능력이 당신보다 낮아 아인틸과 대화할 준비가 되어 있어"
rows["169:1464395531"]="일어나라, 젊은 볼둔이여... 그런 거추장스러운 격식은 필요 없다. 나는 우리의 주인이신 캘타스 왕자님의 명령으로 왔다. 그분께서 마나 폭탄의 진척 상황을 점검해 보라고 명하셨다."
rows["169:147685206"]="내가 할 수 있다면 훈련해 주겠는데, 하지만 좀 더 누군가의 도움이 필요해요. 아이언포지브론크가 보낸다고 말해!"
rows["169:151349226"]="남동쪽을 보면 무자비한 요너 근처에서 영주가 곧 모습을 드러낼 것이다. 그가 내려오도록 놔두어라. 발할라스의 투기장을 벗어나선 안 된다."
rows["169:1567312626"]="$p 감사합니다! 당신이 우리를 도와주셔서 너무 행복합니다. 제 로는 지금 나와 함께 있고, 아버지도 편안한 것 같습니다.$b$b그는 인정하지 않을거야, 하지만 내 아버지는 로를 좋아한다고 생각합니다."
rows["169:158585868"]="언더보그로부터 공부하고 배울 수 있는 것은 평생 기회입니다.$B$B내가 얼마 전 노예 펜의 상자 안에 앉아 거의 죽은 줄 생각하면..."
rows["169:1635023599"]="헤그룸의 블랙마우 홀에 침투 계획은 야심찬 계획입니다. 오크에게도 매우 두발한 것입니다."
rows["169:165806099"]="수도원에서 멀리 걸어서 발에 살인이 일어났어요. 그리고 식욕을 먹으러요. 저는 다시 일어서려고 생각하기 전에, 여기 에너지를 채우고 시간을 보낼 것 같아요."
rows["169:1707433633"]="괴물 공학의 비밀은 폭발을 막는 데는 상관이 없고, 폭발을 원하는 곳으로 향하는 데는 상관이 있습니다."
rows["169:1811540063"]="전장에서 맞닥뜨린 적이 형제거나 불구대천의 원수이든 아니든 존중하십시오. 자신이 진정으로 믿는 바가 무엇이든 간에, 이러한 존중은 서로 통하는 바가 있는 법입니다."
rows["169:1824211018"]="아제로스에서의 네파리안의 패배에 대해서 필시 들었을 것입니다... 그가 실패했다고는 하지만, 실험은 계속되고 있습니다. 제 주인님께서... 그분께서는 그분의 후계자가 시작했던 일을 계속 진행하고 계십니다."
rows["169:184829248"]="타루온 대사가 저를 데려왔는데, 저는 새로운 동맹국들에게 이 세상의 요소들을 가르쳐 줄 수 있기를 바랬습니다."
rows["169:189967488"]="넌 이제 오크가 아니야 그리고 너만 대신해 말야 우리 민족을 배신해서 나약한 동맹을 맺었어"
rows["169:1917805042"]="자라스, 나 혼자서도 얼마든지 해그늘 주둔지까지 갈 수 있다. 서한을 전달하지 않으면 일리단 님께 우리 모두 죽게 될 것이다! 이만 돌아가도록!"
rows["169:2003693291"]="오, 아니, 스푸터발프는 날 죽일거야! 시스... 여기서부터 자기 교통수단을 찾아내면 좋겠어."
rows["169:2023980386"]="이런 무관심한 성격이 이렇게 멀리까지 왔다는 것은 정말 놀랍습니다.$B$B네, 다른 매력이 있을지도 모르지만 마우아리는 네 행동에 매우 불만을 가지고 있습니다!$B$B가자, 당장 "
rows["169:2050841312"]="만약 당신이 위대한 paladin가 되고 싶다면, 그레이슨 스카드브레이커보다 더 좋은 선생은 없습니다."
rows["169:2090500448"]="곧 깨달으리라. 내 일이 끝나면, 너는 자비를 구걸하겠지. 나는 거부할 테고. 고뇌에 찬 네 비명은 풀려난 내 힘에 대한 서약이 되리라..."
rows["169:2125394481"]="모든 판다레인은 자신의 운명을 찾아내야 합니다. 전사이든 농부이든, 우리 각자는 우리에게 맞는 장소를 가지고 있고, 각각의 장소는 고유한 중요성을 지니고 있습니다."
rows["169:2138463048"]="드레드 캡틴 데메자는 부티 베이에 진입해 해적의 날이라고 선언했습니다!$B$B그녀는 그녀와 함께 술을 마실 용기가 있는 모든 사람을 명예 승무원으로 만들려고 합니다."
rows["169:304239624"]="우리 사냥꾼들 중 일부는 이미 반에틸 바로우 텐으로 갔습니다. 당신이 들어가면 당신을 찾을 것입니다."
rows["169:309775604"]="우린 쉐도파인이 가진 가장 강한 놈이 필요해 증오의 샤와 대결을 할 수 있어"
rows["169:343346405"]="드래곤마우에 설명하기는 어렵습니다. \"불밭\"이나 \"압압적인 방역\" 같은 개념이죠.$B$B다행히도, 그들은 \"살인 구역\"과 \"살인\"에 대해 잘 알고 있습니다."
rows["169:351687983"]="크라우리는 우리 종에게 부끄러움을 안겨주었습니다 포세이큰내 무리가 그들에게 워크겐의 진짜 얼굴을 보여주며 우리의 존재와 함께 오는 불쌍한 분노를 보여 줄 것입니다!"
rows["169:39912368"]="우선 신도레이들은 잘 들어라. 나는 무엇보다도 기강을 중시한다. 점술가 길드와 있을 때와는 전혀 분위기가 다를 것이야. 그러니 전력을 기울이든가 아니면 당장 배로 돌아가라!"
rows["169:501400901"]="전투는 승리했습니다. 현재까지 스컬지 위협은 뒤로 밀려졌습니다. 우리의 자원은 감사의 표정으로"
rows["169:523398176"]="저는 다양한 형태의 회복 마법에 뛰어들었습니다. 물의 힘에서 신성한 힘까지요. 하지만 저의 진정한 소명은 항상 안개가 주는 은혜입니다."
rows["169:545856560"]="이 벽 안에서 그대들은 시험을 받으리라. 그대들의 전투 실력이 노스렌드의 가장 무시무시한 적을 상대하기에 부족함이 없는지, 모든 지도자가 주의 깊게 지켜볼 것이다."
rows["169:560997922"]="베스프리스투스의 히포그리프들은 당신을 빨리 목적지로 데려갈 것입니다. 다르나서스의 서쪽 부분에있는 포털을 통해 루트테라안 마을에서 그를 찾으십시오."
rows["169:640743966"]="래션 더 나일드는 아름다운 옷으로 유명합니다.$B$B그녀는 공예의실에서 일하고 있습니다. 건물 안으로 들어오는 동안 왼쪽으로$B$B지도에 위치를 표시해 줄게요"
rows["169:73110654"]="알거논이 공급을 유지한다면, 한 잔디도 찾아내지 않고 일할 수 있어. 자연의 기적을 다시 볼 필요가 없다면, 너무 빨리 될 수 없을 것이다."
rows["169:743854514"]="얼라이언스 군인들, 너무 용감하고, 너무 기마자리 (Scurry, scurry, scurr, scurry; 필사적)"
rows["169:779029907"]="엘룬은 밤의 엘프들에게 많은 선물을 주었습니다. 호드 항상 함께 가져오는 것."
rows["169:827860125"]="아제로스에서의 네파리안의 패배에 대해서 필시 들었을 것입니다... 그가 실패했다고는 하지만, 실험은 계속되고 있습니다. 제 주인님께서... 그분께서는 그분의 후계자가 시작했던 일을 계속 진행하고 계십니다."
rows["169:898323683"]="이제 전쟁이 활발히 진행되고 있는데, 호드와 얼라이언스의 능력 있는 전투원들이 부족하지 않았습니다.$B$B만약 우리가 서로가 서로를 못  ⁇ 다면..."
rows["169:930705744"]="물론 우리는 계획대로 전염병을 파견할거야 길니안들이 작은 승리를 누릴 수 있어"
rows["169:941391010"]="더 많은 훈련을 할 수 없는데, 네 스킬은 내 스킬보다 더 낫다."
