rows["170:1007500619"]="우리 두통을 덜어줄 수 있기를 바랍니다. 10명의 아들을 낳으려요.$B$B하지만, 아버지로서 우리는 해야 할 일을 합니다."
rows["170:1036055150"]="9-10까지 다 셀 수 있어$B$B<밀리는 손가락과 발가락을 세우고 있다.>$B$B한, 두, 세, 다섯, 여섯,  ⁇ ... 일곱, 여덟, 9-10!$B$B잠깐, 한 번 놓쳤어..."
rows["170:1043838507"]="이제 여러분 앞에 보세요. 아제로스의 가장 강력한 \"드루이드\" 중 하나, 화려한 껍질만 줄어들었습니다. 이것이 판달 스태겔름의 뜻입니다. 그것이 불의 뜻입니다."
rows["170:1098602510"]="조세타는 이 마을에 축복이 되었어요. 지역 경비원들의 도움으로요. 만약 당신이 그녀를 사제들의 훈련에 따라 찾아보시면,"
rows["170:1139540497"]="그 해 동안 - 전쟁은 레지옹과 스컬지 우리 집들을 약탈하고 가족들을 죽였죠.\010"
rows["170:1145276180"]="이 둘을 감옥에서 풀어줄 주문이 생겼는데, 그 마법은 둘 다 풀려나갈 거야"
rows["170:1181168951"]="제 초청으로 왔어요, 메이저님 대부분의 파스트라이더들은 떠나서 쉽게 회수할 수 없습니다. "
rows["170:118260716"]="몇 달 후  ⁇ 은 더 끔찍한 소식을 가지고 돌아왔다. 그는 바다 바닥을 파는 거친 균열에서 뱀의 군대가 쏟아져 나오는 것을 보았다."
rows["170:1285763653"]="전쟁의 혼란이 당신을 미치게 했습니까? 내 도움으로 승리가 다가오고 있습니다. 내 도움 없이는, 당신의 싸움은 어려울 것입니다."
rows["170:1306525340"]="유리부시 왜성 중 한 명이 보석공자라는 걸 확신합니다.\010남편인 것 같아요, 둘 다 탐험가예요."
rows["170:133702357"]="우리 모두에게 어둡고 힘든 시기가 아닐 수 없습니다. 스컬지 군대는 남쪽에 모여들었고, 전장에서는 동료가 쓰러져 잠시 후에는 우리 적의 편이 되어 몸을 일으키고 있습니다."
rows["170:1368069876"]="엘드레 타라스의 궁전과 홀에서 방황하는 고위성 귀신들은 고르도크 오그레스나 사타르를 침략한 것이 아니라 왕자 스스로 살해당했습니다!"
rows["170:1403000110"]="여행자님, 당신의 지식은 위대합니다. 당신은 나보다 더 지혜로운 사람에게서 배워야 합니다. 요제프 그레고리안의 지혜에 대해 많은 이야기들이 전해졌습니다. 당신은 언더시티에서 그를 찾을 수 있습니다."
rows["170:1436933359"]="스톰윈드 및 오그리마의 포털과 다양한 전투장들은 달라란의 얼라이언스 및 호드 분지에서 발견 될 수 있습니다. 은 엔클래브와 선레버의 성당."
rows["170:1513799891"]="하지만 그와 그의 Twilight Masters는 분노와 전쟁을 위한 요소가 없다는 것을 이해하지 못했지만"
rows["170:1559097535"]="검의 두 명의 마스터: 핸디어와 우 핑. 전자는 에크소다르의 트레이더 계층에서 발견 될 수 있으며 후자는 스톰윈드 내에서 웰러의 아스널에서 찾을 수 있습니다."
rows["170:158211110"]="서쪽에서, 맨티드 붐이 일어납니다.$B$B북서쪽에서 모가들은 어두운 예술을 연습합니다.$B$B북쪽에서 야롱들이 우리를 압박합니다.$B$B할 일이 너무 많고 시간이 너무 적습니다."
rows["170:1636156292"]="이 Twilight들에게 조금만 공로를 인정해야 합니다. 그들은 실력에서 부족한 것을 보완하고, 숫자와 끈기로 보완합니다."
rows["170:1639714593"]="마스터의 그림자는 이 세상을 덮고 있습니다. (암, 모든 어둠) 우리의 적들은 고산지를 넘어서 서로 싸우고 있습니다. 바보들. (피, 피.)"
rows["170:166480871"]="들은 대로군. 그 아버지에 그 아들이라니... 티리온 만큼이나 나약하군. 어쩌면 더 나약할지도 모르겠고 말이야. 내가 보낸 암살자가 티리온의 비참한 삶을 끝내주길 바랄 뿐..."
rows["170:1673690754"]="우리 같은 사람들을 방문하는 것보다 더 중요한 일이 있어. 하지만, 여기 있는 동안,"
rows["170:170928857"]="스컬지의 침습은 동부 플라그랜드에서 증가합니다. 모든 능력 있는 전사들은 그들의 침략의 물결을 막기 위해 필요합니다.$B$B남아있는 네크로폴리스의 수는: $2282W"
rows["170:1755926572"]="준비하세요, 경호원님, 얼마나 많은 침입자가 있는지 모르겠지만 헤드랜드는 점령되고 항구도시에서 차단되어 있습니다."
rows["170:176490680"]="안녕하세요, 그리고 Darkmoon Faire Staging Area에 오신 것을 환영합니다.$b$b이 포털은 당신을 암흑달의 요정으로 데려다 줄 것입니다.$b$b하지만 떠나기 전에 질문이 있다면, 제가 대답할 수 있습니다."
rows["170:179391341"]="월 축제의 가장 큰 축제는 무글라데에서 열리고 있습니다. 여행하기 너무 멀리 있다면, 지혜의 계곡에서 운송을 제공하는 드루이드가 있습니다."
rows["170:1807520965"]="티르스한테 사령관이 있어 내가라면 최대한 멀리 갈 거야 술이 너무 많이 마셨지만 마법은 늘처럼 강해"
rows["170:1824066343"]="고객 들 은 서열 을 밟아, 당신 이 앉으라고 말 할 때 까지 기다립니다. 그들은 떠나기 전 에 잠시만 기다리실 것 입니다. 따라서 그들이 떠나기 전에 그들을 앉게 해 주십시오."
rows["170:1878667791"]="만약 당신이 좋은 금속을 무기와 갑옷으로 만들 수 있는 힘을 가지고 있다고 생각한다면 호드 라저힐 북서쪽에서 온난한 동굴 옆에 있는 듀크를 찾아라"
rows["170:189882810"]="자자, 이 여관에 있는 모든 사람들, 소리를 낮추지 않으면 이 주방장 예센이 식칼을 들고 달려나올 겁니다! 내 말 알아들었소?!!!"
rows["170:2027468813"]="Twilight's Hammer는 내게는 조직이 아니라 가족입니다.$B$B그래서 저는 유리한 후보가 훈련 단계를 통과하지 않도록 매우 조심합니다."
rows["170:2057492273"]="그 드워프는 콰르릉거리는 굉음을 내며 앞으로 나갔고, 번쩍이는 금속 망치를 휘두르며 그 빛으로 길을 밝혔습니다. 그러면서 요르문가르의 창자 속으로 들어갔지요."
rows["170:2070821742"]="음, 음, 당신은 약물을 만드는 데 약간의 기술을 가지고 있다고 볼 수 있습니다. 당신이 제 학생이 될 가치가 있는지 여부는 아직 밝혀지지 않습니다."
rows["170:2073674947"]="시간과 공간의 이 파열은 악명 높은 것 같습니다. 다양한 장면들이 무서운 속도로 지나가고 있습니다. 매우 용감한 사람이 적절한 시간에 뛰어내려도..."
rows["170:2084120549"]="물 원자체는 불 원자와 전쟁을 벌이고 있어, 이는 그들이 우리와 전쟁을 벌이고 있다는 뜻입니다."
rows["170:2123429797"]="고난의 거리로 갑시다. 한 가지 미리 알려드리자면 샤트라스는 아웃랜드에 남아 있는 몇 안 되는 안전한 피난처이기 때문에 과거에 벌어진 전쟁이나 현재 진행 중인 전쟁을 피해 많은 난민이 몰려들고 있습니다."
rows["170:231075586"]="기본 가죽 작업 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 이 일을 포기 하기 를 선택 한다면, 기본 가죽 작업 을 필요로 하는 모든 요리법 을 잊을 것 입니다."
rows["170:280151966"]="오랜 세월의 옛 적인 악마들은 다시 짐승의 얼굴을 보여 주지만 흔들리지 마요 두려움은 그들의 많은 무기의 하나이고 가장 치명적인 무기가니까요"
rows["170:39100232"]="레더볼 리그에 참가하고 싶으세요? $B$B이 셔프 후 우리로 가자"
rows["170:407495371"]="북쪽의 우리 큰 집 썬더 블러프 에 한 수강자 가 있다. 그러한 지식을 찾고 있다면 그곳으로 가서 블럭워치 중 한 명에게 방향을 물어보십시오."
rows["170:439192695"]="난 이런 두꺼운 안개가 본 적 없어 보람을 내려놓고 지나갈 때까지 기다려야 돼 오늘 바르나클을 지저리 암초에 떠나는 생각은 별로 좋아하지 않아"
rows["170:455338538"]="폭발하는 화산에서 벗어나 오크들과 마지막 공격에 나설 수 있을 거야"
rows["170:474696356"]="내 고향에서 좋은 친구에게 가장 큰 선물은 나무였습니다.$B$B왜 그런지 아세요?$B$B나무 는 평화, 성장, 생명 을 상징 한다."
rows["170:500241613"]="저는 해변을 지키기 위해 보병을 요청했습니다. 그리고 호드는 이 작은 작은 사람들을 그들의 작은 금속 튜브와 함께 보냈습니다.$B$B그라록은 경멸의 눈으로 근처의 괴물들을 바라보고 있습니다."
rows["170:515851317"]="내가 그랬던 것처럼 어떤 오크도 전투에서 도망쳐서는 안 돼 내 수치심에 대해 말해주지 마 내가 이 탑에서 죽으면 좋겠어"
rows["170:592114913"]="스코른과 다른 곳에서 총알을 쏘는 거였는데, 어떻게 된 거야?$B$B캐논볼 복원 임무!$B$B내가 계약한건 아니잖아"
rows["170:627949951"]="참전용사 성투자자께서 오크시스를 막으실 수 있습니다. 무슨 일이죠? 나랑 문제가 있나요? 아레나로 데려가세요. 저는 여러분의 작은 \"조단\"과 \"연맹\"에 시간을 낭비하지 않습니다."
rows["170:65601409"]="그래, 트롤 아르타스를 죽이는 시간이야 내 외과 의사도 데려가줘 스컬지 널 향해 던질 거야"
rows["170:672473826"]="더 이상 가르쳐 줄 게 없어요. 하지만, 할 수 있는 밤 엘프에 대해 들어봤어요. 그녀의 이름은 아이네틸이고, 그녀는 다르나서스의 공예인 테라스에서 살고 있습니다."
rows["170:726030619"]="성전의 수호자들은 땅에 굳게 서 있고, 구름 뱀의 질서가 위에서 싸우고 있습니다."
rows["170:735414268"]="하지만 몇 세기 후, 젊은 탐험가 중 한 명이 야외에서 무엇이 있는지 확인하기로 결정했습니다. 그의 이름은  ⁇ 랑이었습니다. 그리고 그는 전 세계를 발견하기 위해 떠났습니다."
rows["170:739020704"]="우리 전투는 가장 어려운 거야, 태 ⁇  의 의심의 심장은 미묘하고 속임수다 한 번 의심의 어두운 씨앗이 심으면 강한 마음과 마음이 있는 사람만이 그것을 제거할 수 있어"
rows["170:760583031"]="스터글스톤의 트롤들은 다크스피어에게 너무 친절하지 않아요. 난 블러드스칼프나 스켈플리터에 두려워하지 않아요. 하지만 여전히..."
rows["170:772973991"]="전쟁의 물결이 다시 왔습니다. 추운 북쪽에서, 리치 왕의 시골들이 우리 땅을 포위했습니다. 그는 비행하는 시골들을 보내서 전 세계를 침략합니다."
rows["170:81503334"]="이 모가 신성 벨을 숨긴 곳 봤어? 나는 즉시 사자 착륙에 알리겠다. 우리는 가로쉬 전에 이 물건을 얻을 필요가 있습니다. 우리가 그것을 발견하자마자 연락!"
rows["170:85326946"]="우리의 죄수는 이상하고 무기를 들고 있지 않아$b$b운이 좋으면 소중한 사람을 잡을 수 있을지도 몰라"
rows["170:888125907"]="한때 타이탄이 만든 돌이 들어있었는데, 이 돌은 세계 기둥이라고 불리곤 했었죠."
rows["170:966110524"]="이 상자에는 코크론의 표적이 있습니다. 다양한 무기와 다른 전쟁 물품이 동굴에 흩어져 있습니다."
rows["171:1000554480"]="마침내 그들을 쫓아냈어, 힘의 계곡에 있는 노르사라 지구맨더에게 태블릿을 가져와"
rows["171:1009987591"]="제 상품은 전투에서 자신을 증명한 사람들에게만 있습니다. 호드 내가 널 맡기기 전에 쓰레기를"
rows["171:1010288866"]="많은 사람들이 훌륭한 맥주라는 것은 요리에서 마시는 것과 똑같이 적용된다는 것을 잊습니다. 파다리아 전체에 있는 모든 것은 유명한 꿀 ⁇   ⁇ 어 생선과 비슷합니다!"
rows["171:1019603486"]="당신의 세계 샤만은 갈망과 욕망의 도 vórtex이 되었습니다. 그의 심장이 그 근처에 있는 모든 것을 삼키는 방법을 보세요. 여행자, 가볍게 걷어, 그렇지 않으면 당신은 또한 소비됩니다."
rows["171:1069271941"]="그래, 모든 사람들이 트램을 타고 가고 싶어 하니까 진짜 핫도그 기술공 시는 아이언포지."
rows["171:1138068488"]="줌, 지프, 그리고 BAM! 그는 배의 항구에서 만든 거대한 두 손 클리버를 가지고 있었을지도 모르지만"
rows["171:1293389855"]="방위 격차는 이 길이고 맨티드는 스카우트를 지나가며 바리케드를 돌고 있습니다.$B$B우리가 둘러싸여 있기 전에 그들을 차단해야 합니다."
rows["171:1377619469"]="당신도 이것만은 인정해야 하오. 당신이 변절자들로부터 얻은 정보는 오래된 것이고 확실하지도 않소이다. 우리는 치밀하게 계산된 전술을 바탕으로 마나괴철로를 공격하여 최대한 많은 정보를 캐내야 하오."
rows["171:1461153629"]="너네들은 정말 위대한 영웅이야 엘윈 숲 그리고 서부 몰락지대 앞으로 몇 년 동안 당신의 승리에 대해 칭찬을 드리겠습니다."
rows["171:1503061272"]="내가 널 지지하지 않을거야 네가 싸우지 않으면\010경비원한테 가서 싸우겠다고 말해"
rows["171:1504778630"]="당신은 새로운 요리사가군요. 배리플로어에서 필요한 모든 것을 찾을 수 있습니다. 그녀는 가구장에서 재화를 판매합니다.$B$B지도에 위치를 표시해 줄게요"
rows["171:1595623107"]="어서, 가끔 농장에 올 수도 있겠어."
rows["171:1622433665"]="오마리온은 어느 날 밤 사라졌어요. 바람에 발짝처럼... "
rows["171:1647473223"]="순례자의 보너스는 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간입니다.$B$B우리는 우리의 귀족 동맹국들이 함께 축하하고 축하하기를 바랍니다."
rows["171:1735478124"]="우리가 고통받으면서 우릴 배신한 드레네이와 거래해야 할까요?$B$B진심한 영이 이렇게 말하지 않나니 사기꾼아, 너 를 보내신 자 누구냐?"
rows["171:1791196457"]="내 한정된 능력을 뛰어넘어 다르나서스더 많은 것을 가르쳐 줄 수 있어."
rows["171:1805605489"]="지나, 시장에서 있는 여자?$b$b그 귀여운 작은 걸 직접 돈을 모러 오라고 말해줘"
rows["171:1855829888"]="난 이 땅에 온 건 괴로운 영혼을 깨끗하게 하기 위해서였지만 공격 후 난 내 임무가 실패했다고 두려워"
rows["171:1860313852"]="난 이 팀에 새로 들어왔어$b$b트롤을 죽이고, 그로그를 마시면 충분해요\010"
rows["171:1884699853"]="어글러스 쿼터마스터를 찾고 있는 건가?$B$B지도에 위치를 표시해줄게요"
rows["171:1896810050"]="신형 형제 여러분, 이 악마들을 물리치세요. 여러분의 세계 때문에요. 여기 서십시오."
rows["171:1903925596"]="훈련하고 싶으세요? 저랑요? 환상적이죠. 총알과 폭발기구를 집어 넣는 것보다 더 좋은 것은 그 지식을 다른 사람과 공유하는 것입니다. 시작하자!"
rows["171:1936372073"]="이 영유아는 살아갈 것 이다. 사랑 과 애정 으로 그들은 호드 의 강렬한 구성원 들 로 성장 할 것 이다. 그리고 시간이 지남 으로 그들의 파괴 된 생활 의 끔찍한 기억 들 은 사라질 것 이다."
rows["171:1950864549"]="잘 해, 하지만 가장자리에 조금 힘들어. 걱정마, 연습도 함께 할거야."
rows["171:1987262809"]="이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이 얼굴에  ⁇ 어  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 이"
rows["171:2019450843"]="고위사령관 아벤디스가 북으로 온 일은 실수였고, 우리 모두 죽은 목숨이라고 내게 직접 말했다! 모두 무기를 내려놓고 더 늦어지기 전에 떠나라!"
rows["171:2030580905"]="이 숨겨진 경로에서 아래의 적들에게 공포를 비울 수 있습니다.$B$B타격과 달리는 공격은 큰 명예가 없지만 좋은 전사가 적을 균형에서 벗어나게 하는 법을 알고 있습니다."
rows["171:2065786653"]="우리는 모두 끔찍한 비극을 목격했지만, 우리는 절망에 빠지도록 허용해서는 안 됩니다.$B$B대신 그 기억을 잘 기억해 두면 언젠가는 계산을 할 수 있을 겁니다."
rows["171:2071733249"]="화재는 모든 것을 파괴할 위협을 오그리마만약 당신이 거기에 들어갈 만큼 강하다고 생각한다면, 내 게을리 해. 그렇지 않으면, 도시에서 벗어나서 우리가 처리해 줄 수 있다."
rows["171:230045188"]="저는 보통 그런 일을 기둥에게 맡깁니다. 만약 당신이 직업을 취득하고 싶다면, 저는 당신이 훈련할 수 있는 기둥들을 스톰윈드에서 찾을 수 있을 것이라고 확신합니다."
rows["171:282745098"]="환영합니다. 순례자의 보너티 파티에 함께 오셨나요?$B$B모든 것을 시도해 보세요. 저는 여러분이 좋아하는 것을 발견할 것이라고 확신합니다."
rows["171:283493890"]="그래. 살아 있는 네놈들의 허약한 육체에도 무는 재주는 있단 말이지. 당분간 여기서 물러나마. 우리는 돌아올 것이다. 지금보다 훨씬 강해져서. 내가 돌아가면 너희의 보잘것없는 병력은 전멸을 면치 못할 것이다!"
rows["171:291557264"]="우리가 정복을 통해 빨리 비행할거야 호드 그들의 바람을 타고 가는 사람들을 위해 눈을 뜨게 해"
rows["171:341021024"]="저는 우리가 스스로 문제를 해결할 수 있다고 생각했습니다. 하지만 10천 년 동안 우리는 정지해졌고, 우리의 의심과 두려움은 땅에 묻혀 있었고, 우리가 허락할 때마다 더 심해졌습니다."
rows["171:347774365"]="똑똑한 트릭이긴 하지만 내가 널 싸울 수 있는 무기가 하나만 있다고 생각하니"
rows["171:354683448"]="이 문헌에 따르면, 멘은 황제 왕위를 악용한 가장 사악한 통치자였다고 합니다."
rows["171:429150235"]="가로쉬의 피에 대한 갈망이 채워지기 전에 얼마나 많은 사람들이 죽어야 할까요? 오그리마하지만 저는 여러분들이 제 편에 있는 영웅이 되어 기쁘습니다."
rows["171:460792177"]="어이, 친구들! 다들 잘 들어! 내가 남은 보물을 나눠 줄게! 구루바시 투기장에 궤짝을 놔둘 테니 가져가라고! 먼저 여는 자가 임자인 거 알지?"
rows["171:469577104"]="난 산의 바람을 불러 라그나로스의 불로부터 우리를 보호해 줄 것이다."
rows["171:487230890"]="우리가 이 사과들을 팔아야 하지만, 우리는  ⁇ 을 먹도록 허용하지 않을 것입니다. 오, 아니! 우리는 우리의 친구들에게 사과를 팔고, 그들은 나를 위해 과일 판매자에게 싸움을 가져오게 될 것입니다."
rows["171:512467289"]="이 문제에 대해 신중하게 생각해보세요. 만약 우리가 우리의 마술을 단순한 미적 향상에 쓸 수 있다면, 우리는 분명히 엄청난 힘을 가지고 있습니다."
rows["171:544776982"]="내 아들은 언제 좋은 여인을 만나게 될 거야?$B$B어떤 여자라도 냄새가 나가는 야커드 좀 원할까요?"
rows["171:567409954"]="수요의 탄력성에 비해 공급비 빼고 수익을 줄여서 재무와 채무를 회귀수분으로 기울인다고 생각해보세요."
rows["171:574876235"]="태양광선생들과의 친분이 보람을 얻었고, 저는 아웃랜드에서만 찾을 수 있는 주제들을 연구할 수 있었고, 그들은..."
rows["171:589763796"]="저는 이미 스타일에 대해 많이 알고 있습니다. 이제 그것은 그냥 가죽과 일하는 기술을 마스터하는 문제입니다. 다행스럽게도 사이먼은 그들을 배우는 데 도움이되는 진정한 스포츠입니다."
rows["171:621258926"]="고리판의 고리는 한때 영광과 명예의 장소였지만, 그 후 스팀위들 카르텔이 오르크 도끼보다 날카로운 금 기둥과 펜을 들고"
rows["171:644731223"]="최대한 짧고 간결하게 이야기 하마. 이리 와서 그냥 죽어라. 네가 한 짓에 대해 내가 해줄 수 있는 건 그것뿐이다. 이 신성한 전투의 장을 더럽힌 대가다."
rows["171:646508517"]="사람들이 다채로운 달걀을 찾아 흙에 뿌리를 내리고 싶어한다면 내가 누가 판단해야 할까요?"
rows["171:707080060"]="몇 주 동안 이런 것들을 어떻게 불러야 하는지 알아봤는데 내가 모르는 게 있다면"
rows["171:730041314"]="네가 강한다면, 나는 너를 존중한다.$b$b만약 여러분이 약해지면, 저는 여러분을 격려합니다.$b$b만약 당신이 내 적이라면, 내가 네 손에 拳을 붙여줄게"
rows["171:750667925"]="아뇨, 지휘관님, 하지만 저는 더 이상 작은 사람이 아닙니다. 저는 아버지를 찾아 왔습니다."
rows["171:766568736"]="우린 해냈네, 친구들! 봉우리에서 스컬지를 몰아냈다고! 서둘러 구스타프 신부에게 가서 이 좋은 소식을 전해 주게! 우린 여기서 정비를 하겠네. 어서 떠나게!"
rows["171:825629461"]="선입견이나 고대적 증오가 우리의 임무에 방해를 주지 마, 칼도레이."
rows["171:83365060"]="우리는 여기 숫자로 우월해 있습니다. 듀로타 하지만 한 오크가 가치가 있어요 10 얼라이언스 겁쟁이들$B$B이 패스에 담아서 돼지처럼 먹여 먹어"
rows["171:892920232"]="'그레이즈드 글래디에이터'가 '공평'을 막는 데 있어? '무슨? 너랑 문제가 있어? 아레나로 데려가라. 난 너의 작은 '조단'과 '연대'에 시간을 낭비하지 않는다."
rows["171:9344574"]="샤만?\010테라모어의 숙소에서 꽤 거친 외모의 왜구 소녀가 살고 있습니다. 나는 그녀가 그녀의 오래된 친구를 방문하기 위해 왔다고 믿습니다.\010그녀가 당신을 도울 수 있을지도 모릅니다."
rows["171:938575127"]=" ⁇ 비들이 왔을 때 마을의 아이들을 지켜보고 있었는데 공격은 멈췄지만 물려서 치료할 수 없었어요"
