rows["172:1133228123"]="짐승의 지혜와 지식을 살펴보고, 너는 자신을 보게 될 것이다. 오징어처럼 관찰하고, 사벌 고양이로부터 현명한 것을 배우며, 늑대의 강력한 정신을 구현한다."
rows["172:1237366158"]="그는 아마 우리가 Brawl'gar 아레나에서 가장 치명적인 싸운 선수입니다. 불행히도, 그는 그의 요소를 조금 벗어났습니다."
rows["172:1244943555"]="놀라운! 위대한 전사들의 혈통... 다른 세상, 그보다 덜! 판다렌이 고향을 떠나기는 드물다. 당신은 당신이 누구인지를 자랑스럽게 생각합니다."
rows["172:1294506533"]="엘룬의 힘은 당신을 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제로 강제 강제 강제로 강제 강제 강제로 강제 강제 강제로 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강제 강도 강도 강제 강제 강제 강제 강제 강도 강제 강제 강제 강도 강제 강제 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강도 강  \010지금 당장 가서 달의 성전의 중앙 홀에서 다르나서스의 남쪽 부분에서 자드리아를 찾아라!"
rows["172:1352076130"]="만약 우리가 쉐도우포지 시티에 있다면, 나는 당신의 범죄를 위해 법의 반지에 던져 주겠네, 대사 아이언포지 지금만 해도 충분할 것 같아요"
rows["172:1356392976"]="고마워, 챔피언! 호드 위기 처지에 있을지도 모르지만 이 해안에서의 여러분의 행동은 우리가 앞으로 어떻게 될지라도 생존과 번영을 계속할 수 있도록 해줬습니다."
rows["172:1359056030"]="바보 같은 놈! 이 성스러운 곳에 저 벌레 같은 것들이 날뛰도록 내버려두었더란 말이냐? 날 실망시켰다, 이그젝큐투스! 그 대가를 치러라!"
rows["172:1366816043"]="이 마녀들랑 갇혀 있는 건 참을 수 없어 이건 시'룬의 일이야 내 일이 아니야$b$b난 이 전투가 시작될 때까지 기다릴 수 없어 나 밖에 나가야 돼 용들과 함께"
rows["172:137018731"]="주식장인 자울 수는 본 건물에 들어가기 전에 대면 위에 서 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["172:1478531276"]="이 신성 벨이 숨겨진 곳을 봤어? 아주 잘 해. 가로쉬는 기뻐할 것입니다."
rows["172:1505377631"]="사람들은 항상 내 가족 관계를 승진하기 위해 사용한다고 비난하고$b$b게다가, 내가 다른 어떤 일에 가족을 쓸까?"
rows["172:1514733671"]="차가운 논리는 이 세상을 보전할 가치가 없다고 판단했다. 그러나 차가운 논리는, 자유 의지의 힘을 간과했다! 이제 우리가 증명해야 한다. 이 세상의 가치를!"
rows["172:1586968214"]="피알 시일렌트스트라이드는 블러드하프 마을의 최고의 요리사입니다."
rows["172:1659579722"]="괜찮소, 에드. 상자는 단단히 잠겨 있으니 걱정하지 마시오. 아무도 이 샌더스의 보물에 손대지 못하오! 자, 가서 한잔 더 합시다. 술기운이 떨어지는군."
rows["172:1674916291"]="내가 아는 유일한 무기로는 누군가를 죽이는 것 외에는 아무 것도 없다. 어떤 것을 아니라 누군가를. 이 칼은 인간의 생명을 끝내기 위해 발명되었다. 아름답지 않나요?"
rows["172:1706226956"]="만약 당신이 야수 카드의 덱을 완성할 수 있다면 당신은 파란색 용의 더 큰 암흑 달 카드로 보상될 것입니다. 이것은 마법의 에너지를 회복하는데 매우 유용합니다."
rows["172:1805588317"]="영웅들, 당신은 고집이 있잖아요? 당신의 동맹은 내 힘과 그의 힘을 비교하려고 노력했고 그 대가를 지불했습니다. "
rows["172:1815902135"]="타란 주가 병력을 보내지 않을 거야 우린 엄청난 군대를 가지고 있어"
rows["172:1824020393"]="내 계산에 따르면, 우리의 벽돌을 수리할 적절한 재료가 없으면 이 탑을 보호하는 벽은 12시간 안에 무너질 것입니다."
rows["172:1863263424"]="네가 찾는 건 주인님의 보금자리에 있지만, 들어가려면 티라누스를 이겨야 할 거야. 투영의 전당에서 서리한을 찾을 수 있어. 거기... 거기에 진실이 있어."
rows["172:1938237050"]="저 위에 텔라아르로 가는 길이 있습니다. 수렁피 일족 녀석들이 추가 병력을 보내서 우리를 추적할 게 뻔하니 갈림길이 나오면 찢어져서 가기로 합시다. 우리 중 한 명은 텔라아르로 돌아가야만 합니다."
rows["172:201819444"]="누가 이렇게 아름다운 것이 여기 숨어있다고 생각했을까?얼라이언스\"당신의 작품의 정밀한 절단으로 주변 세상을 변화시킬 수 있습니다\"."
rows["172:2052350247"]="자연에서 발견되는 허브는 존경과 결합하면 강력한 동맹이 될 수 있습니다. 당신은 그 중장 위에 있는 그녀의 화학 가게에서 베나를 찾아서 훈련을 더 진행하고 싶을 것입니다."
rows["172:2080552217"]="<신체가 매우 심하게 불태워 거의 반으로 물려졌어요>$B$B<붉은 용 비행은 아제로스의 모든 생명체의 보호자가 될 수 있지만 분명히 그들을 넘지 말아야합니다.>"
rows["172:2081244493"]="네 증오와 폭력, 의심의 냄새가 나니 네 영혼은 평생의 고난의 무게를 지고 있어 왜 망할 길을 따라 계속 갈 거야?"
rows["172:2101748345"]="넌 좋은 스포츠가 될 거 같아$b$b그 이유 때문에, 저는 이 \"Luckydo Kazoo\"를 떠나기로 합니다."
rows["172:2133104076"]="이 물에서 이렇게 쉽게 비전을 볼 수 있는 사람은 본 적 없어요.$B$B그런데도, 마지막엔 진 ⁇ 이 우리를 방문해서 물 속에 얼굴을 꽂은 건 기억나지 않아요."
rows["172:213930045"]="자, 시작하겠습니다. 진화 의식은 한 5분 정도 걸릴 겁니다. 제가 시작하면 졸개 녀석들이 접근하지 못하게 막아주십시오. 안 그러면 우리 모두 끝장입니다!"
rows["172:226367026"]="지옥의 소리, 난 드래곤마우의 자엘라야. 네 사람들이 제 사람들을 독재로부터 해방시켰어. 우리는 네 도구이다. 호드!"
rows["172:25429468"]="이 버섯은 겉으로는 다른 것이 아니라 그것을 먹는 사람들에게 지혜와 명확성을 가져다 준다고 합니다.$B$B스포레그르로 가져갈게"
rows["172:288639286"]="학카르의 종들아, 너희가 섬기는 신의 목소리를 들어라! 이 신성하고 거룩한 사원을 침입자들이 더럽히고 있나니! 피의 제단을 반드시 지켜야 한다. 죽여라! 전부!"
rows["172:303405872"]="곰 인간이 싸워서 나무 도시 되찾은 것처럼 언젠가 케켁도 광란심장 일족 집에 데려갈 수 있을까? 케켁 우리 집 갖고 싶다. 보라색 인간들 많은 도시 말고, 날름이들 많은 정글도 말고."
rows["172:312533916"]="티탄이 직접 창조한 발아니르는 첫 번째 토석인 왕 우렐 스톤하트에게 주어졌습니다. 스톤하트는 망치로 형제들을 창조하고 생명을 불어 넣었습니다."
rows["172:359527261"]="그만하시오. 나는 참으로 오랫동안 여기서 떨어져 있었소. 이 신전 안의 달샘은 단순히 영원의 샘의 희미한 그림자일지 모르나, 여전히 그 안엔 아름다움이... 순수함이 담겨 있소."
rows["172:359538693"]="변화의 바람은 끔찍한 폭풍에서 풍성한 수확까지 모든 것을 가져올 수 있습니다.$B$B이제, 내가 궁금한 것은, 당신은 폭풍이거나 작물인가?"
rows["172:433473024"]="아나테라가 쓰러지자 라테리온은 주위에서 일어나는 전투는 잊은 채 사랑하는 연인을 품에 안았지. 악마들은 그 아름다운 모습에도 아랑곳하지 않고 라테리온마저 죽여버렸소."
rows["172:538615519"]="브랜의 얼굴에 보이는 모습을 보고 싶지만, 그가 내가 왕에게 그린등을 준다는 걸 알면"
rows["172:560651905"]="난  ⁇ 을 만들지만, 불빛이 난 사람들에게는 간단하지만,  ⁇ 에 사용되는 재료가 얼마나 많은 영향을 미치는지 놀랄 것입니다."
rows["172:64277122"]="알렉스투스는 상처를 치료하는 데 능숙해 보니까 첫 번째 도움을 받는 것이 목표라면 왕실 교역 입구 근처의 노인도에서 찾아봐"
rows["172:698985834"]="미안하지만, 제가 가르칠 수 있는 한계에 도달했습니다. 더 배우고 싶다면, 다르나서스의 공예인 테라스에서 테론스를 보시기 바랍니다. 그는 꽤 재능이 있습니다. 그래서 저는 듣습니다."
rows["172:739172105"]="다른 숙련된 괴뢰 엔지니어와 대화하는 게 좋네요."
rows["172:745344286"]="보시다시피, 우리는 돌고래를 제거했습니다. 엄청난 인명 손실은 유감스럽지만 이제 트로그가 침투한 터널을 자유롭게 통과할 수 있습니다.$b$b- 환영합니다!"
rows["172:762069184"]="저는 당신이 그 일에 대해 말하는 게 싫어요. 전 모든 방면에서 당신과 동등합니다. 다음번에 세속의 소용돌이에 갇히면 도움을 요청해야 한다는 걸 명심하세요."
rows["172:805119031"]="스칼렛 홀은 내려갔고, 스칼렛 수도원은 아직 끝나지 않았다고$B$B내가 사라진다면 놀라지 마요. 빨리 가야 해요."
rows["172:871187288"]="여러 판다렌 그림으로 덮여 있는 오래된 서적."
rows["172:873507891"]="시나 선웨이버는 반응제 판매로 유명합니다. 건물 안으로 들어오는 좌측의 마스터 방에서 찾을 수 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["172:8823045"]="필멸의 존재여, 서리 군주님께서 이 세계에 오시는 것을 막지는 못하리라. 바다사냥꾼님이 휘두르는 권력이 라그나로스의 힘을 완전히 무너뜨리고, 네 땅을 동토의 왕국으로 만들리라!"
rows["172:975671599"]="물론 저는 참가자를 위해 악마를 소환하는 역할을 해요. 저는 윌프레드 피즐뱅, 소환의 대가랍니다! 악마들은 제 굳건한 의지에 속박되는 걸 상상만 해도 벌벌 떤다고요!"
rows["173:1019462439"]="우리는 물의 주인이니까 이 마을을 오랫동안 방어할 수 있었습니다. 하지만 육지에서, 특히 두꺼운 나무 덮개로, 호젠은 훨씬 우월합니다."
rows["173:1026936097"]="내 힘이 최고조에 달한 지금이라면 희생을 사용할 수 있도다. 이것을 사용해 다른 비룡들을 보호할 수 있지만, 내가 집중 공격을 받게 될 테니 꼭 교묘한 회피와 함께 사용하여라."
rows["173:1068536003"]="오그리마는 당신이 가야 할 곳입니다. 라저 힐에서 북쪽 도로가 바로 거기로 이어집니다. 거기 있는 그루트 중 한 명에게 이야기하면 더 많은 방향을 알려줄 수 있습니다."
rows["173:1071548412"]="그가 돌아오는 때마다 더 많은 판다레들이 류랑의 부르심을 받아 그의 성장하는 거북이에 합류했습니다. 그들은 우리들 중 가장 용감한 사람들이었습니다. 탐험가, 모험가"
rows["173:122038061"]="전설의 팔 안에 사요크와 한아시를 찾아라. 아니면 사요크가 너한테 한 조각을  ⁇ 거리는 개에게 줄 수도 있다."
rows["173:1269462132"]="이 곳에는 동물과 짐승들이 많고, 그 모든 동물들의 몸에서 튀어나오는 아름다운 전기 방출이 있습니다."
rows["173:1301459163"]="네, 내가 도와줄 수 없어, 네 능력은 내 능력보다 더 뛰어나고 있어! 더 배우고 싶다면, 다르나서스의 공예인 테라스에서 밤 elf Telonis와 이야기해봐! 그는 놀라운 사람입니다!"
rows["173:1354585187"]=" ⁇ '알로의 왼쪽 머리는 이렇게 말합니다.$B$B우리는 당신의 열정을 우리에게 도움이 가장 매력적인 ...$B$B<우측 머리가 끝나는 것>$B$B... 그리고 우리는 여러분의 노력을 매우 높이 평가하고 있음을 알려드리고 싶습니다!"
rows["173:1523763820"]="이 검이 저희에게 돌아온 건 이유가 있습니다. 이제 쿠엘델라를 든 자를 중심으로 다시 모여 실버문과 태양샘을 파괴한 복수를 해야 할 때가 온 겁니다."
rows["173:1633446747"]="오그리마에서 무슨 일이 일어나고 있는데, 그 모습은 마음에 들지 않습니다. 이 여성들은 사람들이 실망했다고 불평합니다. 다른 사람들은 세상이 끝날 것이라고 말합니다. 이것이 무슨 뜻일까요?"
rows["173:1719246765"]="악마들이 정정당당하게 싸울 것이라 생각하시오? 그 짐승들은 오크보다도 야만적이고 언데드보다도 교활하오. 일반적인 전쟁을 기준으로 불타는 군단과 맞서려는 생각은 버리시오."
rows["173:172026776"]="이상한 선택이지만 내가 판단할 수 있는 사람이 아니라고 생각하지만, 댄웨가 그 사람인데"
rows["173:1788072963"]="벡지크는 거대 혀를 찾는데 너무 멀리서 저기에 던져버리는 것을 좋아해요. 그는 멍청한 놈들을 잡을 수 있도록 도와줍니다."
rows["173:1788407240"]="공원 의 달수리 근처 에 테리든 이나 말드린 을 찾을 수 있습니다. 마지 구역 북쪽 에 있는 스톰윈드 서쪽 지역 으로 향 해 보세요."
rows["173:1818209685"]="전쟁과 고통을 백 년이나 견디어 왔다. 진정 필멸의 존재가 불멸의 존재에 맞서는 일이 현명하다고 생각하는가? 감히 말하건대 네 쪽이 잃을 것이 더 많으리라."
rows["173:1826372789"]="그나마 낫군. 상가에는 아직 불길이 번지지 않았다. 말가니스는 저 너머 십자군 광장에 있을 것이다. 이동할 준비가 되면 내게 보고해라."
rows["173:18631632"]="레지온에 의해 잡히면 \"Xar il romath da tidesbi\"라고 말해주세요. 그들은 그들의 신을 모욕한 것에 대해 즉시 당신을 죽일 것입니다."
rows["173:1885882843"]="만약 당신이 이 일을 맡기 준비가 되어 있다면, 당신은 배를 강화하고 결국 라그나로스의 손잡이를 깨뜨릴 필요가 있을 것이다!"
rows["173:1894789496"]="어스타야는 어업에 많은 시간을 보냈고, 몇 가지 기묘한 보물을 찾았습니다."
rows["173:1915473406"]="뭐? 그 오래된 마을 지하에 묘지가 있다고? 어리석게도 여태껏 그것도 모르고 있었다니! 반드시 그곳을 찾아서 네 주인을 쓰러트려 주겠다, 고드프리. 이 악몽을 반드시 끝내고야 말겠어."
rows["173:1964254665"]="제기랄! 피엉겅퀴에서 추출한 이 성분은 내 독과 잘 섞이지 않는군. 하지만, 절대 포기 안 해. 트롤들을 혼내주고 말 거야! 흠, 다른 혼합물이면 되지 않을까?"
rows["173:2056413195"]="방문하는 호드은 주로 달라란 북동부에 있는 선리버의 성원에 머물고 있다.$B$B거기에는 숙소가 있고, 다양한 전투장과 오그리마의 포털도 있다."
rows["173:2073196953"]="주인님께서 이 소식에 매우 기뻐하실 겁니다. 검은용군단에서 당신이 원하는 모든 걸 제공할 것임은 물론입니다. 필요하신 만큼 우리의 비룡에 오를 수 있겠군요."
rows["173:207657891"]="안 그래, 미안해, 많이 들어요$B$B<테일라는 재미있고 짜증나는 것 같네요>$B$B난 고위 엘프이지 피 엘프 아냐 걱정 마 마 마법을 빨아내지 않을거야"
rows["173:2135143946"]="네 발 아래의 땅은 살아 숨 쉬고 있어 지금 당신을 안정적으로 붙잡을 수 있지만 전쟁과 고통을 가져오면"
rows["173:244964534"]="앉으세요, 한 번 뒤집으세요$B$B부츠, B.O.O.M.의 믹스 전문가가랑 바텐더 특이원!$B$B발자국하면 올'보츠가 줄 수 있어"
rows["173:254616716"]="윌프레드 피즐뱅을 잃은 일은 안 됐지만, 흑마법으로 장난치는 자들에게는 교훈이 되었을 걸세. 아, 자네는 승리를 거뒀으니 다음 도전을 해야겠지."
rows["173:291331352"]="지금 제가 말했듯이 무례한 방해가 끝났으니, 콰그미란은 근처에 있습니다!$B$B약속대로, 마법의 축복으로 당신을 강화시킬 수 있습니다."
rows["173:359560543"]="우리는 몇 년 전부터 이 벌레들을 돌보고 있습니다. 저는 그들이 이 조직의 반구 행사에 맞춰서 적합해졌으면 합니다. 결국 당신은 한 가지가 아니라 두 개의 jormungar에 직면해야 합니다."
rows["173:372213993"]="카일의 래키들은 겸손의 교훈을 받을 겁니다. 우리는 Dawnblade 군대를 몰아내고,$B$B우리는 $3238w 퍼센트로 목표에 도달했습니다."
rows["173:529962863"]="내가 본 중에 당신이 최고로군. 내가 이런 말을 하다니 믿을 순 없지만 이제 스카이쉐터 대장과 겨룰 기회가 있을 거요. 아, 그렇지... 썩 잘 되지 못해도 내 편대 조종사가 될 수 있을 거요..."
rows["173:532192877"]="내 처지에 대해 더 많은 것을 알아내려고 노력하는 것은 거의 불가능했습니다. 우리를 고용한 밀수범은 사라졌고,"
rows["173:624242984"]="워치프, 분명히 노스렌드는 우리 민족에 대한 가장 심각한 위협을 나타내고 있으며, 우리는 그것에 맞서 행동해야 합니다. 하지만 이 적은 다른 적들과는 다릅니다."
rows["173:643254048"]="호드 전쟁선은 우리를 막았고 그들의 전사들은 용의 함락을 넘어서서 그들이 원하는 것을 가져갔고 협조하지 않는 사람들을 죽였죠."
rows["173:670503562"]="날 기억 안 나니? 스컬지내가 널 마조 마스타로 만든 모든 걸 지워버렸어"
rows["173:678172568"]="아레나 배틀마스터를 찾고 있어요?$B$B여기 묶어줄 수 있고, 수도권으로도 이동할 수 있습니다."
rows["173:679047343"]="우리의 도전은 겉모습을 넘어서 우리의 유사성을 이해하는 것입니다. 이러한 이해를 통하여, 우리는 다른 이들이 겪은 상실에 대하여 동정심을 느낄 수가 있답니다."
rows["173:723371107"]="오그리마 바깥에는 두 개의 제펠린 탑이 있다. 동쪽 탑은 티리스팔 숲와 스트랑글스톤밸리를 서비스하고, 서쪽 탑은 노스렌드와 썬더 블러프을 서비스한다."
rows["173:830513672"]="으히히... 알았어! 내가 졌다. 네놈들의 그 고귀하신 대마법사는 봉인된 공중 감옥에 갇혀 있다. 구하려고 해 봤자 열쇠는 살란드 님께서 직접 지니고 계시다. 네놈들은 바보짓을 하는 거야!"
rows["173:842606765"]="어떻게? 인간들은 참으로 어리석군. 안 그런가? 황혼의 인도자 텔잔 님이시란 말이다! 텔잔님은 리치시다! 인간의 뼈와 살에서 태어나 힘을 위해 모든 것을 희생한, 리치 왕의 가호를 받는 분이시란 말이다!"
rows["173:966327186"]="\"우리\"의 성공? 트롤, 당신은 노스렌드에서 호드의 승리를 위해 아무런 역할을 하지 않았습니다. 내가 우리 전사들을 리치 왕에 대항할 때, 당신은 단지 몇 개의 흩어져있는 섬을 되찾았습니다."
rows["173:986971444"]="아즈하라가 여왕이던 시절의 왕실의 도시 중 하나였죠. 이 도시에서 오래전부터 잃어버린 전통의 열쇠와 상상할 수 없는 역사적 가치가 있는 유물들이 있습니다. "
rows["174:1007467802"]="포메로이 씨는 알케미스트를 위해 허브를 수집합니다 북녘골 그리고 스톰윈드그의 집에서 그녀를 찾아서 그 직업을 보여줄 수 있는지 봐"
rows["174:1148642802"]="한번에 여러 적을 상대할 때는 불타는 격노를 사용하고, 내가 공격을 받기 시작하면 교묘한 회피를 사용하라. 단, 교묘한 회피를 사용하려면 먼저 공격을 받아 회피력을 충전해야 한다는 것을 기억해 두어라!"
rows["174:1168981554"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 호드 오크들 사이에서 전염병이 급속히 퍼지기 시작했어요."
rows["174:1193358672"]="노드와  ⁇ 은 잠수함에서 호드 공격당했어요\010하지만, 저는 그들의 모든 장비와 폭발물을 잘 활용했습니다.\010전선에서 방어 위치를 설정할 수 있습니다."
rows["174:1353108380"]="마법사라면, 아마 여기 가장 어두운 곳에 있을 거야."
rows["174:1464870511"]="이제 여기 거처하시는 군주님을 소환하겠다. 그분을 알현하면 너희 벌레 같은 목숨도 끝장날 것이다! 그때도 그런 배짱이 남아 있을지 어디 한번 보자!"
rows["174:1528042751"]="이 챔피언은 돌 용과 그들의  ⁇ 모를 두려움이나 의문의 단면을 보이지 않고도 마주했습니다."
rows["174:1548280703"]="정말 멋지네요, 정말 재밌었어요. 조금씩 더 많은 이 혐오스러운 잃어버린 사람들을 저주하고 있어요."
rows["174:1569708826"]="내 불만을 듣고 싶지 않아$b$b그냥 \"바다발\"과 \"오르는 방향으로 수영하는 능력\"을 가진 행운을 잊지 마세요."
rows["174:1637672778"]="천둥새는 아름답지 않나요?$B$B우리들 중 누구보다 이 땅이 더 가치가 있는 사람들이야$B$B여기 내가 기다리겠고 그들이 준비되면 날 데려갈 거야"
rows["174:1641266468"]="스 ⁇ 블레이드 사우로크에서 비롯된 혼란을 정리하러 왔어요$b$b그들의 일은 제가 익숙한 것과는 다른 종류의 혼란이지만,"
rows["174:1642858437"]="제 아는 한 사람만 있고 제 자신보다  ⁇ 을 잘 아는 사람인데"
rows["174:1677586493"]="내 STOUT은 그냥 스티어 던지기 위한 목표가 아니라 귀중한 훈련 수단입니다.$b$b날 때리지 마"
rows["174:1800605196"]="발굴을 포기하는 건 웃기죠. 오랜 공업 경력에서, 저는 결코 장소를 포기하지 않았습니다. 의도적으로 하지 않았습니다. 몇 가지를 놓쳤을 수도 있습니다. 당신은 또 누구입니까? 우리는 여기서 무엇을 하고 있습니까?"
rows["174:1923413352"]="경건하소서, 우리는 느슨하지 않고 얇아지고 있습니다. 모든 전선에서 포위하고 있습니다."
rows["174:1951409870"]="여기 있는 사람은 케그 타퍼 프로토타입에 대해 듣고 싶지 않을 것 같아요 74205 그리고 75633... 아마도 프로토타입에 대해 이야기한다면 1701-D, 흥분할 거야"
rows["174:1954653935"]="만약 당신이 미친 카드 팩을 완성한다면 더 큰 암흑달의 미쳤다는 상을 받게 될 것입니다."
rows["174:1985881738"]="안녕하세요 $p물은 너희 도착을 예언했지 불행히도 침략자들이 우리를 그렇게 공격할 것이라고 예측하지 못했어$b$b워터스피커  ⁇ 신입니다"
rows["174:2064491897"]="이 종파들은 단지 문제를 악화시키는데, 세상의 종말을 설교하거나,"
rows["174:228681100"]="|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t제국 비지르 조로크는 |cFFFF0000|Hspell:122740|h[변경]|h|r에 대한 그의 목소리를 사용하여 그의 편에서 싸우다!"
rows["174:275103562"]="드래곤 스칼라 가죽 을 만드는 일 을 잊는 것 은 가볍게 하는 일 이 아닙니다. 만약 그 일 을 포기 하기 를 선택 한다면 드래곤 스칼라 가죽 을 만드는 일 을 필요로 하는 모든 요리법 을 잊을 것 입니다!"
rows["174:414548305"]="넌 샤만의 한 명이야? 네, 네 길을 선택해 내버려 두게 될 거야. 그 길은 뭐든."
rows["174:51488792"]="내가 보냈어 순찰자 사리시 남쪽에서 순찰자 레트발린 서쪽에서 트랭킬린까지 하루 전에!"
rows["174:598540822"]="난 맹인 스쿠어트를 고용했나?$b$b이웃 스파크는 그들을 공룡이라고 부르지만 드래곤은 내가 볼 때 알아"
rows["174:602675855"]="다라란의 아레나와 그 서비스를 제공하는 사람들은 도시 아래로, 하수도에서 발견됩니다.$B$B적어도 세 가지 방법이 있습니다. 동쪽과 서쪽의 입구와 북쪽의 우물."
rows["174:610939387"]="아버지가 항상 말했듯이, 성공한 투자자가 되기 위해서는 현명한 마음과 급성한 본능, 그리고 끊임없는 용기가 필요합니다.$b$b인정해야 할건 이 기회를 한 마일 떨어진 곳에서 느꼈어요"
rows["174:628346470"]="거의 아무것도 아닌 곳에서 해적 제국을 건설하는 데 시간이 걸리지 않았습니다. 불모의 땅맨크릭의 아내랑 무슨 일이 있었는지 알아낸 사람이 있나요?"
rows["174:741494099"]="우리의 의무를 다한 후 아제로스의 인간들이 천 년 동안 살아남는다면, 그때야 비로소 우리의 시간이 헛되지 않았다고 말할 수 있을 것이다."
rows["174:878548477"]="나무에 대해 걱정하지 마, 그건 생명의 원입니다. 그들은 자라나고, 우리는 그들을 잘라서, 그리고 우리가 그것들을 사용하여 물건을 짓습니다!$b$b더 작은 원이 아니라 줄이 더 많다고 생각합니다."
rows["174:884950225"]="당신의 능력은 우리 예술에 대한 지속적인 애정을 보여 주지만, 당신의 헌신에 대한 더 많은 증거를 보고 싶습니다."
rows["174:919459544"]="스태프는 스톰윈드년] 웰러의 아스널에서 발견된 마스터 우 핑과 다르나서스년] 워리어 테라스에서 밤 엘프들을 훈련시키는 일리니아 문파이어 모두 가르친다."
rows["174:989487228"]="같은 동작을 여러 번 연속 수행 하면 작은 보너스 를 얻을 수 있습니다. 많은 고객 을 앉히거나 주문 을 순차적으로 배달 하는 것 으로 추가 포인트를 획득 할 수 있습니다!"
rows["175:1031661268"]=" ⁇ 은 엘라가 맥주 만드는 데 힘을 쏟고 있잖아, 잘 해줘"
rows["175:104793824"]="네놈들을 과소평가했나 보군. 모두를 한꺼번에 상대하라는 건 불공평한 처사지만, 나의 백성도 공평한 대접을 받은 적 없기는 매한가지. 받은 대로 돌려주겠다."
rows["175:1104682208"]="만약 당신이 선스파이어에서 에로나 사법부장관과 아직 대화하지 않았다면, 즉시 그렇게 해달라고 추천합니다. 긴급한 문제들이 있어, 우리 모두가 그렇듯이 그녀는 당신의 도움이 필요합니다!"
rows["175:113845915"]="기념관 은 아름답지 않습니까? 우리 역사 에서 큰 희생 을 받은 순간 을 기억 하는 것 은 중요 하다. 그렇게 하면 모든 전쟁 들 의 대가를 잊을 수 없읍니다. 심지어 승리 한 전쟁 들 도 마찬가지 입니다."
rows["175:1138619435"]="미안하지만, 더 이상 팔릴 유적이 없어서 마법을 꺼버린 것 같네요."
